async ({ shell }) => {
  const script = `tell application "Music"
set output to ""
repeat with playlistName in {"Library", "Music", "Recently Played"}
try
set p to playlist playlistName
set output to output & playlistName & tab & (count of tracks of p) & tab & (class of track 1 of p as string) & linefeed
on error errMsg number errNum
set output to output & playlistName & tab & errNum & tab & errMsg & linefeed
end try
end repeat
return output
end tell`;
  return shell.execFile("osascript", ["-e", script], { timeoutMs: 30000, maxBytes: 10000, maxLines: 100 });
}

