async ({ shell }) => {
  const [date, music] = await Promise.all([
    shell.execFile("date", ["+%A, %B %-d, %Y %H:%M:%S %Z"], { maxBytes: 1000, maxLines: 10 }),
    shell.execFile("osascript", ["-e", `tell application "Music"
set dayStart to current date
set time of dayStart to 0
set output to ""
repeat with t in tracks of playlist "Music"
try
set d to played date of t
if d ≥ dayStart then
set output to output & (d as string) & tab & (name of t) & tab & (artist of t) & tab & (album of t) & linefeed
end if
end try
end repeat
return output
end tell`], { timeoutMs: 120000, maxBytes: 50000, maxLines: 2000 })
  ]);
  return { date, music };
}

