async ({ shell }) => {
  const home = "/Users/example";
  const roots = [
    `${home}/Library/Music`,
    `${home}/Library/Containers/com.apple.Music`,
    `${home}/Library/Group Containers`,
    `${home}/Library/Caches/com.apple.Music`,
  ];
  const probes = await Promise.allSettled(roots.map(root => shell.execFile("find", [root, "-maxdepth", "5", "-type", "f", "(", "-iname", "*.sqlite", "-o", "-iname", "*.db", "-o", "-iname", "*.musicdb", "-o", "-iname", "*history*", "-o", "-iname", "*recent*", ")"], { timeoutMs: 30000, maxBytes: 20000, maxLines: 300 })));
  return probes.map((r, i) => ({ root: roots[i], ...(r.status === "fulfilled" ? r.value : { error: String(r.reason) }) }));
}

