async ({ shell }) => {
  const predicates = [
    `process == "Music" AND (eventMessage CONTAINS[c] "playback" OR eventMessage CONTAINS[c] "now playing")`,
    `(subsystem CONTAINS[c] "media" OR subsystem CONTAINS[c] "music") AND (eventMessage CONTAINS[c] "title" OR eventMessage CONTAINS[c] "track")`,
  ];
  const results = [];
  for (const predicate of predicates) {
    results.push(await shell.execFile("/usr/bin/log", ["show", "--start", "2026-08-12 00:00:00", "--end", "2026-08-13 00:00:00", "--style", "compact", "--predicate", predicate], { timeoutMs: 60000, maxBytes: 30000, maxLines: 300, truncate: "tail" }));
  }
  return results;
}

