async ({ shell }) => {
  const result = await shell.execFile("/usr/bin/log", ["show", "--start", "2026-08-12 07:58:00", "--end", "2026-08-12 07:59:00", "--style", "compact", "--predicate", `process == "Music" AND (eventMessage CONTAINS "Fantasy '82" OR eventMessage CONTAINS[c] "artist" OR eventMessage CONTAINS[c] "album")`], { timeoutMs: 60000, maxBytes: 30000, maxLines: 300 });
  const lines = result.stdout.split("\n").filter(line => /Fantasy '82|artist|album/i.test(line));
  return { lines: lines.slice(0, 120), totalMatchedLines: lines.length, stderr: result.stderr, truncated: result.truncated };
}

async ({ shell }) => {
  const command = `set -o pipefail; /usr/bin/log show --start '2026-08-12 00:00:00' --end '2026-08-13 00:00:00' --style compact --predicate 'process == "Music" AND subsystem == "com.apple.amp.mediaplaybackcore" AND (eventMessage CONTAINS "playbackTimeDidChangeTo - Regular item" OR eventMessage CONTAINS "Current song: contentIdentifier=")' | /usr/bin/python3 -c 'import sys,re,json
played=[]; seen=set(); titles={}; albums={}
for line in sys.stdin:
 m=re.search(r"playbackTimeDidChangeTo - Regular item .*?item=<ITMPAVItem:.*?> \\(([^)]+)\\) (.*?) - reason:",line)
 if m:
  cid,title=m.groups(); titles[cid]=title.strip()
  if cid not in seen: played.append(cid); seen.add(cid)
 m=re.search(r"Current song: contentIdentifier=([^ ,]+).*?album\\.identifiers=.*?storeAdamID=(\\d+)",line)
 if m: albums[m.group(1)]=m.group(2)
out=[{"contentId":c,"title":titles.get(c),"albumId":albums.get(c)} for c in played]
print(json.dumps(out,ensure_ascii=False))'`;
  const result = await shell.exec(command, { timeoutMs: 120000, maxBytes: 50000, maxLines: 20 });
  if (result.code !== 0) return result;
  const tracks = JSON.parse(result.stdout || "[]");
  return { count: tracks.length, withAlbumId: tracks.filter((x:any) => x.albumId).length, albumIds: [...new Set(tracks.map((x:any) => x.albumId).filter(Boolean))], missing: tracks.filter((x:any) => !x.albumId).slice(0, 30), stderr: result.stderr };
}

