async ({ shell, http }) => {
  const command = `set -o pipefail; /usr/bin/log show --start '2026-08-12 00:00:00' --end '2026-08-13 00:00:00' --style compact --predicate 'process == "Music" AND subsystem == "com.apple.amp.mediaplaybackcore" AND (eventMessage CONTAINS "playbackTimeDidChangeTo - Regular item" OR eventMessage CONTAINS "Current song: contentIdentifier=")' | /usr/bin/python3 -c 'import sys,re,json
played=[]; last=None; titles={}; albums={}; times={}
for line in sys.stdin:
 m=re.search(r"^(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}\\.\\d+).*?playbackTimeDidChangeTo - Regular item .*?item=<ITMPAVItem:.*?> \\(([^)]+)\\) (.*?) - reason:",line)
 if m:
  ts,cid,title=m.groups(); title=title.strip(); titles[cid]=title; times[cid]=ts
  if cid != last: played.append(cid); last=cid
 m=re.search(r"Current song: contentIdentifier=([^ ,]+).*?album\\.identifiers=.*?storeAdamID=(\\d+)",line)
 if m: albums[m.group(1)]=m.group(2)
out=[{"contentId":c,"time":times.get(c),"title":titles.get(c),"albumId":albums.get(c)} for c in played]
print(json.dumps(out,ensure_ascii=False))'`;
  const result = await shell.exec(command, { timeoutMs: 120000, maxBytes: 50000, maxLines: 20 });
  if (result.code !== 0) return { code: result.code, stderr: result.stderr };
  const tracks = JSON.parse(result.stdout || "[]") as Array<{contentId: string; time: string; title: string; albumId: string | null}>;
  const ids: string[] = Array.from(new Set(tracks.map(x => x.albumId).filter((x): x is string => Boolean(x))));
  const chunks: string[][] = [];
  for (let i = 0; i < ids.length; i += 20) chunks.push(ids.slice(i, i + 20));
  const responses = await Promise.all(chunks.map(chunk => http.request(`https://itunes.apple.com/lookup?id=${chunk.join(",")}`, { maxBytes: 50000 })));
  const albums = new Map<string, {artist: string; album: string}>();
  for (const response of responses) {
    const body = JSON.parse(response.body) as {results?: Array<{collectionId?: number; artistName?: string; collectionName?: string}>};
    for (const item of body.results || []) if (item.collectionId) albums.set(String(item.collectionId), {artist: item.artistName || "Unknown artist", album: item.collectionName || "Unknown album"});
  }
  const enriched = tracks.map(t => ({ time: t.time.slice(11,16), title: t.title, artist: t.albumId ? albums.get(t.albumId)?.artist || null : null, album: t.albumId ? albums.get(t.albumId)?.album || null : null }));
  return { count: enriched.length, enriched, metadataAlbumsFound: albums.size, albumIds: ids.length };
}

