async function getAppleMusicListeningHistory(
  { shell, http },
  input: { date?: string; includeMetadata?: boolean; minObservedSeconds?: number } = {},
) {
  const requestedDate = input.date;
  const includeMetadata = input.includeMetadata !== false;
  const minObservedSeconds = Math.max(0, input.minObservedSeconds ?? 0);

  if (requestedDate && !/^\d{4}-\d{2}-\d{2}$/.test(requestedDate)) {
    throw new Error("date must use YYYY-MM-DD format");
  }

  const date =
    requestedDate ||
    (
      await shell.execFile("/bin/date", ["+%F"], {
        maxBytes: 1000,
        maxLines: 5,
        raise: true,
      })
    ).stdout.trim();

  const [nextDateResult, timezoneResult] = await Promise.all([
    shell.execFile("/bin/date", ["-j", "-f", "%Y-%m-%d", date, "-v+1d", "+%F"], {
      maxBytes: 1000,
      maxLines: 5,
      raise: true,
    }),
    shell.execFile("/bin/date", ["+%Z"], { maxBytes: 1000, maxLines: 5, raise: true }),
  ]);
  const nextDate = nextDateResult.stdout.trim();
  const timezone = timezoneResult.stdout.trim();

  const python = `import sys,re,json
tracks=[]
albums={}
current=None
for line in sys.stdin:
    a=re.search(r"Current song: contentIdentifier=([^ ,]+).*?album\\.identifiers=.*?storeAdamID=(\\d+)",line)
    if a:
        albums[a.group(1)]=a.group(2)
    m=re.search(r"^(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}\\.\\d+).*?time:([0-9.]+)s .*?item=<ITMPAVItem:.*?> \\(([^)]+)\\) (.*?) - reason:",line)
    if not m:
        continue
    timestamp,position,cid,title=m.groups()
    position=float(position)
    restarted=current is not None and cid==current["contentId"] and position < 2 and current["maxPosition"] > 30
    if current is None or cid!=current["contentId"] or restarted:
        current={"startedAt":timestamp,"lastEventAt":timestamp,"contentId":cid,"title":title.strip(),"maxPosition":position}
        tracks.append(current)
    else:
        current["lastEventAt"]=timestamp
        current["maxPosition"]=max(current["maxPosition"],position)
for track in tracks:
    track["albumId"]=albums.get(track["contentId"])
    track["secondsObserved"]=round(track.pop("maxPosition"),1)
print(json.dumps(tracks,ensure_ascii=False,separators=(",",":")))`;

  const predicate = `process == "Music" AND subsystem == "com.apple.amp.mediaplaybackcore" AND (eventMessage CONTAINS "playbackTimeDidChangeTo - Regular item" OR eventMessage CONTAINS "Current song: contentIdentifier=")`;
  const command = `set -o pipefail; /usr/bin/log show --start '${date} 00:00:00' --end '${nextDate} 00:00:00' --style compact --predicate '${predicate}' | /usr/bin/python3 -c ${JSON.stringify(python)}`;
  const logResult = await shell.exec(command, {
    timeoutMs: 120000,
    maxBytes: 51200,
    maxLines: 20,
    raise: true,
  });
  if (logResult.truncated) {
    throw new Error("Playback history exceeded the safe output limit; query a smaller interval.");
  }

  type RawTrack = {
    startedAt: string;
    lastEventAt: string;
    contentId: string;
    title: string;
    albumId: string | null;
    secondsObserved: number;
  };
  const rawTracks = JSON.parse(logResult.stdout || "[]") as RawTrack[];

  const albumMetadata = new Map<string, { artist: string; album: string }>();
  if (includeMetadata) {
    const albumIds: string[] = Array.from(
      new Set(rawTracks.map((track) => track.albumId).filter((id): id is string => Boolean(id))),
    );
    const chunks: string[][] = [];
    for (let i = 0; i < albumIds.length; i += 20) chunks.push(albumIds.slice(i, i + 20));
    const lookups = await Promise.allSettled(
      chunks.map((ids) =>
        http.request(`https://itunes.apple.com/lookup?id=${ids.join(",")}`, { maxBytes: 51200 }),
      ),
    );
    for (const lookup of lookups) {
      if (lookup.status !== "fulfilled" || !lookup.value.ok) continue;
      const body = JSON.parse(lookup.value.body) as {
        results?: Array<{ collectionId?: number; artistName?: string; collectionName?: string }>;
      };
      for (const item of body.results || []) {
        if (!item.collectionId) continue;
        albumMetadata.set(String(item.collectionId), {
          artist: item.artistName || "Unknown artist",
          album: item.collectionName || "Unknown album",
        });
      }
    }
  }

  const tracks = rawTracks
    .filter((track) => track.secondsObserved >= minObservedSeconds)
    .map((track) => {
      const metadata = track.albumId ? albumMetadata.get(track.albumId) : undefined;
      return {
        time: track.startedAt.slice(11, 19),
        title: track.title,
        artist: metadata?.artist || null,
        album: metadata?.album || null,
        secondsObserved: track.secondsObserved,
      };
    });

  type SessionWithEnd = { start: string; end: string; trackStarts: number; _end?: number };
  const sessions: SessionWithEnd[] = [];
  for (const track of rawTracks) {
    const started = new Date(track.startedAt.replace(" ", "T")).getTime();
    const ended = new Date(track.lastEventAt.replace(" ", "T")).getTime();
    const previous = sessions[sessions.length - 1];
    if (!previous || started - (previous._end || 0) > 30 * 60 * 1000) {
      sessions.push({
        start: track.startedAt.slice(11, 19),
        end: track.lastEventAt.slice(11, 19),
        trackStarts: 1,
        _end: ended,
      });
    } else {
      previous.end = track.lastEventAt.slice(11, 19);
      previous.trackStarts += 1;
      previous._end = ended;
    }
  }
  for (const session of sessions) delete session._end;

  return {
    date,
    timezone,
    trackStarts: tracks.length,
    totalTrackStartsBeforeFiltering: rawTracks.length,
    approximateObservedSeconds: Math.round(
      tracks.reduce((sum, track) => sum + track.secondsObserved, 0),
    ),
    sessions,
    tracks,
    source: "macOS unified logs for the Music playback engine",
  };
}

