async ({ shell }) => {
  const yesterday = (await shell.execFile("/bin/date", ["-v-1d", "+%F"], { maxBytes: 1000, maxLines: 5, raise: true })).stdout.trim();
  const history = await getAppleMusicListeningHistory({ date: yesterday, includeMetadata: true });
  const grouped = new Map<string, { title: string; artist: string | null; album: string | null; plays: number; observedSeconds: number }>();
  for (const track of history.tracks) {
    const key = `${track.title}\u0000${track.artist || ""}`;
    const current = grouped.get(key);
    if (current) {
      current.plays += 1;
      current.observedSeconds += track.observedSeconds;
    } else {
      grouped.set(key, { title: track.title, artist: track.artist, album: track.album, plays: 1, observedSeconds: track.observedSeconds });
    }
  }
  const top = [...grouped.values()]
    .sort((a, b) => b.observedSeconds - a.observedSeconds || b.plays - a.plays)
    .slice(0, 10)
    .map((track, index) => ({ rank: index + 1, ...track, observedSeconds: Math.round(track.observedSeconds) }));
  return { date: history.date, trackStarts: history.trackStarts, sampledPlaybackSeconds: history.sampledPlaybackSeconds, top, note: history.note };
}

