arguments.code:
async ({ shell }) => {
  const yesterday = (await shell.execFile("/bin/date", ["-v-1d", "+%F"], { maxBytes: 1000, maxLines: 5, raise: true })).stdout.trim();
  const history = await getAppleMusicListeningHistory({ date: yesterday, includeMetadata: true });
  const aliases: Record<string, string> = {
    "Super Strut": "Deodato",
    "Panopticom (Bright Side Mix)": "Peter Gabriel",
  };
  const grouped = new Map<string, { artist: string; observedSeconds: number; trackStarts: number; uniqueTracks: Set<string> }>();
  for (const track of history.tracks) {
    const artist = track.artist || aliases[track.title] || "Unknown artist";
    const current = grouped.get(artist) || { artist, observedSeconds: 0, trackStarts: 0, uniqueTracks: new Set<string>() };
    current.observedSeconds += track.observedSeconds;
    current.trackStarts += 1;
    current.uniqueTracks.add(track.title);
    grouped.set(artist, current);
  }
  const top = [...grouped.values()]
    .sort((a, b) => b.observedSeconds - a.observedSeconds)
    .slice(0, 10)
    .map((item, index) => ({
      rank: index + 1,
      artist: item.artist,
      minutes: Math.round(item.observedSeconds / 6) / 10,
      trackStarts: item.trackStarts,
      uniqueTracks: item.uniqueTracks.size,
    }));
  return { date: history.date, top, sampledPlaybackSeconds: history.sampledPlaybackSeconds, note: history.note };
}

