async ({ http }) => {
  const queries = [
    { artist: "Grupo Medusa", album: "Grupo Medusa" },
    { artist: "Marcos Resende & Index", album: "Marcos Resende Index" },
    { artist: "Antônio Adolfo", album: "Viralata" },
