    { artist: "Amaro Freitas", album: "Sankofa" },
    { artist: "Mildlife", album: "Automatic" },
    { artist: "Cortex", album: "Troupeau Bleu" },
    { artist: "Placebo", album: "Ball of Eyes Marc Moulin" },
    { artist: "Jiro Inagaki & Soul Media", album: "Funky Stuff" },
    { artist: "Neue Grafik Ensemble", album: "Foulden Road" },
  ];
  const responses = await Promise.all(queries.map(q => http.request(`https://itunes.apple.com/search?term=${encodeURIComponent(`${q.artist} ${q.album}`)}&entity=album&limit=8&country=US`, { maxBytes: 30000 })));
  return queries.map((q, i) => {
    const body = JSON.parse(responses[i].body) as { results?: Array<{collectionId:number; artistName:string; collectionName:string; trackCount:number; primaryGenreName:string}> };
    return { query: q, matches: (body.results || []).slice(0, 5) };
  });
}

