async ({ workspace }) => {
  const file = await workspace.read("/System/Applications/Music.app/Contents/Resources/com.apple.Music.sdef", { format: "raw" });
  const lines = file.content.split("\n");
  const indexes = lines.map((line, i) => /<command name="(add|duplicate|open location)|<property name="current track"|<class name="user playlist"/.test(line) ? i : -1).filter(i => i >= 0);
  const excerpts = indexes.map(i => lines.slice(Math.max(0, i - 3), i + 16).join("\n"));
  return { excerpts };
