async function populateAppleMusicCatalogPlaylist(
  { shell },
  input: {
    name: string;
    description?: string;
    albums: Array<{ url: string; tracks: string[] }>;
    ifExists?: "reuse" | "error" | "createUnique";
    dryRun?: boolean;
    loadTimeoutSeconds?: number;
  },
) {
  if (!input.name?.trim()) throw new Error("playlist name is required");
  if (!input.albums?.length) throw new Error("Provide at least one album selection.");
  const requestedName = input.name.trim();
  const mode = input.ifExists || "reuse";
  const timeoutSeconds = Math.max(5, Math.min(60, input.loadTimeoutSeconds || 20));
  const plan = input.albums.flatMap(album => album.tracks.map(title => ({ albumUrl: album.url, title })));
  if (input.dryRun) return { dryRun: true, requestedName, plannedTracks: plan.length, plan };

  const asAppleString = (value: string) => `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
  const accessibility = await shell.execFile("osascript", ["-e", `tell application "System Events" to tell process "Music" to return count of windows`], { timeoutMs: 15000, maxBytes: 1000, maxLines: 10 });
  if (accessibility.code !== 0) throw new Error(`Music UI automation is unavailable: ${accessibility.stderr || accessibility.stdout}`);

  const createScript = `tell application "Music"
set requestedName to ${asAppleString(requestedName)}
set actualName to requestedName
if exists user playlist actualName then
if ${asAppleString(mode)} is "error" then error "Playlist already exists: " & actualName number 409
if ${asAppleString(mode)} is "createUnique" then
set suffix to 2
repeat while exists user playlist actualName
set actualName to requestedName & " " & suffix
set suffix to suffix + 1
end repeat
set p to make new user playlist with properties {name:actualName, description:${asAppleString(input.description || "")}}
else
set p to user playlist actualName
if ${asAppleString(input.description || "")} is not "" then set description of p to ${asAppleString(input.description || "")}
end if
else
set p to make new user playlist with properties {name:actualName, description:${asAppleString(input.description || "")}}
end if
set output to actualName & linefeed
repeat with t in tracks of p
set output to output & (name of t) & linefeed
end repeat
return output
end tell`;
  const created = await shell.execFile("osascript", ["-e", createScript], { timeoutMs: 30000, maxBytes: 30000, maxLines: 1000, raise: true });
  const existingLines = created.stdout.trimEnd().split("\n");
  const playlistName = existingLines.shift() || requestedName;
  const existing = new Set(existingLines.filter(Boolean));
  const added: string[] = [];
  const skipped: string[] = [];
  const missing: string[] = [];
  const albumsFailed: Array<{ url: string; reason: string }> = [];

  for (const album of input.albums) {
    const wanted = album.tracks.filter(title => {
      if (existing.has(title)) { skipped.push(title); return false; }
      return true;
    });
    if (!wanted.length) continue;
    await shell.execFile("open", ["-a", "Music", album.url], { timeoutMs: 10000, maxBytes: 1000, maxLines: 10, raise: true });

    let loaded = false;
    for (let attempt = 0; attempt < timeoutSeconds; attempt++) {
      await new Promise(resolve => setTimeout(resolve, 1000));
      const probeScript = `tell application "Music" to activate
delay 0.2
tell application "System Events"
tell process "Music"
try
set sg to UI element 2 of front window
set mainList to UI element 1 of UI element 4 of sg
set trackSection to UI element 2 of mainList
repeat with e in UI elements of trackSection
try
if description of e is ${asAppleString(wanted[0])} then return "yes"
end try
end repeat
end try
return "no"
end tell
end tell`;
      const probe = await shell.execFile("osascript", ["-e", probeScript], { timeoutMs: 15000, maxBytes: 1000, maxLines: 10 });
      if (probe.stdout.trim() === "yes") { loaded = true; break; }
    }
    if (!loaded) {
      albumsFailed.push({ url: album.url, reason: "Album page did not expose the expected track rows." });
      continue;
    }

    const addScript = `tell application "Music" to activate
delay 0.3
tell application "System Events"
tell process "Music"
set wantedTracks to {${wanted.map(asAppleString).join(", ")}}
set output to ""
set sg to UI element 2 of front window
set mainList to UI element 1 of UI element 4 of sg
set trackSection to UI element 2 of mainList
repeat with wantedTrack in wantedTracks
set wantedName to wantedTrack as string
set foundIt to false
repeat with e in UI elements of trackSection
try
if description of e is wantedName then
set foundIt to true
set moreButton to first button of e whose description is "More"
perform action "AXPress" of moreButton
delay 0.35
keystroke "Add to Playlist"
delay 0.2
key code 124
delay 0.35
keystroke ${asAppleString(playlistName)}
delay 0.2
key code 36
delay 0.55
set output to output & "ADDED" & tab & wantedName & linefeed
exit repeat
end if
end try
end repeat
if not foundIt then set output to output & "MISSING" & tab & wantedName & linefeed
end repeat
return output
end tell
end tell`;
    const result = await shell.execFile("osascript", ["-e", addScript], { timeoutMs: 120000, maxBytes: 20000, maxLines: 500 });
    for (const line of result.stdout.split("\n")) {
      const [status, title] = line.split("\t");
      if (!title) continue;
      if (status === "ADDED") { added.push(title); existing.add(title); }
      if (status === "MISSING") missing.push(title);
    }
    if (result.code !== 0) albumsFailed.push({ url: album.url, reason: result.stderr || "UI automation failed." });
  }

  await new Promise(resolve => setTimeout(resolve, 1500));
  const verifyScript = `tell application "Music"
set p to user playlist ${asAppleString(playlistName)}
set totalDuration to 0
repeat with t in tracks of p
try
set totalDuration to totalDuration + (duration of t)
end try
end repeat
return (count of tracks of p as string) & tab & (round totalDuration as string)
end tell`;
  const verified = await shell.execFile("osascript", ["-e", verifyScript], { timeoutMs: 60000, maxBytes: 2000, maxLines: 20, raise: true });
  const [countText, durationText] = verified.stdout.trim().split("\t");
  const totalSeconds = Number(durationText) || 0;
  return {
    dryRun: false,
    name: playlistName,
    added,
    skipped,
    missing,
    albumsFailed,
    trackCount: Number(countText) || 0,
    totalSeconds,
    duration: `${Math.floor(totalSeconds / 3600)}:${String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, "0")}:${String(totalSeconds % 60).padStart(2, "0")}`,
  };
}

