async ({ shell }) => {
  const description = "Built from your recent Azymuth, Banda Black Rio, Marcos Valle, João Donato and Yussef Kamaal listening. Grupo Medusa and Marcos Resende & Index continue the Brazilian electric-piano/synth-fusion thread; Index features Oberdan Magalhães, co-founder of Banda Black Rio. Antônio Adolfo and Hareton Salvanini widen it into samba-jazz, northeastern rhythms, psychedelia and cinematic arranging. Amaro Freitas turns Afro-Brazilian rhythm into percussive modern piano and has recorded with Shabaka Hutchings; Neue Grafik sits in the same London jazz ecosystem as Yussef Kamaal, with Nubya Garcia and Allysha Joy featured here. Mildlife adds cosmic disco and prog, Cortex and Marc Moulin’s Placebo bring French/Belgian jazz-funk, and Jiro Inagaki supplies the Japanese branch. I chose signature and title tracks, the strongest rhythm-section and Rhodes showcases, and several longer pieces whose arrangements evolve—enough range to test each artist without simply dropping in whole albums.";
  const quote = (value: string) => `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
  const script = `tell application "Music"
set p to user playlist "To Explore Next"
set description of p to ${quote(description)}
set savedDescription to description of p
return (length of savedDescription as string) & linefeed & savedDescription
end tell`;
  const result = await shell.execFile("osascript", ["-e", script], { timeoutMs: 30000, maxBytes: 10000, maxLines: 50, raise: true });
  const [lengthText, ...lines] = result.stdout.trimEnd().split("\n");
  return { requestedLength: description.length, savedLength: Number(lengthText), savedDescription: lines.join("\n") };
}

