  },
) {
  if (!input.artists?.length) throw new Error("Provide at least one artist.");
  const maxResults = Math.max(1, Math.min(10, input.maxResultsPerArtist || 5));
  const references = (input.referenceArtists || []).slice(0, 8);
  const themes = (input.themes || []).slice(0, 6);
  const decode = (value: string) =>
    value
      .replace(/<[^>]+>/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&quot;/g, '"')
      .replace(/&#x27;|&#39;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/\s+/g, " ")
      .trim();
  const unwrapUrl = (value: string) => {
    const decoded = value.replace(/&amp;/g, "&");
    const match = decoded.match(/[?&]uddg=([^&]+)/);
    try {
      return match ? decodeURIComponent(match[1]) : decoded;
    } catch {
      return decoded;
    }
  };

  const jobs = input.artists.flatMap((artist) => {
    const queries = [
      `"${artist}" biography collaborators personnel`,
      references.length
        ? `"${artist}" ${references.map((name) => `"${name}"`).join(" OR ")} collaboration`
        : `"${artist}" musical style influences`,
      themes.length ? `"${artist}" ${themes.join(" ")}` : null,
    ].filter((query): query is string => Boolean(query));
    return queries.map((query) => ({ artist, query }));
  });

  const responses = await Promise.allSettled(
    jobs.map((job) =>
      http.request(`https://html.duckduckgo.com/html/?q=${encodeURIComponent(job.query)}`, {
        maxBytes: 40000,
      }),
    ),
  );
  const grouped = new Map<
    string,
    Array<{ query: string; title: string; url: string; snippet: string }>
  >();

  for (let index = 0; index < jobs.length; index++) {
    const response = responses[index];
    if (response.status !== "fulfilled" || !response.value.ok) continue;
    const html = response.value.body;
    const resultRegex =
      /<a[^>]*class="[^"]*result__a[^"]*"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>[\s\S]*?<a[^>]*class="[^"]*result__snippet[^"]*"[^>]*>([\s\S]*?)<\/a>/gi;
    const fallbackRegex = /<a[^>]*rel="nofollow"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
    const found: Array<{ query: string; title: string; url: string; snippet: string }> = [];
    let match: RegExpExecArray | null;
    while ((match = resultRegex.exec(html)) && found.length < maxResults) {
      found.push({
        query: jobs[index].query,
        url: unwrapUrl(match[1]),
        title: decode(match[2]),
        snippet: decode(match[3]),
      });
    }
    if (!found.length) {
      while ((match = fallbackRegex.exec(html)) && found.length < maxResults) {
        const title = decode(match[2]);
        if (title)
          found.push({ query: jobs[index].query, url: unwrapUrl(match[1]), title, snippet: "" });
      }
    }
    const current = grouped.get(jobs[index].artist) || [];
    const seen = new Set(current.map((item) => item.url));
    for (const item of found)
      if (!seen.has(item.url)) {
        current.push(item);
        seen.add(item.url);
      }
    grouped.set(jobs[index].artist, current);
  }

  return {
    artists: input.artists.map((artist) => ({
      artist,
      evidence: (grouped.get(artist) || []).slice(0, maxResults),
    })),
    referenceArtists: references,
