async function updateAppleMusicPlaylistDescription(
  { shell },
  input: {
    name: string;
    description: string;
    overflow?: "error" | "truncate";
    dryRun?: boolean;
  },
) {
  if (!input.name?.trim()) throw new Error("playlist name is required");
  const limit = 255;
  const requested = input.description || "";
  const overflow = input.overflow || "error";
  let description = requested;
  let truncated = false;
  if (description.length > limit) {
    if (overflow === "error") throw new Error(`Apple Music playlist descriptions are limited to ${limit} characters; received ${description.length}.`);
    const candidate = description.slice(0, limit - 1);
    const wordBoundary = candidate.lastIndexOf(" ");
    description = `${candidate.slice(0, wordBoundary >= limit * 0.75 ? wordBoundary : candidate.length).trimEnd()}…`;
    truncated = true;
  }
  const preview = { name: input.name, description, length: description.length, limit, truncated };
  if (input.dryRun) return { dryRun: true, ...preview };

  const asAppleString = (value: string) => `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
  const script = `tell application "Music"
if not (exists user playlist ${asAppleString(input.name)}) then error "Playlist not found" number 404
set p to user playlist ${asAppleString(input.name)}
set description of p to ${asAppleString(description)}
set savedDescription to description of p
return (length of savedDescription as string) & linefeed & savedDescription
end tell`;
  const result = await shell.execFile("osascript", ["-e", script], { timeoutMs: 30000, maxBytes: 10000, maxLines: 50, raise: true });
  const [lengthText, ...descriptionLines] = result.stdout.trimEnd().split("\n");
  const savedDescription = descriptionLines.join("\n");
  const savedLength = Number(lengthText);
  if (savedDescription !== description) throw new Error(`Music saved ${savedLength} of ${description.length} characters; description did not round-trip exactly.`);
  return { dryRun: false, name: input.name, description: savedDescription, length: savedLength, limit, truncated };
}

