    { file: "data/README.md", content: "# Music feedback data

This directory is intentionally version-controlled.

- `recommendations.jsonl`: playlist manifests with recommendation provenance and track traits.
- `listening-feedback.jsonl`: evaluations derived from Apple Music playback logs.
- `taste-profile.json`: generated artist and trait preferences.

JSONL records use stable IDs so evaluations can be safely replaced instead of duplicated.
" },
  ];
  const results = [];
  for (const item of files) {
    results.push(await workspace.edit(item.file, { revision: null, changes: [{ kind: "replaceFile", content: item.content }] }));
  }
  return results;
}

