async function recordMusicRecommendationManifest(
  { workspace },
  input: {
    playlist: string;
    manifestId?: string;
    createdAt?: string;
    targetMinutes?: number;
    description?: string;
    tracks: Array<{
      title: string;
      artist: string;
      album?: string;
      albumId?: string | number;
      trackId?: string | number;
      durationSeconds: number;
      seeds?: string[];
      traits?: string[];
      reason?: string;
      albumUrl?: string;
    }>;
    ifExists?: "replace" | "error";
  },
) {
  if (!input.playlist?.trim()) throw new Error("playlist is required");
  if (!input.tracks?.length) throw new Error("Provide at least one recommended track.");
  const createdAt = input.createdAt || new Date().toISOString();
  const date = createdAt.slice(0, 10);
  const slug = input.playlist
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
  const id = input.manifestId || `${date}-${slug}`;
  const seen = new Set<string>();
  const tracks = input.tracks.map((track, index) => {
    if (!track.title?.trim() || !track.artist?.trim() || !(track.durationSeconds > 0))
      throw new Error(`Invalid track at position ${index + 1}.`);
    const key = `${track.title.toLowerCase()}\u0000${track.artist.toLowerCase()}`;
    if (seen.has(key))
      throw new Error(`Duplicate track in manifest: ${track.title} — ${track.artist}`);
    seen.add(key);
    return {
      position: index + 1,
      title: track.title,
      artist: track.artist,
      album: track.album || null,
      albumId: track.albumId != null ? String(track.albumId) : null,
      trackId: track.trackId != null ? String(track.trackId) : null,
      durationSeconds: Math.round(track.durationSeconds),
      seeds: Array.from(new Set(track.seeds || [])),
      traits: Array.from(new Set(track.traits || [])),
      reason: track.reason || null,
      albumUrl: track.albumUrl || null,
    };
  });
  const record = {
    version: 1,
    id,
    playlist: input.playlist,
    createdAt,
    targetMinutes: input.targetMinutes || null,
    description: input.description || null,
    tracks,
  };
  const path = "data/recommendations.jsonl";
  const current = await workspace.read(path, { format: "raw" }).catch(() => null);
  const records =
    current?.content
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line)) || [];
  const existingIndex = records.findIndex((item) => item.id === id);
  if (existingIndex >= 0 && (input.ifExists || "error") === "error")
    throw new Error(`Manifest already exists: ${id}`);
  if (existingIndex >= 0) records[existingIndex] = record;
  else records.push(record);
  const content = records.map((item) => JSON.stringify(item)).join("\n") + "\n";
  await workspace.edit(path, {
    revision: current?.revision || null,
    changes: [{ kind: "replaceFile", content }],
  });
  return {
    path,
    id,
    playlist: input.playlist,
    trackCount: tracks.length,
    totalSeconds: tracks.reduce((sum, track) => sum + track.durationSeconds, 0),
    replaced: existingIndex >= 0,
  };
}

