</style></head><body><main class="shell"><header class="hero"><p class="eyebrow">A private recommendation journal</p><h1>Listening<br>Notes</h1><p class="hero-copy">A growing field guide to the records, scenes, collaborators and musical detours worth hearing next.</p><div class="stats"><div><strong>${entries.length}</strong> entries</div><div><strong>${totalTracks}</strong> tracks</div><div><strong>${uniqueArtists}</strong> artists</div><div><strong>${longDuration(totalSeconds)}</strong> queued</div></div></header>${renderedEntries || `<p class="empty">No entries yet.</p>`}<footer><span>Generated from versioned recommendation manifests.</span><span>Last updated ${prettyDate(new Date().toISOString())}</span></footer></main></body></html>`;
  const sitePath = "site/index.html";
  const siteFile = await workspace.read(sitePath, { format: "raw" }).catch(() => null);
  await workspace.edit(sitePath, { revision: siteFile?.revision || null, changes: [{ kind: "replaceFile", content: html }] });
