async ({ workspace }) => {
  const [source, site] = await Promise.all([
    workspace.read(".pi/pit/functions/publishMusicRecommendationJournalEntry.ts", { format: "raw" }),
    workspace.read("site/index.html", { format: "raw" }),
  ]);
  let sourceContent = source.content;
  const helperNeedle = `  const hashHue = (value: string) =>\n    [...value].reduce((sum, char) => (sum * 31 + char.charCodeAt(0)) % 360, 0);`;
  const helperReplacement = `${helperNeedle}\n  const wikipediaUrl = (artist: string) => \`https://en.wikipedia.org/wiki/Special:Search?search=\${encodeURIComponent(artist)}\`;`;
  const headingNeedle = `<div class="artist-copy"><p class="album-label">\${esc(first.album)}</p><h3>\${esc(artist)}</h3>`;
  const headingReplacement = `<div class="artist-copy"><p class="album-label">\${esc(first.album)}</p><h3><a href="\${esc(wikipediaUrl(artist))}" target="_blank" rel="noreferrer" title="Read about \${esc(artist)} on Wikipedia">\${esc(artist)} <span aria-hidden="true">↗</span></a></h3>`;
  const cssNeedle = `.artist-copy h3{font-size:2.15rem;letter-spacing:-.035em}.album-label`;
  const cssReplacement = `.artist-copy h3{font-size:2.15rem;letter-spacing:-.035em}.artist-copy h3 a{color:inherit;text-decoration:none}.artist-copy h3 a span{font:500 .8rem system-ui;color:var(--muted);vertical-align:top}.artist-copy h3 a:hover{color:var(--acid)}.album-label`;
  if (!sourceContent.includes(helperNeedle) || !sourceContent.includes(headingNeedle) || !sourceContent.includes(cssNeedle)) throw new Error("Expected journal generator anchors were not found.");
  sourceContent = sourceContent.replace(helperNeedle, helperReplacement).replace(headingNeedle, headingReplacement).replace(cssNeedle, cssReplacement);

  let siteContent = site.content;
  if (!siteContent.includes(cssNeedle)) throw new Error("Expected generated-site CSS anchor was not found.");
  siteContent = siteContent.replace(cssNeedle, cssReplacement).replace(/<h3>([^<]+)<\/h3>/g, (_match, encodedArtist: string) => {
    const artist = encodedArtist.replace(/&amp;/g, "&").replace(/&#39;/g, "'").replace(/&quot;/g, '"');
    const href = `https://en.wikipedia.org/wiki/Special:Search?search=${encodeURIComponent(artist)}`.replace(/&/g, "&amp;");
    return `<h3><a href="${href}" target="_blank" rel="noreferrer" title="Read about ${encodedArtist} on Wikipedia">${encodedArtist} <span aria-hidden="true">↗</span></a></h3>`;
  });

  const result = await workspace.batch([
    { kind: "edit", file: ".pi/pit/functions/publishMusicRecommendationJournalEntry.ts", changes: { revision: source.revision, changes: [{ kind: "replaceFile", content: sourceContent }] } },
    { kind: "edit", file: "site/index.html", changes: { revision: site.revision, changes: [{ kind: "replaceFile", content: siteContent }] } },
  ]);
  return result;
}

