async ({ workspace, shell }) => {
  const [page, source] = await Promise.all([
    workspace.read("site/index.html", { format: "raw" }),
    workspace.read(".pi/pit/functions/publishMusicRecommendationJournalEntry.ts", { format: "raw" }),
  ]);
  const links = [...page.content.matchAll(/<h3><a href="([^"]+)"[^>]*>(.*?) <span/g)].map(match => ({ href: match[1], artist: match[2].replace(/&amp;/g, "&") }));
  const validation = await shell.execFile("/usr/bin/python3", ["-c", "from html.parser import HTMLParser\np=HTMLParser();p.feed(open('site/index.html',encoding='utf-8').read());print('ok')"], { maxBytes: 1000, maxLines: 10 });
  return { linkCount: links.length, links, generatorHasWikipediaHelper: source.content.includes("const wikipediaUrl"), validation };
}

