async ({ workspace }) => {
  const paths = [".pi/pit/functions/publishMusicRecommendationJournalEntry.ts", "site/index.html"];
  const reads = await Promise.all(paths.map(file => workspace.read(file, { format: "raw" })));
  const replacements: Array<[string,string]> = [
    [`.hero{min-height:72vh;display:grid;align-content:center;padding:80px 0 64px;border-bottom:1px solid var(--line)}`, `.hero{display:grid;align-content:center;padding:52px 0 40px;border-bottom:1px solid var(--line)}`],
    [`h1{font-size:clamp(4rem,12vw,10rem);letter-spacing:-.07em;max-width:1000px}`, `h1{font-size:clamp(3.5rem,9vw,7.5rem);letter-spacing:-.065em;max-width:900px}`],
    [`.hero-copy{max-width:660px;font-size:1.15rem;color:var(--muted);margin:32px 0}`, `.hero-copy{max-width:660px;font-size:1.05rem;color:var(--muted);margin:20px 0 24px}`],
    [`.hero{min-height:60vh}.artist-card`, `.hero{padding:40px 0 32px}.artist-card`],
  ];
  const edits = reads.map((read, index) => {
    let content = read.content;
    for (const [from, to] of replacements) {
      if (!content.includes(from)) throw new Error(`Expected CSS anchor not found in ${paths[index]}: ${from}`);
      content = content.replace(from, to);
    }
    return { kind: "edit" as const, file: paths[index], changes: { revision: read.revision, changes: [{ kind: "replaceFile" as const, content }] } };
  });
  return workspace.batch(edits);
}

