async ({ workspace }) => {
  return workspace.edit("data/explicit-feedback.jsonl", { revision: null, changes: [{ kind: "replaceFile", content: "" }] });
}

async function recordExplicitMusicFeedback(
  { workspace },
  input: {
    manifestId: string;
    track?: string;
    artist?: string;
    trait?: string;
    sentiment: "love" | "like" | "neutral" | "dislike" | "never";
    note?: string;
    recordedAt?: string;
    feedbackId?: string;
    ifExists?: "replace" | "error";
    dryRun?: boolean;
  },
) {
  if (!input.manifestId) throw new Error("manifestId is required");
  const targets = [input.track, input.artist, input.trait].filter(value => value?.trim());
  if (targets.length !== 1) throw new Error("Provide exactly one of track, artist, or trait.");
  const scoreBySentiment = { love: 4, like: 2, neutral: 0, dislike: -3, never: -6 } as const;
  const recommendations = await workspace.read("data/recommendations.jsonl", { format: "raw" });
  const manifests = recommendations.content.split("\n").filter(Boolean).map(line => JSON.parse(line));
  const manifest = manifests.find(item => item.id === input.manifestId);
  if (!manifest) throw new Error(`Manifest not found: ${input.manifestId}`);
  const normalize = (value: string) => value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();

  let targetType: "track" | "artist" | "trait";
  let target: string;
  let artist: string | null = null;
  let title: string | null = null;
  let traits: string[] = [];
  if (input.track) {
    targetType = "track"; target = input.track;
    const matched = manifest.tracks.find((item: any) => normalize(item.title) === normalize(input.track!));
    if (!matched) throw new Error(`Track not found in manifest: ${input.track}`);
    title = matched.title; artist = matched.artist; traits = matched.traits || [];
  } else if (input.artist) {
    targetType = "artist"; target = input.artist;
    const tracks = manifest.tracks.filter((item: any) => normalize(item.artist) === normalize(input.artist!));
    if (!tracks.length) throw new Error(`Artist not found in manifest: ${input.artist}`);
    artist = tracks[0].artist;
    traits = Array.from(new Set(tracks.flatMap((item: any) => item.traits || []))) as string[];
  } else {
    targetType = "trait"; target = input.trait!;
    const available = new Map<string, string>();
    for (const item of manifest.tracks) for (const value of item.traits || []) available.set(normalize(value), value);
    const canonical = available.get(normalize(input.trait!));
    if (!canonical) throw new Error(`Trait not found in manifest: ${input.trait}`);
    target = canonical; traits = [canonical];
  }

  const recordedAt = input.recordedAt || new Date().toISOString();
  const id = input.feedbackId || `${input.manifestId}:${targetType}:${normalize(target).replace(/ /g, "-")}:${recordedAt}`;
  const record = {
    version: 1,
    id,
    manifestId: input.manifestId,
    playlist: manifest.playlist,
    recordedAt,
    targetType,
    target,
    title,
    artist,
    traits,
    sentiment: input.sentiment,
    score: scoreBySentiment[input.sentiment],
    note: input.note || null,
  };
  if (input.dryRun) return { dryRun: true, record };

  const path = "data/explicit-feedback.jsonl";
  const current = await workspace.read(path, { format: "raw" }).catch(() => null);
  const records = current?.content.split("\n").filter(Boolean).map(line => JSON.parse(line)) || [];
  const index = records.findIndex(item => item.id === id);
  if (index >= 0 && (input.ifExists || "error") === "error") throw new Error(`Feedback already exists: ${id}`);
  if (index >= 0) records[index] = record; else records.push(record);
  await workspace.edit(path, { revision: current?.revision || null, changes: [{ kind: "replaceFile", content: records.map(item => JSON.stringify(item)).join("\n") + "\n" }] });
  return { dryRun: false, path, id, targetType, target, sentiment: input.sentiment, score: record.score, replaced: index >= 0 };
}

