    manifestId: string;
    startDate: string;
    endDate?: string;
    halfLifeDays?: number;
    dryRun?: boolean;
  },
) {
  const before = await updateMusicTasteProfile({ halfLifeDays: input.halfLifeDays, write: false });
  const evaluation = await evaluateRecommendedPlaylistListening({
    manifestId: input.manifestId,
    startDate: input.startDate,
    endDate: input.endDate,
    write: !input.dryRun,
  });
  if (input.dryRun) return { dryRun: true, evaluation, profileBefore: { topArtists: before.topArtists, topTraits: before.topTraits } };
  const after = await updateMusicTasteProfile({ halfLifeDays: input.halfLifeDays, write: true });
  const beforeArtists = new Map(before.profile.artists.map((item: any) => [item.name, item.preference]));
  const beforeTraits = new Map(before.profile.traits.map((item: any) => [item.name, item.preference]));
  const artistChanges = after.profile.artists.map((item: any) => ({
    name: item.name,
    before: beforeArtists.get(item.name) || 0,
