arguments.code:
async ({ shell }) => {
  const playlistName = "To Explore Next 2";
  const albums = [
    { url: "https://music.apple.com/br/album/arthur-verocai/495578530", tracks: ["Na Boca do Sol", "Dedicada a Ela", "Karina (Domingo No Grajaú)", "Sylvia"] },
    { url: "https://music.apple.com/br/album/matanca-do-porco/713818104", tracks: ["A Matanca do Porco", "Mar Azul", "A 3", "Bolero"] },
    { url: "https://music.apple.com/br/album/slaves-mass/281147840", tracks: ["Slaves Mass (Missa Dos Escravos)", "Cannon (Dedicated to Cannonball Adderley)", "Just Listen (Escuta Meu Piano)"] },
    { url: "https://music.apple.com/br/album/academia-de-dan%C3%A7as/1687358367", tracks: ["Quatro Cantos", "Palácio De Pinturas", "Bodas De Prata", "Vila Rica 1720"] },
    { url: "https://music.apple.com/br/album/meu-balan%C3%A7o/1240981590", tracks: ["Meu Balanço", "Lady Samba", "Luar do Sertão", "Walking"] },
    { url: "https://music.apple.com/br/album/natura-morta/1671850742", tracks: ["Natura Morta", "Prussian Blue", "Panorama", "Barocco, Ma Non Troppo"] },
    { url: "https://music.apple.com/br/album/days-as-echoes/1529360285", tracks: ["Days As Echoes", "In a Dream", "Moonscape Waltz", "Few Layers for Smith"] },
    { url: "https://music.apple.com/br/album/education-recreation/1633665943", tracks: ["Conversation Piece", "Grinners Circle", "Iconoclasts", "Ten & Two"] },
    { url: "https://music.apple.com/br/album/yellow/1574720059", tracks: ["Venus", "Golden Green", "Rahu & Ketu", "Third Eye"] },
    { url: "https://music.apple.com/br/album/source/1523554803", tracks: ["Source (feat. Ms Maurice, Cassie Kinoshi & Richie Seivwright)", "The Message Continues", "Inner Game", "La cumbia me está llamando (feat. La Perla)"] }
  ];
  const appleString = (value: string) => `"${value.replace(/\/g, "\\").replace(/"/g, '\"')}"`;
  const existingResult = await shell.execFile("osascript", ["-e", `tell application "Music"
set output to ""
repeat with t in tracks of user playlist ${appleString(playlistName)}
set output to output & (name of t) & linefeed
end repeat
return output
end tell`], { timeoutMs: 30000, maxBytes: 20000, maxLines: 500 });
  const existing = new Set(existingResult.stdout.split("
").filter(Boolean));
  const results: Array<{url:string; loaded:boolean; added:string[]; missing:string[]; error:string}> = [];

  for (const album of albums) {
    const wanted = album.tracks.filter(title => !existing.has(title));
    if (!wanted.length) { results.push({url:album.url,loaded:true,added:[],missing:[],error:"skipped existing"}); continue; }
    await shell.execFile("open", ["-a", "Music", album.url], { timeoutMs: 10000, maxBytes: 1000, maxLines: 10, raise: true });
    let loaded = false;
    for (let attempt = 0; attempt < 20; attempt++) {
      await new Promise(resolve => setTimeout(resolve, 1000));
      const probe = `tell application "Music" to activate
delay 0.15
tell application "System Events"
tell process "Music"
try
set sg to first UI element of front window whose role is "AXSplitGroup"
set mainList to UI element 1 of UI element 4 of sg
set trackSection to UI element 2 of mainList
repeat with e in UI elements of trackSection
try
if description of e is ${appleString(wanted[0])} then return "yes"
end try
end repeat
end try
return "no"
end tell
end tell`;
      const check = await shell.execFile("osascript", ["-e", probe], { timeoutMs: 15000, maxBytes: 1000, maxLines: 10 });
      if (check.stdout.trim() === "yes") { loaded = true; break; }
    }
    if (!loaded) { results.push({url:album.url,loaded:false,added:[],missing:wanted,error:"album did not load"}); continue; }
    const addScript = `tell application "Music" to activate
delay 0.2
tell application "System Events"
tell process "Music"
set wantedTracks to {${wanted.map(appleString).join(", ")}}
set output to ""
set sg to first UI element of front window whose role is "AXSplitGroup"
set mainList to UI element 1 of UI element 4 of sg
set trackSection to UI element 2 of mainList
repeat with wantedTrack in wantedTracks
set wantedName to wantedTrack as string
set foundIt to false
repeat with e in UI elements of trackSection
try
if description of e is wantedName then
set foundIt to true
perform action "AXPress" of (first button of e whose description is "More")
delay 0.25
keystroke "Add to Playlist"
delay 0.15
key code 124
delay 0.25
keystroke ${appleString(playlistName)}
delay 0.15
key code 36
delay 0.4
set output to output & "ADDED" & tab & wantedName & linefeed
exit repeat
end if
end try
end repeat
if not foundIt then set output to output & "MISSING" & tab & wantedName & linefeed
end repeat
return output
end tell
end tell`;
    const action = await shell.execFile("osascript", ["-e", addScript], { timeoutMs: 90000, maxBytes: 10000, maxLines: 100 });
    const added:string[]=[]; const missing:string[]=[];
    for (const line of action.stdout.split("
")) { const [status,title]=line.split("	"); if(status==="ADDED"&&title){added.push(title);existing.add(title);} if(status==="MISSING"&&title)missing.push(title); }
    results.push({url:album.url,loaded:true,added,missing,error:action.stderr});
  }
  await new Promise(resolve => setTimeout(resolve, 2500));
  const verify = await shell.execFile("osascript", ["-e", `tell application "Music"
set p to user playlist ${appleString(playlistName)}
set totalDuration to 0
repeat with t in tracks of p
set totalDuration to totalDuration + (duration of t)
end repeat
return (count of tracks of p as string) & tab & (round totalDuration as string)
end tell`], { timeoutMs: 60000, maxBytes: 2000, maxLines: 20 });
  return {results,verify};
}

async ({ shell }) => {
  const script = `tell application "Music"
set p to user playlist "To Explore Next 2"
set output to ""
set seenNames to {}
repeat with t in tracks of p
set trackName to name of t
if seenNames does not contain trackName then
set end of seenNames to trackName
set n to 0
repeat with x in tracks of p
if name of x is trackName then set n to n + 1
end repeat
set output to output & n & tab & trackName & tab & (artist of t) & linefeed
end if
end repeat
return output
end tell`;
  const result = await shell.execFile("osascript", ["-e", script], { timeoutMs: 120000, maxBytes: 20000, maxLines: 300 });
  const rows = result.stdout.split("\n").filter(Boolean).map(line => { const [count,title,artist]=line.split("\t"); return {count:Number(count),title,artist}; });
  return { totalRows: rows.reduce((s,r)=>s+r.count,0), unique: rows.length, duplicates: rows.filter(r=>r.count>1), rows };
}

