async ({ workspace }) => {
  const site = await workspace.read("site/index.html", { format: "raw" });
  let content = site.content;
  const replacements: Array<[string,string]> = [
    [`.hero{min-height:72vh;display:grid;align-content:center;padding:80px 0 64px;border-bottom:1px solid var(--line)}`, `.hero{display:grid;align-content:center;padding:30px 0 26px;border-bottom:1px solid var(--line)}`],
    [`.eyebrow,.kicker,.album-label,.narrative>span{text-transform:uppercase;letter-spacing:.18em;font-size:.72rem;font-weight:800;color:var(--acid)}h1`, `.eyebrow,.kicker,.album-label,.narrative>span{text-transform:uppercase;letter-spacing:.18em;font-size:.72rem;font-weight:800;color:var(--acid)}.eyebrow{margin:0 0 8px}h1`],
    [`h1{font-size:clamp(4rem,12vw,10rem);letter-spacing:-.07em;max-width:1000px}`, `h1{font-size:clamp(3rem,7vw,5.8rem);letter-spacing:-.06em}`],
    [`.hero-copy{max-width:660px;font-size:1.15rem;color:var(--muted);margin:32px 0}`, `.hero-copy{max-width:700px;font-size:1rem;color:var(--muted);margin:12px 0 16px}`],
    [`.hero{min-height:60vh}.artist-card`, `.hero{padding:24px 0 22px}.artist-card`],
    [`<h1>Listening<br>Notes</h1>`, `<h1>Listening Notes</h1>`],
    [`.artist-copy h3{font-size:2.15rem;letter-spacing:-.035em}.album-label`, `.artist-copy h3{font-size:2.15rem;letter-spacing:-.035em}.artist-copy h3 a{color:inherit;text-decoration:none}.artist-copy h3 a span{font:500 .8rem system-ui;color:var(--muted);vertical-align:top}.artist-copy h3 a:hover{color:var(--acid)}.album-label`],
  ];
  for (const [from,to] of replacements) {
    if (!content.includes(from)) throw new Error(`Expected generated journal anchor was not found: ${from}`);
    content = content.replace(from,to);
  }
  content = content.replace(/<h3>([^<]+)<\/h3>/g, (_match, encodedArtist:string) => {
    const artist = encodedArtist.replace(/&amp;/g,"&").replace(/&#39;/g,"'").replace(/&quot;/g,'"');
    const href = `https://en.wikipedia.org/wiki/Special:Search?search=${encodeURIComponent(artist)}`;
    return `<h3><a href="${href}" target="_blank" rel="noreferrer" title="Read about ${encodedArtist} on Wikipedia">${encodedArtist} <span aria-hidden="true">↗</span></a></h3>`;
  });
  return workspace.edit("site/index.html", { revision: site.revision, changes: [{ kind: "replaceFile", content }] });
}

async ({ workspace, git, shell }) => {
  const [status, page, manifests, journal, feedback, profile] = await Promise.all([
    git.status(["--short"]),
    workspace.read("site/index.html", { format: "raw" }),
    workspace.read("data/recommendations.jsonl", { format: "raw" }),
    workspace.read("data/journal.jsonl", { format: "raw" }),
    workspace.read("data/listening-feedback.jsonl", { format: "raw" }),
    workspace.read("data/taste-profile.json", { format: "raw" }),
  ]);
  const manifestRecords = manifests.content.split("\n").filter(Boolean).map(line=>JSON.parse(line));
  const journalRecords = journal.content.split("\n").filter(Boolean).map(line=>JSON.parse(line));
  const feedbackRecords = feedback.content.split("\n").filter(Boolean).map(line=>JSON.parse(line));
  const validation = await shell.execFile("/usr/bin/python3", ["-c", "from html.parser import HTMLParser\np=HTMLParser();p.feed(open('site/index.html',encoding='utf-8').read());print('ok')"], { maxBytes:1000,maxLines:10 });
  return {
    status,
    manifests: manifestRecords.map(r=>({id:r.id,playlist:r.playlist,tracks:r.tracks.length,totalSeconds:r.tracks.reduce((s:number,t:any)=>s+t.durationSeconds,0)})),
    journalEntries: journalRecords.map(r=>({manifestId:r.manifestId,headline:r.headline})),
    feedbackEvaluations: feedbackRecords.length,
    profile: {sourceEvaluations:JSON.parse(profile.content).sourceEvaluations, explicit:JSON.parse(profile.content).sourceExplicitFeedback},
    page: {entries:(page.content.match(/class="entry"/g)||[]).length,cards:(page.content.match(/class="artist-card"/g)||[]).length,wikipedia:(page.content.match(/wikipedia\.org\/wiki\/Special:Search/g)||[]).length,compact:page.content.includes("<h1>Listening Notes</h1>")},
    validation
  };
}

