2{font-size:clamp(3rem,7vw,6.5rem);letter-spacing:-.055em;max-width:850px}.intro{font-size:1.25rem;max-width:720px;color:#d7d1c5;margin:28px 0}.entry-meta{display:flex;gap:8px;flex-wrap:wrap}.tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.tags span{font-size:.72rem;text-transform:uppercase;letter-spacing:.12em;color:#111;background:var(--acid);padding:6px 10px;border-radius:2px}.narrative{grid-column:2;grid-row:2/8;border-left:1px solid var(--line);padding-left:32px;color:var(--muted)}.narrative p{font-family:Georgia,serif;font-size:1.15rem;color:#d7d1c5}.artist-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.artist-card{display:grid;grid-template-columns:200px 1fr;background:linear-gradient(145deg,hsl(var(--h) 24% 18%),var(--panel) 42%);border:1px solid #ffffff14;min-height:390px;overflow:hidden;box-shadow:0 20px 60px #0004;transition:transform .25s,border-color .25s}.artist-card:hover{transform:translateY(-4px);border-color:hsl(var(--h) 70% 60% / .5)}.cover-wrap{position:relative;min-height:100%;background:hsl(var(--h) 35% 22%);overflow:hidden}.cover-wrap img{width:100%;height:100%;object-fit:cover;filter:saturate(.82) contrast(1.05);transition:transform .5s}.artist-card:hover img{transform:scale(1.03)}.cover-fallback{height:100%;display:grid;place-items:center;font:8rem Georgia;color:#ffffff33}.card-number{position:absolute;top:12px;left:12px;background:#111d;padding:5px 8px;font-size:.7rem;letter-spacing:.12em}.artist-copy{padding:26px}.artist-copy h3{font-size:2.15rem;letter-spacing:-.035em}.album-label{color:hsl(var(--h) 75% 70%);margin:0 0 10px}.why{color:#d8d2c7}.connection,.selection{font-size:.86rem;color:var(--muted);border-top:1px solid #ffffff12;padding-top:10px}.connection strong,.selection strong{display:block;color:var(--ink);text-transform:uppercase;font-size:.65rem;letter-spacing:.12em}.track-list{list-style:none;padding:0;margin:18px 0 0;border-top:1px solid #ffffff14}.track-list li{border-bottom:1px solid #ffffff14}.track-list a{display:flex;justify-content:space-between;gap:14px;padding:9px 0;color:var(--ink);text-decoration:none;font-size:.86rem}.track-list a:hover span{color:var(--acid)}.track-list time{color:var(--muted);font-variant-numeric:tabular-nums}footer{padding:60px 0;color:var(--muted);display:flex;justify-content:space-between}.empty{padding:100px 0}@media(max-width:900px){.entry-head{grid-template-columns:1fr}.narrative{grid-column:1;grid-row:auto;margin-top:32px}.artist-grid{grid-template-columns:1fr}}@media(max-width:580px){.shell{width:min(100% - 24px,1240px)}.hero{min-height:60vh}.artist-card{grid-template-columns:1fr}.cover-wrap{height:280px}.entry{padding:72px 0}h1{font-size:4.3rem}footer{display:block}}
</style></head><body><main class="shell"><header class="hero"><p class="eyebrow">A private recommendation journal</p><h1>Listening<br>Notes</h1><p class="hero-copy">A growing field guide to the records, scenes, collaborators and musical detours worth hearing next.</p><div class="stats"><div><strong>${entries.length}</strong> entries</div><div><strong>${totalTracks}</strong> tracks</div><div><strong>${uniqueArtists}</strong> artists</div><div><strong>${longDuration(totalSeconds)}</strong> queued</div></div></header>${renderedEntries || `<p class="empty">No entries yet.</p>`}<footer><span>Generated from versioned recommendation manifests.</span><span>Last updated ${prettyDate(new Date().toISOString())}</span></footer></main></body></html>`;
  const sitePath = "site/index.html";
  const siteFile = await workspace.read(sitePath, { format: "raw" }).catch(() => null);
  await workspace.edit(sitePath, {
    revision: siteFile?.revision || null,
    changes: [{ kind: "replaceFile", content: html }],
  });
  return {
    journalPath,
    sitePath,
    manifestId: input.manifestId,
