/**
 * Evaluate recommendation listening, update versioned feedback, rebuild the taste profile, and report preference changes.
 *
 * @pit project
 */
async function runMusicFeedbackCycle(
  {},
  input: {
    manifestId: string;
    startDate: string;
    endDate?: string;
    halfLifeDays?: number;
    dryRun?: boolean;
  },
) {
  const before = await updateMusicTasteProfile({ halfLifeDays: input.halfLifeDays, write: false });
  const evaluation = await evaluateRecommendedPlaylistListening({
    manifestId: input.manifestId,
    startDate: input.startDate,
    endDate: input.endDate,
    write: !input.dryRun,
  });
  if (input.dryRun)
    return {
      dryRun: true,
      evaluation,
      profileBefore: { topArtists: before.topArtists, topTraits: before.topTraits },
    };
  const after = await updateMusicTasteProfile({ halfLifeDays: input.halfLifeDays, write: true });
  const beforeArtists = new Map(
    before.profile.artists.map((item: any) => [item.name, item.preference]),
  );
  const beforeTraits = new Map(
    before.profile.traits.map((item: any) => [item.name, item.preference]),
  );
  const artistChanges = after.profile.artists
    .map((item: any) => ({
      name: item.name,
      before: beforeArtists.get(item.name) || 0,
      after: item.preference,
      delta: Math.round((item.preference - (beforeArtists.get(item.name) || 0)) * 1000) / 1000,
    }))
    .filter((item: any) => item.delta !== 0)
    .sort((a: any, b: any) => Math.abs(b.delta) - Math.abs(a.delta));
  const traitChanges = after.profile.traits
    .map((item: any) => ({
      name: item.name,
      before: beforeTraits.get(item.name) || 0,
      after: item.preference,
      delta: Math.round((item.preference - (beforeTraits.get(item.name) || 0)) * 1000) / 1000,
    }))
    .filter((item: any) => item.delta !== 0)
    .sort((a: any, b: any) => Math.abs(b.delta) - Math.abs(a.delta));
  return {
    dryRun: false,
    evaluation: {
      id: evaluation.id,
      playlist: evaluation.playlist,
      heard: evaluation.heard,
      unheard: evaluation.unheard,
      completedPlays: evaluation.completedPlays,
      earlySkips: evaluation.earlySkips,
      replays: evaluation.replays,
      totalScore: evaluation.totalScore,
    },
    profile: {
      sourceEvaluations: after.sourceEvaluations,
      sourceExplicitFeedback: after.sourceExplicitFeedback,
      uniquePlayEvents: after.uniquePlayEvents,
      uniqueExplicitEvents: after.uniqueExplicitEvents,
      topArtists: after.topArtists,
      topTraits: after.topTraits,
    },
    artistChanges: artistChanges.slice(0, 15),
    traitChanges: traitChanges.slice(0, 20),
  };
}

