/**
 * Summarize an Apple Music playlist's tracks, artists, and total duration.
 *
 * @pit project
 */
async function summarizeAppleMusicPlaylist({ shell }, input: { name: string }) {
  if (!input.name?.trim()) throw new Error("playlist name is required");
  const asAppleString = (value: string) => `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
  const script = `tell application "Music"
if not (exists user playlist ${asAppleString(input.name)}) then error "Playlist not found: ${input.name.replace(/"/g, "")}" number 404
set p to user playlist ${asAppleString(input.name)}
set output to ""
set totalDuration to 0
repeat with t in tracks of p
set trackDuration to 0
try
set trackDuration to duration of t
end try
set totalDuration to totalDuration + trackDuration
set output to output & (name of t) & tab & (artist of t) & tab & (album of t) & tab & (trackDuration as string) & linefeed
end repeat
return (count of tracks of p as string) & tab & (round totalDuration as string) & linefeed & output
end tell`;
  const result = await shell.execFile("osascript", ["-e", script], {
    timeoutMs: 60000,
    maxBytes: 51200,
    maxLines: 1000,
    raise: true,
  });
  const lines = result.stdout.trimEnd().split("\n");
  const [countText, secondsText] = (lines.shift() || "0\t0").split("\t");
  const tracks = lines.filter(Boolean).map((line, index) => {
    const [title, artist, album, seconds] = line.split("\t");
    return { position: index + 1, title, artist, album, seconds: Math.round(Number(seconds) || 0) };
  });
  const totalSeconds = Number(secondsText) || 0;
  return {
    name: input.name,
    trackCount: Number(countText) || tracks.length,
    totalSeconds,
    duration: `${Math.floor(totalSeconds / 3600)}:${String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, "0")}:${String(totalSeconds % 60).padStart(2, "0")}`,
    artists: Array.from(new Set(tracks.map((track) => track.artist).filter(Boolean))),
    tracks,
  };
}

