async function researchMusicArtistConnections(
  { http },
  input: { artists: string[]; referenceArtists?: string[]; themes?: string[]; maxResultsPerArtist?: number },
) {
  if (!input.artists?.length) throw new Error("Provide at least one artist.");
  const maxResults = Math.max(1, Math.min(10, input.maxResultsPerArtist || 5));
  const references = (input.referenceArtists || []).slice(0, 8);
  const themes = (input.themes || []).slice(0, 6);
  const decode = (value: string) => value.replace(/<[^>]+>/g, " ").replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/\s+/g, " ").trim();
  const unwrapUrl = (value: string) => {
    const decoded = value.replace(/&amp;/g, "&");
    const match = decoded.match(/[?&]uddg=([^&]+)/);
    try { return match ? decodeURIComponent(match[1]) : decoded; } catch { return decoded; }
  };
  const isUsefulUrl = (url: string) => /^https?:\/\//i.test(url) && !/duckduckgo\.com\/(?:feedback|y\.js)/i.test(url);
  type Job = { artist: string; query: string; kind: "biography" | "connection" | "themes"; reference?: string };
  const jobs: Job[] = [];
  for (const artist of input.artists) {
    jobs.push({ artist, kind: "biography", query: `"${artist}" biography members collaborators personnel` });
    if (themes.length) jobs.push({ artist, kind: "themes", query: `"${artist}" ${themes.map(theme => `"${theme}"`).join(" ")}` });
    for (const reference of references.slice(0, 3)) jobs.push({ artist, reference, kind: "connection", query: `"${artist}" "${reference}" collaboration personnel connection` });
    if (!themes.length && !references.length) jobs.push({ artist, kind: "themes", query: `"${artist}" musical style influences review` });
  }
  const responses = await Promise.allSettled(jobs.map(job => http.request(`https://html.duckduckgo.com/html/?q=${encodeURIComponent(job.query)}`, { maxBytes: 40000 })));
  const candidates = new Map<string, Array<{ query: string; kind: string; title: string; url: string; snippet: string; score: number }>>();
  for (let index = 0; index < jobs.length; index++) {
    const response = responses[index];
    if (response.status !== "fulfilled" || !response.value.ok) continue;
    const regex = /<a[^>]*class="[^"]*result__a[^"]*"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>[\s\S]*?<a[^>]*class="[^"]*result__snippet[^"]*"[^>]*>([\s\S]*?)<\/a>/gi;
    let match: RegExpExecArray | null;
    let perQuery = 0;
    while ((match = regex.exec(response.value.body)) && perQuery < 5) {
      const url = unwrapUrl(match[1]);
      const title = decode(match[2]);
      const snippet = decode(match[3]);
      if (!isUsefulUrl(url) || !title || !snippet) continue;
      let score = jobs[index].kind === "connection" ? 3 : jobs[index].kind === "biography" ? 2 : 1;
      if (/wikipedia|bandcamp|discogs|allmusic|recordings|records|official/i.test(url)) score += 2;
      if (title.toLowerCase().includes(jobs[index].artist.toLowerCase().split(" ")[0])) score += 2;
      if (jobs[index].reference && snippet.toLowerCase().includes(jobs[index].reference.toLowerCase().split(" ")[0])) score += 3;
      const current = candidates.get(jobs[index].artist) || [];
      current.push({ query: jobs[index].query, kind: jobs[index].kind, title, url, snippet, score });
      candidates.set(jobs[index].artist, current);
      perQuery += 1;
    }
  }
  return {
    artists: input.artists.map(artist => {
      const seen = new Set<string>();
      const evidence = (candidates.get(artist) || []).sort((a,b) => b.score - a.score).filter(item => {
        if (seen.has(item.url)) return false;
        seen.add(item.url); return true;
      }).slice(0, maxResults).map(({ score: _score, ...item }) => item);
      return { artist, evidence };
    }),
    referenceArtists: references,
    themes,
    note: "Search evidence is filtered and ranked, but remains a research packet rather than a verified claim set; confirm important connections from the linked sources.",
  };
}

