arguments.code:
async () => {
  const result = await findAppleMusicCatalogAlbums({ country:"BR", maxAlbumMatches:5, albums:[
    {artist:"Arrigo Barnabé",album:"Clara Crocodilo"},
    {artist:"Metá Metá",album:"MM3"},
    {artist:"Tortoise",album:"TNT"},
    {artist:"The Pop Group",album:"Y"},
    {artist:"African Head Charge",album:"Songs of Praise"},
    {artist:"Francis Bebey",album:"African Electronic Music 1975-1982"},
    {artist:"Ebo Taylor",album:"Love and Death"},
    {artist:"Goat",album:"World Music"},
    {artist:"Broadcast",album:"Tender Buttons"},
    {artist:"A Certain Ratio",album:"Sextet"},
    {artist:"This Heat",album:"Deceit"},
    {artist:"Nala Sinephro",album:"Space 1.8"}
  ]});
  return result.albums.map(item=>({query:item.query,album:item.album,trackCount:item.tracks.length,tracks:item.tracks.map(t=>({title:t.title,seconds:t.seconds}))}));
}

