async ({ http, shell }) => {
 const albums=[
 {id:"1679006816",first:"Man Feriman"},{id:"314874253",first:"TNT"},{id:"1475113163",first:"She Is Beyond Good and Evil"},{id:"1004520675",first:"Dervish Chant"},{id:"1628953437",first:"Dibiye"},{id:"391504410",first:"Love & Death"},{id:"1059097823",first:"Goatman"},{id:"291071689",first:"Tender Buttons"},{id:"1152918145",first:"Knife Slits Water"},{id:"1526175563",first:"Paper Hats"},{id:"1576882000",first:"Space 8"}
 ];
 const lookups=await Promise.all(albums.map(a=>http.request(`https://itunes.apple.com/lookup?id=${a.id}&entity=song&country=BR`,{maxBytes:40000})));
 const direct=albums.map((a,i)=>{const tracks=(JSON.parse(lookups[i].body) as {results:any[]}).results.filter(x=>x.wrapperType==="track");const t=tracks.find(x=>x.trackName===a.first);if(!t?.trackViewUrl)throw new Error(`Missing URL for ${a.first}`);return {...a,url:t.trackViewUrl as string};});
 const outcomes=[];
 for(const album of direct){
   await shell.execFile("open",["-a","Music",album.url],{timeoutMs:10000,maxBytes:1000,maxLines:10,raise:true});
   await new Promise(r=>setTimeout(r,5000));
   const script=`tell application "Music" to activate\ndelay 0.2\ntell application "System Events"\ntell process "Music"\nset tb to first UI element of front window whose role is "AXToolbar"\ntry\nset b to first button of tb whose description is "Add to Library"\nif enabled of b then\nperform action "AXPress" of b\nreturn "added"\nend if\non error\nreturn "already-or-unavailable"\nend try\nreturn "already-or-unavailable"\nend tell\nend tell`;
   const result=await shell.execFile("osascript",["-e",script],{timeoutMs:15000,maxBytes:2000,maxLines:20});
   outcomes.push({albumId:album.id,track:album.first,status:result.stdout.trim(),error:result.stderr});
   await new Promise(r=>setTimeout(r,2500));
 }
 return outcomes;
}

