 [`.hero{min-height:60vh}.artist-card`,`.hero{padding:24px 0 22px}.artist-card`],[`<h1>Listening<br>Notes</h1>`,`<h1>Listening Notes</h1>`],
 [`.artist-copy h3{font-size:2.15rem;letter-spacing:-.035em}.album-label`,`.artist-copy h3{font-size:2.15rem;letter-spacing:-.035em}.artist-copy h3 a{color:inherit;text-decoration:none}.artist-copy h3 a span{font:500 .8rem system-ui;color:var(--muted);vertical-align:top}.artist-copy h3 a:hover{color:var(--acid)}.album-label`]];
