[
  {
    "name": "populateAppleMusicCatalogPlaylist",
    "scope": "project",
    "signature": "populateAppleMusicCatalogPlaylist(input: { name: string; description?: string; albums: Array<{ url: string; tracks: string[] }>; ifExists?: "reuse" | "error" | "createUnique"; dryRun?: boolean; loadTimeoutSeconds?: number; })",
    "lines": 216,
