            .join("");
          return `<section class="artist-card" style="--h:${hashHue(artist)}">
        <div class="cover-wrap">${art ? `<img src="${esc(art)}" alt="Cover of ${esc(first.album)}" loading="lazy">` : `<div class="cover-fallback">${esc(artist.slice(0, 1))}</div>`}<span class="card-number">${String([...grouped.keys()].indexOf(artist) + 1).padStart(2, "0")}</span></div>
        <div class="artist-copy"><p class="album-label">${esc(first.album)}</p><h3>${esc(artist)}</h3>
        <p class="why">${esc(note.why || first.reason || "Selected as a representative next step from your recent listening.")}</p>
