    "source": "/**
 * Rebuild the visual recommendation journal from its latest stored editorial entry without re-entering the content.
 *
 * @pit project
 */
async function rebuildMusicRecommendationJournal(
  { workspace },
  input: { manifestId?: string; country?: string; dryRun?: boolean } = {},
) {
  const journal = await workspace.read("data/journal.jsonl", { format: "raw" });
  const entries = journal.content
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  if (!entries.length) throw new Error("No journal entries are available to rebuild.");
  entries.sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)));
  const entry = input.manifestId
    ? entries.find((item) => item.manifestId === input.manifestId)
    : entries[0];
  if (!entry) throw new Error(`Journal entry not found: ${input.manifestId}`);
  const publishInput = {
    manifestId: entry.manifestId,
    headline: entry.headline,
    intro: entry.intro,
    narrative: entry.narrative || undefined,
    publishedAt: entry.publishedAt,
    tags: entry.tags || [],
    artistNotes: entry.artistNotes || [],
    ifExists: "replace" as const,
    country: input.country || "BR",
  };
  if (input.dryRun)
    return {
      dryRun: true,
      entryCount: entries.length,
      rebuildFrom: entry.manifestId,
      publishInput,
    };
  const result = await publishMusicRecommendationJournalEntry(publishInput);
  return { dryRun: false, entryCount: entries.length, rebuildFrom: entry.manifestId, ...result };
}"
