/**
 * Create or reuse an Apple Music playlist and add selected catalog tracks without duplicates.
 *
 * @pit project
 */
async function populateAppleMusicCatalogPlaylist(
  { shell },
  input: {
    name: string;
    description?: string;
    albums: Array<{ url: string; tracks: string[] }>;
    ifExists?: "reuse" | "error" | "createUnique";
    dryRun?: boolean;
    loadTimeoutSeconds?: number;
  },
) {
  if (!input.name?.trim()) throw new Error("playlist name is required");
  if (!input.albums?.length) throw new Error("Provide at least one album selection.");
  const requestedName = input.name.trim();
  const mode = input.ifExists || "reuse";
  const timeoutSeconds = Math.max(5, Math.min(60, input.loadTimeoutSeconds || 20));
  const plan = input.albums.flatMap((album) =>
    album.tracks.map((title) => ({ albumUrl: album.url, title })),
  );
  if (input.dryRun) return { dryRun: true, requestedName, plannedTracks: plan.length, plan };

  const asAppleString = (value: string) => `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
  const accessibility = await shell.execFile(
    "osascript",
    ["-e", `tell application "System Events" to tell process "Music" to return count of windows`],
    { timeoutMs: 15000, maxBytes: 1000, maxLines: 10 },
  );
  if (accessibility.code !== 0)
    throw new Error(
      `Music UI automation is unavailable: ${accessibility.stderr || accessibility.stdout}`,
    );

  const createScript = `tell application "Music"
set requestedName to ${asAppleString(requestedName)}
set actualName to requestedName
if exists user playlist actualName then
if ${asAppleString(mode)} is "error" then error "Playlist already exists: " & actualName number 409
if ${asAppleString(mode)} is "createUnique" then
set suffix to 2
repeat while exists user playlist actualName
set actualName to requestedName & " " & suffix
set suffix to suffix + 1
end repeat
set p to make new user playlist with properties {name:actualName, description:${asAppleString(input.description || "")}}
else
set p to user playlist actualName
if ${asAppleString(input.description || "")} is not "" then set description of p to ${asAppleString(input.description || "")}
end if
else
set p to make new user playlist with properties {name:actualName, description:${asAppleString(input.description || "")}}
end if
set output to actualName & linefeed
repeat with t in tracks of p
set output to output & (name of t) & linefeed
end repeat
return output
end tell`;
  const created = await shell.execFile("osascript", ["-e", createScript], {
    timeoutMs: 30000,
    maxBytes: 30000,
    maxLines: 1000,
    raise: true,
  });
  const existingLines = created.stdout.trimEnd().split("\n");
  const playlistName = existingLines.shift() || requestedName;
  const existing = new Set(existingLines.filter(Boolean));
  const added: string[] = [];
  const skipped: string[] = [];
  const missing: string[] = [];
  const albumsFailed: Array<{ url: string; reason: string }> = [];

  for (const album of input.albums) {
    const wanted = album.tracks.filter((title) => {
      if (existing.has(title)) {
        skipped.push(title);
        return false;
      }
      return true;
    });
    if (!wanted.length) continue;
    await shell.execFile("open", ["-a", "Music", album.url], {
      timeoutMs: 10000,
      maxBytes: 1000,
      maxLines: 10,
      raise: true,
    });

    let loaded = false;
    for (let attempt = 0; attempt < timeoutSeconds; attempt++) {
      await new Promise((resolve) => setTimeout(resolve, 1000));
      const probeScript = `tell application "Music" to activate
delay 0.2
tell application "System Events"
tell process "Music"
try
set sg to UI element 2 of front window
set mainList to UI element 1 of UI element 4 of sg
set trackSection to UI element 2 of mainList
repeat with e in UI elements of trackSection
try
if description of e is ${asAppleString(wanted[0])} then return "yes"
end try
end repeat
end try
return "no"
end tell
end tell`;
      const probe = await shell.execFile("osascript", ["-e", probeScript], {
        timeoutMs: 15000,
        maxBytes: 1000,
        maxLines: 10,
      });
      if (probe.stdout.trim() === "yes") {
        loaded = true;
        break;
      }
    }
    if (!loaded) {
      albumsFailed.push({
        url: album.url,
        reason: "Album page did not expose the expected track rows.",
      });
      continue;
    }

    const addScript = `tell application "Music" to activate
delay 0.3
tell application "System Events"
tell process "Music"
set wantedTracks to {${wanted.map(asAppleString).join(", ")}}
set output to ""
set sg to UI element 2 of front window
set mainList to UI element 1 of UI element 4 of sg
set trackSection to UI element 2 of mainList
repeat with wantedTrack in wantedTracks
set wantedName to wantedTrack as string
set foundIt to false
repeat with e in UI elements of trackSection
try
if description of e is wantedName then
set foundIt to true
set moreButton to first button of e whose description is "More"
perform action "AXPress" of moreButton
delay 0.35
keystroke "Add to Playlist"
delay 0.2
key code 124
delay 0.35
keystroke ${asAppleString(playlistName)}
delay 0.2
key code 36
delay 0.55
set output to output & "ADDED" & tab & wantedName & linefeed
exit repeat
end if
end try
end repeat
if not foundIt then set output to output & "MISSING" & tab & wantedName & linefeed
end repeat
return output
end tell
end tell`;
    const result = await shell.execFile("osascript", ["-e", addScript], {
      timeoutMs: 120000,
      maxBytes: 20000,
      maxLines: 500,
    });
    for (const line of result.stdout.split("\n")) {
      const [status, title] = line.split("\t");
      if (!title) continue;
      if (status === "ADDED") {
        added.push(title);
        existing.add(title);
      }
      if (status === "MISSING") missing.push(title);
    }
    if (result.code !== 0)
      albumsFailed.push({ url: album.url, reason: result.stderr || "UI automation failed." });
  }

  await new Promise((resolve) => setTimeout(resolve, 1500));
  const verifyScript = `tell application "Music"
set p to user playlist ${asAppleString(playlistName)}
set totalDuration to 0
repeat with t in tracks of p
try
set totalDuration to totalDuration + (duration of t)
end try
end repeat
return (count of tracks of p as string) & tab & (round totalDuration as string)
end tell`;
  const verified = await shell.execFile("osascript", ["-e", verifyScript], {
    timeoutMs: 60000,
    maxBytes: 2000,
    maxLines: 20,
    raise: true,
  });
  const [countText, durationText] = verified.stdout.trim().split("\t");
  const totalSeconds = Number(durationText) || 0;
  return {
    dryRun: false,
    name: playlistName,
    added,
    skipped,
    missing,
    albumsFailed,
    trackCount: Number(countText) || 0,
    totalSeconds,
    duration: `${Math.floor(totalSeconds / 3600)}:${String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, "0")}:${String(totalSeconds % 60).padStart(2, "0")}`,
  };
}

/**
 * Find representative Apple Music albums and tracks in a selected storefront.
 *
 * @pit project
 */
async function findAppleMusicCatalogAlbums(
  { http },
  input: {
    albums: Array<{ artist: string; album: string }>;
    country?: string;
    maxAlbumMatches?: number;
  },
) {
  const country = (input.country || "BR").toUpperCase();
  const maxAlbumMatches = Math.max(1, Math.min(10, input.maxAlbumMatches || 5));
  if (!input.albums?.length) throw new Error("Provide at least one artist/album query.");
  if (!/^[A-Z]{2}$/.test(country)) throw new Error("country must be a two-letter storefront code.");

  type AlbumResult = {
    collectionId: number;
    artistName: string;
    collectionName: string;
    collectionViewUrl: string;
    trackCount?: number;
    releaseDate?: string;
    primaryGenreName?: string;
  };
  type TrackResult = {
    wrapperType: string;
    collectionId?: number;
    trackId?: number;
    trackName?: string;
    artistName?: string;
    collectionName?: string;
    trackNumber?: number;
    trackTimeMillis?: number;
    trackViewUrl?: string;
  };
  const normalize = (value: string) =>
    value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();

  const searches = await Promise.all(
    input.albums.map((query) =>
      http.request(
        `https://itunes.apple.com/search?term=${encodeURIComponent(`${query.artist} ${query.album}`)}&entity=album&limit=${maxAlbumMatches}&country=${country}`,
        { maxBytes: 30000 },
      ),
    ),
  );

  const selected = input.albums.map((query, index) => {
    const body = JSON.parse(searches[index].body) as { results?: AlbumResult[] };
    const wantedArtist = normalize(query.artist);
    const wantedAlbum = normalize(query.album);
    const candidates = (body.results || [])
      .map((album) => {
        const artist = normalize(album.artistName);
        const title = normalize(album.collectionName);
        let score = 0;
        if (title === wantedAlbum) score += 8;
        else if (title.includes(wantedAlbum) || wantedAlbum.includes(title)) score += 4;
        if (artist === wantedArtist) score += 8;
        else if (artist.includes(wantedArtist) || wantedArtist.includes(artist)) score += 4;
        return { album, score };
      })
      .sort((a, b) => b.score - a.score);
    return {
      query,
      album: candidates[0]?.album || null,
      candidates: candidates.map((item) => ({ ...item.album, score: item.score })),
    };
  });

  const lookups = await Promise.allSettled(
    selected.map((item) =>
      item.album
        ? http.request(
            `https://itunes.apple.com/lookup?id=${item.album.collectionId}&entity=song&country=${country}`,
            { maxBytes: 51200 },
          )
        : Promise.reject(new Error("No album match")),
    ),
  );

  const output = [];
  for (let index = 0; index < selected.length; index++) {
    const item = selected[index];
    let tracks: TrackResult[] = [];
    const lookup = lookups[index];
    if (lookup.status === "fulfilled" && lookup.value.ok && item.album) {
      const body = JSON.parse(lookup.value.body) as { results?: TrackResult[] };
      tracks = (body.results || []).filter(
        (result) =>
          result.wrapperType === "track" && result.collectionId === item.album!.collectionId,
      );
    }
    if (!tracks.length && item.album) {
      const fallback = await http.request(
        `https://itunes.apple.com/search?term=${encodeURIComponent(`${item.album.artistName} ${item.album.collectionName}`)}&entity=song&limit=50&country=${country}`,
        { maxBytes: 51200 },
      );
      if (fallback.ok) {
        const body = JSON.parse(fallback.body) as { results?: TrackResult[] };
        tracks = (body.results || []).filter(
          (result) => result.collectionId === item.album!.collectionId,
        );
      }
    }
    output.push({
      query: item.query,
      album: item.album
        ? {
            id: item.album.collectionId,
            artist: item.album.artistName,
            title: item.album.collectionName,
            url: item.album.collectionViewUrl,
            trackCount: item.album.trackCount || tracks.length,
            releaseDate: item.album.releaseDate || null,
            genre: item.album.primaryGenreName || null,
          }
        : null,
      tracks: tracks
        .sort((a, b) => (a.trackNumber || 0) - (b.trackNumber || 0))
        .map((track) => ({
          id: track.trackId || null,
          number: track.trackNumber || null,
          title: track.trackName || "Unknown title",
          artist: track.artistName || item.album?.artistName || "Unknown artist",
          album: track.collectionName || item.album?.collectionName || "Unknown album",
          seconds: Math.round((track.trackTimeMillis || 0) / 1000),
          url: track.trackViewUrl || null,
        })),
      alternatives: item.candidates.slice(0, maxAlbumMatches),
    });
  }
  return { country, albums: output };
}

/**
 * Publish or replace a richly annotated daily recommendation entry and rebuild a visual static HTML listening journal.
 *
 * @pit project
 */
async function publishMusicRecommendationJournalEntry(
  { workspace, http },
  input: {
    manifestId: string;
    headline: string;
    intro: string;
    narrative?: string;
    publishedAt?: string;
    tags?: string[];
    artistNotes?: Array<{
      artist: string;
      why: string;
      connections?: string;
      selectionNote?: string;
    }>;
    ifExists?: "replace" | "error";
    country?: string;
  },
) {
  if (!input.manifestId || !input.headline?.trim() || !input.intro?.trim())
    throw new Error("manifestId, headline, and intro are required.");
  const country = (input.country || "BR").toUpperCase();
  const recommendations = await workspace.read("data/recommendations.jsonl", { format: "raw" });
  const manifests = recommendations.content
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  const manifest = manifests.find((item) => item.id === input.manifestId);
  if (!manifest) throw new Error(`Manifest not found: ${input.manifestId}`);
  const manifestArtists = new Set(manifest.tracks.map((track: any) => track.artist));
  for (const note of input.artistNotes || [])
    if (!manifestArtists.has(note.artist))
      throw new Error(`Artist note does not match manifest: ${note.artist}`);

  const journalPath = "data/journal.jsonl";
  const journalFile = await workspace.read(journalPath, { format: "raw" }).catch(() => null);
  const entries =
    journalFile?.content
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line)) || [];
  const existingIndex = entries.findIndex((entry) => entry.manifestId === input.manifestId);
  if (existingIndex >= 0 && (input.ifExists || "error") === "error")
    throw new Error(`Journal entry already exists for ${input.manifestId}`);
  const entry = {
    version: 1,
    manifestId: input.manifestId,
    headline: input.headline,
    intro: input.intro,
    narrative: input.narrative || null,
    publishedAt: input.publishedAt || new Date().toISOString(),
    tags: Array.from(new Set(input.tags || [])),
    artistNotes: input.artistNotes || [],
    updatedAt: new Date().toISOString(),
  };
  if (existingIndex >= 0) entries[existingIndex] = entry;
  else entries.push(entry);
  entries.sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)));
  await workspace.edit(journalPath, {
    revision: journalFile?.revision || null,
    changes: [
      {
        kind: "replaceFile",
        content: entries.map((item) => JSON.stringify(item)).join("\n") + "\n",
      },
    ],
  });

  const albumIds = Array.from(
    new Set(
      entries.flatMap((journal) => {
        const related = manifests.find((item) => item.id === journal.manifestId);
        return (related?.tracks || []).map((track: any) => track.albumId).filter(Boolean);
      }),
    ),
  ) as string[];
  const artwork = new Map<string, string>();
  const chunks: string[][] = [];
  for (let index = 0; index < albumIds.length; index += 20)
    chunks.push(albumIds.slice(index, index + 20));
  const lookups = await Promise.allSettled(
    chunks.map((ids) =>
      http.request(`https://itunes.apple.com/lookup?id=${ids.join(",")}&country=${country}`, {
        maxBytes: 51200,
      }),
    ),
  );
  for (const lookup of lookups) {
    if (lookup.status !== "fulfilled" || !lookup.value.ok) continue;
    const body = JSON.parse(lookup.value.body) as {
      results?: Array<{ collectionId?: number; artworkUrl100?: string }>;
    };
    for (const item of body.results || [])
      if (item.collectionId && item.artworkUrl100)
        artwork.set(
          String(item.collectionId),
          item.artworkUrl100.replace("100x100bb", "600x600bb"),
        );
  }

  const esc = (value: unknown) =>
    String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  const duration = (seconds: number) =>
    `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, "0")}`;
  const longDuration = (seconds: number) =>
    `${Math.floor(seconds / 3600)}h ${String(Math.floor((seconds % 3600) / 60)).padStart(2, "0")}m`;
  const prettyDate = (value: string) =>
    new Intl.DateTimeFormat("en", {
      month: "long",
      day: "numeric",
      year: "numeric",
      timeZone: "UTC",
    }).format(new Date(value));
  const hashHue = (value: string) =>
    [...value].reduce((sum, char) => (sum * 31 + char.charCodeAt(0)) % 360, 0);

  const renderedEntries = entries
    .map((journal, entryIndex) => {
      const related = manifests.find((item) => item.id === journal.manifestId);
      if (!related) return "";
      const grouped = new Map<string, any[]>();
      for (const track of related.tracks)
        grouped.set(track.artist, [...(grouped.get(track.artist) || []), track]);
      const notes = new Map((journal.artistNotes || []).map((note: any) => [note.artist, note]));
      const totalSeconds = related.tracks.reduce(
        (sum: number, track: any) => sum + track.durationSeconds,
        0,
      );
      const artistCards = [...grouped.entries()]
        .map(([artist, tracks]) => {
          const note: any = notes.get(artist) || {};
          const first = tracks[0];
          const art = first.albumId ? artwork.get(String(first.albumId)) : null;
          const trackRows = tracks
            .map(
              (track: any) =>
                `<li><a href="${esc(track.albumUrl || "#")}" target="_blank" rel="noreferrer"><span>${esc(track.title)}</span><time>${duration(track.durationSeconds)}</time></a></li>`,
            )
            .join("");
          return `<section class="artist-card" style="--h:${hashHue(artist)}">
        <div class="cover-wrap">${art ? `<img src="${esc(art)}" alt="Cover of ${esc(first.album)}" loading="lazy">` : `<div class="cover-fallback">${esc(artist.slice(0, 1))}</div>`}<span class="card-number">${String([...grouped.keys()].indexOf(artist) + 1).padStart(2, "0")}</span></div>
        <div class="artist-copy"><p class="album-label">${esc(first.album)}</p><h3>${esc(artist)}</h3>
        <p class="why">${esc(note.why || first.reason || "Selected as a representative next step from your recent listening.")}</p>
        ${note.connections ? `<p class="connection"><strong>Connection</strong> ${esc(note.connections)}</p>` : ""}
        ${note.selectionNote ? `<p class="selection"><strong>Why these tracks</strong> ${esc(note.selectionNote)}</p>` : ""}
        <ol class="track-list">${trackRows}</ol></div></section>`;
        })
        .join("");
      return `<article class="entry" id="${esc(journal.manifestId)}">
      <header class="entry-head"><div class="date-stamp"><span>${prettyDate(journal.publishedAt)}</span><i></i></div>
      <p class="kicker">Entry ${String(entries.length - entryIndex).padStart(2, "0")} · ${esc(related.playlist)}</p>
      <h2>${esc(journal.headline)}</h2><p class="intro">${esc(journal.intro)}</p>
      <div class="entry-meta"><span>${related.tracks.length} tracks</span><span>${grouped.size} artists</span><span>${longDuration(totalSeconds)}</span></div>
      ${(journal.tags || []).length ? `<div class="tags">${journal.tags.map((tag: string) => `<span>${esc(tag)}</span>`).join("")}</div>` : ""}
      ${journal.narrative ? `<div class="narrative"><span>Field notes</span><p>${esc(journal.narrative)}</p></div>` : ""}</header>
      <div class="artist-grid">${artistCards}</div></article>`;
    })
    .join("\n");

  const allManifests = entries
    .map((item) => manifests.find((manifestItem) => manifestItem.id === item.manifestId))
    .filter(Boolean);
  const totalTracks = allManifests.reduce((sum, item) => sum + item.tracks.length, 0);
  const totalSeconds = allManifests.reduce(
    (sum, item) =>
      sum +
      item.tracks.reduce((trackSum: number, track: any) => trackSum + track.durationSeconds, 0),
    0,
  );
  const uniqueArtists = new Set(
    allManifests.flatMap((item) => item.tracks.map((track: any) => track.artist)),
  ).size;
  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Listening Notes · Music Recommendations</title>
<style>
:root{--ink:#f4f0e8;--muted:#a9a49a;--paper:#11110f;--panel:#191916;--line:#34332c;--acid:#d8ff63;--orange:#ff7a45}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 82% 4%,#322315 0,transparent 26rem),radial-gradient(circle at 8% 28%,#18352d 0,transparent 28rem),var(--paper);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;line-height:1.55}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.18;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.2'/%3E%3C/svg%3E")}.shell{width:min(1240px,calc(100% - 40px));margin:auto}.hero{min-height:72vh;display:grid;align-content:center;padding:80px 0 64px;border-bottom:1px solid var(--line)}.eyebrow,.kicker,.album-label,.narrative>span{text-transform:uppercase;letter-spacing:.18em;font-size:.72rem;font-weight:800;color:var(--acid)}h1,h2,h3{font-family:Georgia,"Times New Roman",serif;font-weight:500;line-height:.95;margin:0}h1{font-size:clamp(4rem,12vw,10rem);letter-spacing:-.07em;max-width:1000px}.hero-copy{max-width:660px;font-size:1.15rem;color:var(--muted);margin:32px 0}.stats{display:flex;gap:12px;flex-wrap:wrap}.stats div,.entry-meta span{border:1px solid var(--line);border-radius:999px;padding:9px 15px;background:#ffffff08}.stats strong{color:var(--acid)}.entry{padding:100px 0;border-bottom:1px solid var(--line)}.entry-head{display:grid;grid-template-columns:minmax(0,1fr) minmax(260px,420px);column-gap:64px;align-items:end;margin-bottom:56px}.date-stamp,.kicker,h2,.intro,.entry-meta,.tags{grid-column:1}.date-stamp{display:flex;align-items:center;gap:18px;color:var(--muted);font-size:.85rem;margin-bottom:30px}.date-stamp i{height:1px;background:var(--line);flex:1}.entry h2{font-size:clamp(3rem,7vw,6.5rem);letter-spacing:-.055em;max-width:850px}.intro{font-size:1.25rem;max-width:720px;color:#d7d1c5;margin:28px 0}.entry-meta{display:flex;gap:8px;flex-wrap:wrap}.tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.tags span{font-size:.72rem;text-transform:uppercase;letter-spacing:.12em;color:#111;background:var(--acid);padding:6px 10px;border-radius:2px}.narrative{grid-column:2;grid-row:2/8;border-left:1px solid var(--line);padding-left:32px;color:var(--muted)}.narrative p{font-family:Georgia,serif;font-size:1.15rem;color:#d7d1c5}.artist-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.artist-card{display:grid;grid-template-columns:200px 1fr;background:linear-gradient(145deg,hsl(var(--h) 24% 18%),var(--panel) 42%);border:1px solid #ffffff14;min-height:390px;overflow:hidden;box-shadow:0 20px 60px #0004;transition:transform .25s,border-color .25s}.artist-card:hover{transform:translateY(-4px);border-color:hsl(var(--h) 70% 60% / .5)}.cover-wrap{position:relative;min-height:100%;background:hsl(var(--h) 35% 22%);overflow:hidden}.cover-wrap img{width:100%;height:100%;object-fit:cover;filter:saturate(.82) contrast(1.05);transition:transform .5s}.artist-card:hover img{transform:scale(1.03)}.cover-fallback{height:100%;display:grid;place-items:center;font:8rem Georgia;color:#ffffff33}.card-number{position:absolute;top:12px;left:12px;background:#111d;padding:5px 8px;font-size:.7rem;letter-spacing:.12em}.artist-copy{padding:26px}.artist-copy h3{font-size:2.15rem;letter-spacing:-.035em}.album-label{color:hsl(var(--h) 75% 70%);margin:0 0 10px}.why{color:#d8d2c7}.connection,.selection{font-size:.86rem;color:var(--muted);border-top:1px solid #ffffff12;padding-top:10px}.connection strong,.selection strong{display:block;color:var(--ink);text-transform:uppercase;font-size:.65rem;letter-spacing:.12em}.track-list{list-style:none;padding:0;margin:18px 0 0;border-top:1px solid #ffffff14}.track-list li{border-bottom:1px solid #ffffff14}.track-list a{display:flex;justify-content:space-between;gap:14px;padding:9px 0;color:var(--ink);text-decoration:none;font-size:.86rem}.track-list a:hover span{color:var(--acid)}.track-list time{color:var(--muted);font-variant-numeric:tabular-nums}footer{padding:60px 0;color:var(--muted);display:flex;justify-content:space-between}.empty{padding:100px 0}@media(max-width:900px){.entry-head{grid-template-columns:1fr}.narrative{grid-column:1;grid-row:auto;margin-top:32px}.artist-grid{grid-template-columns:1fr}}@media(max-width:580px){.shell{width:min(100% - 24px,1240px)}.hero{min-height:60vh}.artist-card{grid-template-columns:1fr}.cover-wrap{height:280px}.entry{padding:72px 0}h1{font-size:4.3rem}footer{display:block}}
</style></head><body><main class="shell"><header class="hero"><p class="eyebrow">A private recommendation journal</p><h1>Listening<br>Notes</h1><p class="hero-copy">A growing field guide to the records, scenes, collaborators and musical detours worth hearing next.</p><div class="stats"><div><strong>${entries.length}</strong> entries</div><div><strong>${totalTracks}</strong> tracks</div><div><strong>${uniqueArtists}</strong> artists</div><div><strong>${longDuration(totalSeconds)}</strong> queued</div></div></header>${renderedEntries || `<p class="empty">No entries yet.</p>`}<footer><span>Generated from versioned recommendation manifests.</span><span>Last updated ${prettyDate(new Date().toISOString())}</span></footer></main></body></html>`;
  const sitePath = "site/index.html";
  const siteFile = await workspace.read(sitePath, { format: "raw" }).catch(() => null);
  await workspace.edit(sitePath, {
    revision: siteFile?.revision || null,
    changes: [{ kind: "replaceFile", content: html }],
  });
  return {
    journalPath,
    sitePath,
    manifestId: input.manifestId,
    entries: entries.length,
    artists: manifestArtists.size,
