        if 0 <= wall <= 15 and 0 <= advanced <= 15: current['"'"'observedSeconds'"'"'] += min(wall,advanced)
        current['"'"'lastEventAt'"'"']=timestamp; current['"'"'_lastPosition'"'"']=position
finish(None)
for play in plays:
