  await shell.execFile("/usr/bin/python3",["-c",compact],{raise:true,maxBytes:1000,maxLines:10});
  try {
    return await publishMusicRecommendationJournalEntry(input.journal);
  } finally {
    await shell.execFile("mv",["/tmp/music-digest-recommendations-backup.jsonl","data/recommendations.jsonl"],{raise:true,maxBytes:1000,maxLines:10});
  }
}

