    "overridesProject": false,
    "overridesGlobal": false,
    "source": "/**
 * Match a recommendation manifest against macOS Apple Music playback logs and score completions, skips, and replays.
 *
 * @pit project
 */
async function evaluateRecommendedPlaylistListening(
  { workspace, shell },
  input: {
    manifestId: string;
    startDate: string;
    endDate?: string;
    write?: boolean;
  },
) {
  if (!input.manifestId) throw new Error("manifestId is required");
  const endDate = input.endDate || input.startDate;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(input.startDate) || !/^\d{4}-\d{2}-\d{2}$/.test(endDate))
    throw new Error("Dates must use YYYY-MM-DD format.");
  const dayCount =
    Math.floor(
      (new Date(`${endDate}T12:00:00`).getTime() -
        new Date(`${input.startDate}T12:00:00`).getTime()) /
        86400000,
    ) + 1;
  if (dayCount < 1 || dayCount > 31)
    throw new Error("Evaluation range must be between 1 and 31 days.");

  const manifestFile = await workspace.read("data/recommendations.jsonl", { format: "raw" });
  const manifests = manifestFile.content
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  const manifest = manifests.find((item) => item.id === input.manifestId);
  if (!manifest) throw new Error(`Manifest not found: ${input.manifestId}`);
  const nextDate = (
    await shell.execFile("/bin/date", ["-j", "-v+1d", "-f", "%Y-%m-%d", endDate, "+%F"], {
      maxBytes: 1000,
      maxLines: 5,
      raise: true,
    })
  ).stdout.trim();
  const normalize = (value: string) =>
    value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
  const wantedTitles = Array.from(
    new Set(manifest.tracks.map((track: any) => normalize(track.title))),
  );
  const wantedJson = JSON.stringify(wantedTitles);

  const python = `import sys,re,json,unicodedata
from datetime import datetime
wanted=set(json.loads(${JSON.stringify(wantedJson)}))
def norm(value):
    value=''.join(c for c in unicodedata.normalize('NFD',value) if unicodedata.category(c)!='Mn').lower()
    return ' '.join(re.sub(r'[^a-z0-9]+',' ',value).split())
albums={}
plays=[]
current=None
def finish(next_started=None):
    global current
    if current is not None and norm(current['title']) in wanted:
        current['nextStartedAt']=next_started
        plays.append(current)
for line in sys.stdin:
    a=re.search(r"Current song: contentIdentifier=([^ ,]+).*?album\\.identifiers=.*?storeAdamID=(\\d+)",line)
    if a: albums[a.group(1)]=a.group(2)
    m=re.search(r"^(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}\\.\\d+).*?time:([0-9.]+)s .*?item=<ITMPAVItem:.*?> \\(([^)]+)\\) (.*?) - reason:",line)
    if not m: continue
    timestamp,position,cid,title=m.groups(); position=float(position)
    restarted=current is not None and cid==current['contentId'] and position < 2 and current['_lastPosition'] > 30
    if current is None or cid!=current['contentId'] or restarted:
        finish(timestamp)
        current={'startedAt':timestamp,'lastEventAt':timestamp,'contentId':cid,'title':title.strip(),'observedSeconds':0.0,'_lastPosition':position}
    else:
        wall=(datetime.fromisoformat(timestamp)-datetime.fromisoformat(current['lastEventAt'])).total_seconds()
        advanced=position-current['_lastPosition']
        if 0 <= wall <= 15 and 0 <= advanced <= 15: current['observedSeconds'] += min(wall,advanced)
        current['lastEventAt']=timestamp; current['_lastPosition']=position
finish(None)
for play in plays:
    play['albumId']=albums.get(play['contentId'])
    play['observedSeconds']=round(play['observedSeconds'],1)
    play.pop('_lastPosition',None)
print(json.dumps(plays,ensure_ascii=False,separators=(',',':')))`;
  const predicate = `process == "Music" AND subsystem == "com.apple.amp.mediaplaybackcore" AND (eventMessage CONTAINS "playbackTimeDidChangeTo - Regular item" OR eventMessage CONTAINS "Current song: contentIdentifier=")`;
  const quote = (value: string) => `'${value.replace(/'/g, `'"'"'`)}'`;
  const command = `set -o pipefail; /usr/bin/log show --start ${quote(`${input.startDate} 00:00:00`)} --end ${quote(`${nextDate} 00:00:00`)} --style compact --predicate ${quote(predicate)} | /usr/bin/python3 -c ${quote(python)}`;
  const logResult = await shell.exec(command, {
    timeoutMs: 180000,
    maxBytes: 51200,
    maxLines: 20,
    raise: true,
  });
  if (logResult.truncated)
    throw new Error(
      "Matched playback history exceeded the safe output limit; use a shorter range.",
    );
  const plays = JSON.parse(logResult.stdout || "[]") as Array<{
    startedAt: string;
    lastEventAt: string;
    nextStartedAt: string | null;
    title: string;
    albumId: string | null;
    observedSeconds: number;
  }>;

  const feedbackTracks = manifest.tracks.map((track: any) => {
    const matches = plays.filter(
      (play) =>
        normalize(play.title) === normalize(track.title) &&
        (!track.albumId || !play.albumId || String(track.albumId) === String(play.albumId)),
    );
    const playDetails = matches.map((play) => {
      const ratio = Math.min(1, play.observedSeconds / track.durationSeconds);
      const transitionSeconds = play.nextStartedAt
        ? (new Date(play.nextStartedAt.replace(" ", "T")).getTime() -
            new Date(play.startedAt.replace(" ", "T")).getTime()) /
          1000
        : null;
      const earlySkip =
        play.observedSeconds < 30 && transitionSeconds != null && transitionSeconds <= 45;
      const completed = ratio >= 0.8;
      const score = earlySkip ? -2 : completed ? 2 : ratio >= 0.4 ? 1 : 0;
      return {
        startedAt: play.startedAt,
        observedSeconds: play.observedSeconds,
        completionRatio: Math.round(ratio * 1000) / 1000,
        earlySkip,
        completed,
        score,
      };
    });
    const replayBonus = Math.max(0, playDetails.length - 1) * 3;
    return {
      title: track.title,
      artist: track.artist,
      album: track.album,
      albumId: track.albumId,
      durationSeconds: track.durationSeconds,
      traits: track.traits || [],
      seeds: track.seeds || [],
      starts: playDetails.length,
      replays: Math.max(0, playDetails.length - 1),
      completedPlays: playDetails.filter((play) => play.completed).length,
      earlySkips: playDetails.filter((play) => play.earlySkip).length,
      totalObservedSeconds: Math.round(
        playDetails.reduce((sum, play) => sum + play.observedSeconds, 0),
      ),
      bestCompletionRatio: playDetails.length
        ? Math.max(...playDetails.map((play) => play.completionRatio))
        : 0,
      score: playDetails.reduce((sum, play) => sum + play.score, 0) + replayBonus,
      plays: playDetails,
    };
  });
  const evaluationId = `${input.manifestId}:${input.startDate}:${endDate}`;
  const record = {
    version: 1,
    id: evaluationId,
    manifestId: input.manifestId,
    playlist: manifest.playlist,
    evaluatedAt: new Date().toISOString(),
    startDate: input.startDate,
    endDate,
    tracks: feedbackTracks,
  };

  if (input.write !== false) {
    const path = "data/listening-feedback.jsonl";
    const current = await workspace.read(path, { format: "raw" }).catch(() => null);
    const records =
      current?.content
        .split("\n")
        .filter(Boolean)
        .map((line) => JSON.parse(line)) || [];
    const index = records.findIndex((item) => item.id === evaluationId);
    if (index >= 0) records[index] = record;
    else records.push(record);
    await workspace.edit(path, {
      revision: current?.revision || null,
      changes: [
        {
          kind: "replaceFile",
          content: records.map((item) => JSON.stringify(item)).join("\n") + "\n",
        },
      ],
    });
  }

  return {
    id: evaluationId,
    playlist: manifest.playlist,
    heard: feedbackTracks.filter((track: any) => track.starts > 0).length,
    unheard: feedbackTracks.filter((track: any) => track.starts === 0).length,
    completedPlays: feedbackTracks.reduce(
      (sum: number, track: any) => sum + track.completedPlays,
      0,
    ),
    earlySkips: feedbackTracks.reduce((sum: number, track: any) => sum + track.earlySkips, 0),
    replays: feedbackTracks.reduce((sum: number, track: any) => sum + track.replays, 0),
    totalScore: feedbackTracks.reduce((sum: number, track: any) => sum + track.score, 0),
    tracks: feedbackTracks,
    written: input.write !== false,
  };
}"
  },
  {
    "name": "publishMusicRecommendationJournalEntry",
    "scope": "project",
    "signature": "publishMusicRecommendationJournalEntry(input: { manifestId: string; headline: string; intro: string; narrative?: string; publishedAt?: string; tags?: string[]; artistNotes?: Array<{ artist: string; why: string; connections?: string; selectionNote?: string; }>; ifExists?: "replace" | "error"; country?: string; })",
    "lines": 204,
    "bytes": 14400,
    "directDependencies": [],
    "directDependents": [
      "rebuildMusicRecommendationJournal"
    ],
    "overridesProject": false,
    "overridesGlobal": false,
    "source": "/**
 * Publish or replace a richly annotated daily recommendation entry and rebuild a visual static HTML listening journal.
 *
 * @pit project
 */
async function publishMusicRecommendationJournalEntry(
  { workspace, http },
  input: {
    manifestId: string;
    headline: string;
    intro: string;
    narrative?: string;
    publishedAt?: string;
    tags?: string[];
    artistNotes?: Array<{
      artist: string;
      why: string;
      connections?: string;
      selectionNote?: string;
    }>;
    ifExists?: "replace" | "error";
    country?: string;
  },
) {
  if (!input.manifestId || !input.headline?.trim() || !input.intro?.trim())
    throw new Error("manifestId, headline, and intro are required.");
  const country = (input.country || "BR").toUpperCase();
  const recommendations = await workspace.read("data/recommendations.jsonl", { format: "raw" });
  const manifests = recommendations.content
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  const manifest = manifests.find((item) => item.id === input.manifestId);
  if (!manifest) throw new Error(`Manifest not found: ${input.manifestId}`);
  const manifestArtists = new Set(manifest.tracks.map((track: any) => track.artist));
  for (const note of input.artistNotes || [])
    if (!manifestArtists.has(note.artist))
      throw new Error(`Artist note does not match manifest: ${note.artist}`);

  const journalPath = "data/journal.jsonl";
  const journalFile = await workspace.read(journalPath, { format: "raw" }).catch(() => null);
  const entries =
    journalFile?.content
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line)) || [];
  const existingIndex = entries.findIndex((entry) => entry.manifestId === input.manifestId);
  if (existingIndex >= 0 && (input.ifExists || "error") === "error")
    throw new Error(`Journal entry already exists for ${input.manifestId}`);
  const entry = {
    version: 1,
    manifestId: input.manifestId,
    headline: input.headline,
    intro: input.intro,
    narrative: input.narrative || null,
    publishedAt: input.publishedAt || new Date().toISOString(),
    tags: Array.from(new Set(input.tags || [])),
    artistNotes: input.artistNotes || [],
    updatedAt: new Date().toISOString(),
  };
  if (existingIndex >= 0) entries[existingIndex] = entry;
  else entries.push(entry);
  entries.sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)));
  await workspace.edit(journalPath, {
    revision: journalFile?.revision || null,
    changes: [
      {
        kind: "replaceFile",
        content: entries.map((item) => JSON.stringify(item)).join("\n") + "\n",
      },
    ],
  });

  const albumIds = Array.from(
    new Set(
      entries.flatMap((journal) => {
        const related = manifests.find((item) => item.id === journal.manifestId);
        return (related?.tracks || []).map((track: any) => track.albumId).filter(Boolean);
      }),
    ),
  ) as string[];
  const artwork = new Map<string, string>();
  const chunks: string[][] = [];
  for (let index = 0; index < albumIds.length; index += 20)
    chunks.push(albumIds.slice(index, index + 20));
  const lookups = await Promise.allSettled(
    chunks.map((ids) =>
      http.request(`https://itunes.apple.com/lookup?id=${ids.join(",")}&country=${country}`, {
        maxBytes: 51200,
      }),
    ),
  );
  for (const lookup of lookups) {
    if (lookup.status !== "fulfilled" || !lookup.value.ok) continue;
    const body = JSON.parse(lookup.value.body) as {
      results?: Array<{ collectionId?: number; artworkUrl100?: string }>;
    };
    for (const item of body.results || [])
      if (item.collectionId && item.artworkUrl100)
        artwork.set(
          String(item.collectionId),
          item.artworkUrl100.replace("100x100bb", "600x600bb"),
        );
  }

  const esc = (value: unknown) =>
    String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
