/**
 * Record versioned recommendation provenance, seed artists, traits, reasons, catalog IDs, and durations for a generated playlist.
 *
 * @pit project
 */
async function recordMusicRecommendationManifest(
  { workspace },
  input: {
    playlist: string;
    manifestId?: string;
    createdAt?: string;
    targetMinutes?: number;
    description?: string;
    tracks: Array<{
      title: string;
      artist: string;
      album?: string;
      albumId?: string | number;
      trackId?: string | number;
      durationSeconds: number;
      seeds?: string[];
      traits?: string[];
      reason?: string;
      albumUrl?: string;
    }>;
    ifExists?: "replace" | "error";
  },
) {
  if (!input.playlist?.trim()) throw new Error("playlist is required");
  if (!input.tracks?.length) throw new Error("Provide at least one recommended track.");
  const createdAt = input.createdAt || new Date().toISOString();
  const date = createdAt.slice(0, 10);
  const slug = input.playlist
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
  const id = input.manifestId || `${date}-${slug}`;
  const seen = new Set<string>();
  const tracks = input.tracks.map((track, index) => {
    if (!track.title?.trim() || !track.artist?.trim() || !(track.durationSeconds > 0))
      throw new Error(`Invalid track at position ${index + 1}.`);
    const key = `${track.title.toLowerCase()}\u0000${track.artist.toLowerCase()}`;
    if (seen.has(key))
      throw new Error(`Duplicate track in manifest: ${track.title} — ${track.artist}`);
    seen.add(key);
    return {
      position: index + 1,
      title: track.title,
      artist: track.artist,
      album: track.album || null,
      albumId: track.albumId != null ? String(track.albumId) : null,
      trackId: track.trackId != null ? String(track.trackId) : null,
      durationSeconds: Math.round(track.durationSeconds),
      seeds: Array.from(new Set(track.seeds || [])),
      traits: Array.from(new Set(track.traits || [])),
      reason: track.reason || null,
      albumUrl: track.albumUrl || null,
    };
  });
  const record = {
    version: 1,
    id,
    playlist: input.playlist,
    createdAt,
    targetMinutes: input.targetMinutes || null,
    description: input.description || null,
    tracks,
  };
  const path = "data/recommendations.jsonl";
  const current = await workspace.read(path, { format: "raw" }).catch(() => null);
  const records =
    current?.content
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line)) || [];
  const existingIndex = records.findIndex((item) => item.id === id);
  if (existingIndex >= 0 && (input.ifExists || "error") === "error")
    throw new Error(`Manifest already exists: ${id}`);
  if (existingIndex >= 0) records[existingIndex] = record;
  else records.push(record);
  const content = records.map((item) => JSON.stringify(item)).join("\n") + "\n";
  await workspace.edit(path, {
    revision: current?.revision || null,
    changes: [{ kind: "replaceFile", content }],
  });
  return {
    path,
    id,
    playlist: input.playlist,
    trackCount: tracks.length,
    totalSeconds: tracks.reduce((sum, track) => sum + track.durationSeconds, 0),
    replaced: existingIndex >= 0,
  };
}

/**
 * Record explicit track, artist, or trait feedback with stronger learning weights than inferred playback behavior.
 *
 * @pit project
 */
async function recordExplicitMusicFeedback(
  { workspace },
  input: {
    manifestId: string;
    track?: string;
    artist?: string;
    trait?: string;
    sentiment: "love" | "like" | "neutral" | "dislike" | "never";
    note?: string;
    recordedAt?: string;
    feedbackId?: string;
    ifExists?: "replace" | "error";
    dryRun?: boolean;
  },
) {
  if (!input.manifestId) throw new Error("manifestId is required");
  const targets = [input.track, input.artist, input.trait].filter((value) => value?.trim());
  if (targets.length !== 1) throw new Error("Provide exactly one of track, artist, or trait.");
  const scoreBySentiment = { love: 4, like: 2, neutral: 0, dislike: -3, never: -6 } as const;
  const recommendations = await workspace.read("data/recommendations.jsonl", { format: "raw" });
  const manifests = recommendations.content
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  const manifest = manifests.find((item) => item.id === input.manifestId);
  if (!manifest) throw new Error(`Manifest not found: ${input.manifestId}`);
  const normalize = (value: string) =>
    value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();

  let targetType: "track" | "artist" | "trait";
  let target: string;
  let artist: string | null = null;
  let title: string | null = null;
  let traits: string[] = [];
  if (input.track) {
    targetType = "track";
    target = input.track;
    const matched = manifest.tracks.find(
      (item: any) => normalize(item.title) === normalize(input.track!),
    );
    if (!matched) throw new Error(`Track not found in manifest: ${input.track}`);
    title = matched.title;
    artist = matched.artist;
    traits = matched.traits || [];
  } else if (input.artist) {
    targetType = "artist";
    target = input.artist;
    const tracks = manifest.tracks.filter(
      (item: any) => normalize(item.artist) === normalize(input.artist!),
    );
    if (!tracks.length) throw new Error(`Artist not found in manifest: ${input.artist}`);
    artist = tracks[0].artist;
    traits = Array.from(new Set(tracks.flatMap((item: any) => item.traits || []))) as string[];
  } else {
    targetType = "trait";
    target = input.trait!;
    const available = new Map<string, string>();
    for (const item of manifest.tracks)
      for (const value of item.traits || []) available.set(normalize(value), value);
    const canonical = available.get(normalize(input.trait!));
    if (!canonical) throw new Error(`Trait not found in manifest: ${input.trait}`);
    target = canonical;
    traits = [canonical];
  }

  const recordedAt = input.recordedAt || new Date().toISOString();
  const id =
    input.feedbackId ||
    `${input.manifestId}:${targetType}:${normalize(target).replace(/ /g, "-")}:${recordedAt}`;
  const record = {
    version: 1,
    id,
    manifestId: input.manifestId,
    playlist: manifest.playlist,
    recordedAt,
    targetType,
    target,
    title,
    artist,
    traits,
    sentiment: input.sentiment,
    score: scoreBySentiment[input.sentiment],
    note: input.note || null,
  };
  if (input.dryRun) return { dryRun: true, record };

  const path = "data/explicit-feedback.jsonl";
  const current = await workspace.read(path, { format: "raw" }).catch(() => null);
  const records =
    current?.content
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line)) || [];
  const index = records.findIndex((item) => item.id === id);
  if (index >= 0 && (input.ifExists || "error") === "error")
    throw new Error(`Feedback already exists: ${id}`);
  if (index >= 0) records[index] = record;
  else records.push(record);
  await workspace.edit(path, {
    revision: current?.revision || null,
    changes: [
      {
        kind: "replaceFile",
        content: records.map((item) => JSON.stringify(item)).join("\n") + "\n",
      },
    ],
  });
  return {
    dryRun: false,
    path,
    id,
    targetType,
    target,
    sentiment: input.sentiment,
    score: record.score,
    replaced: index >= 0,
  };
}

/**
 * Match a recommendation manifest against macOS Apple Music playback logs and score completions, skips, and replays.
 *
 * @pit project
 */
async function evaluateRecommendedPlaylistListening(
  { workspace, shell },
  input: {
    manifestId: string;
    startDate: string;
    endDate?: string;
    write?: boolean;
  },
) {
  if (!input.manifestId) throw new Error("manifestId is required");
  const endDate = input.endDate || input.startDate;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(input.startDate) || !/^\d{4}-\d{2}-\d{2}$/.test(endDate))
    throw new Error("Dates must use YYYY-MM-DD format.");
  const dayCount =
    Math.floor(
      (new Date(`${endDate}T12:00:00`).getTime() -
        new Date(`${input.startDate}T12:00:00`).getTime()) /
        86400000,
    ) + 1;
  if (dayCount < 1 || dayCount > 31)
    throw new Error("Evaluation range must be between 1 and 31 days.");

  const manifestFile = await workspace.read("data/recommendations.jsonl", { format: "raw" });
  const manifests = manifestFile.content
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  const manifest = manifests.find((item) => item.id === input.manifestId);
  if (!manifest) throw new Error(`Manifest not found: ${input.manifestId}`);
  const nextDate = (
    await shell.execFile("/bin/date", ["-j", "-v+1d", "-f", "%Y-%m-%d", endDate, "+%F"], {
      maxBytes: 1000,
      maxLines: 5,
      raise: true,
    })
  ).stdout.trim();
  const normalize = (value: string) =>
    value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
  const wantedTitles = Array.from(
    new Set(manifest.tracks.map((track: any) => normalize(track.title))),
  );
  const wantedJson = JSON.stringify(wantedTitles);

  const python = `import sys,re,json,unicodedata
from datetime import datetime
wanted=set(json.loads(${JSON.stringify(wantedJson)}))
def norm(value):
    value=''.join(c for c in unicodedata.normalize('NFD',value) if unicodedata.category(c)!='Mn').lower()
    return ' '.join(re.sub(r'[^a-z0-9]+',' ',value).split())
albums={}
plays=[]
current=None
def finish(next_started=None):
    global current
    if current is not None and norm(current['title']) in wanted:
        current['nextStartedAt']=next_started
        plays.append(current)
for line in sys.stdin:
    a=re.search(r"Current song: contentIdentifier=([^ ,]+).*?album\\.identifiers=.*?storeAdamID=(\\d+)",line)
    if a: albums[a.group(1)]=a.group(2)
    m=re.search(r"^(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}\\.\\d+).*?time:([0-9.]+)s .*?item=<ITMPAVItem:.*?> \\(([^)]+)\\) (.*?) - reason:",line)
    if not m: continue
    timestamp,position,cid,title=m.groups(); position=float(position)
    restarted=current is not None and cid==current['contentId'] and position < 2 and current['_lastPosition'] > 30
    if current is None or cid!=current['contentId'] or restarted:
        finish(timestamp)
        current={'startedAt':timestamp,'lastEventAt':timestamp,'contentId':cid,'title':title.strip(),'observedSeconds':0.0,'_lastPosition':position}
    else:
        wall=(datetime.fromisoformat(timestamp)-datetime.fromisoformat(current['lastEventAt'])).total_seconds()
        advanced=position-current['_lastPosition']
        if 0 <= wall <= 15 and 0 <= advanced <= 15: current['observedSeconds'] += min(wall,advanced)
        current['lastEventAt']=timestamp; current['_lastPosition']=position
finish(None)
for play in plays:
    play['albumId']=albums.get(play['contentId'])
    play['observedSeconds']=round(play['observedSeconds'],1)
    play.pop('_lastPosition',None)
print(json.dumps(plays,ensure_ascii=False,separators=(',',':')))`;
  const predicate = `process == "Music" AND subsystem == "com.apple.amp.mediaplaybackcore" AND (eventMessage CONTAINS "playbackTimeDidChangeTo - Regular item" OR eventMessage CONTAINS "Current song: contentIdentifier=")`;
  const quote = (value: string) => `'${value.replace(/'/g, `'"'"'`)}'`;
  const command = `set -o pipefail; /usr/bin/log show --start ${quote(`${input.startDate} 00:00:00`)} --end ${quote(`${nextDate} 00:00:00`)} --style compact --predicate ${quote(predicate)} | /usr/bin/python3 -c ${quote(python)}`;
  const logResult = await shell.exec(command, {
    timeoutMs: 180000,
    maxBytes: 51200,
    maxLines: 20,
    raise: true,
  });
  if (logResult.truncated)
    throw new Error(
      "Matched playback history exceeded the safe output limit; use a shorter range.",
    );
  const plays = JSON.parse(logResult.stdout || "[]") as Array<{
    startedAt: string;
    lastEventAt: string;
    nextStartedAt: string | null;
    title: string;
    albumId: string | null;
    observedSeconds: number;
  }>;

  const feedbackTracks = manifest.tracks.map((track: any) => {
    const matches = plays.filter(
      (play) =>
        normalize(play.title) === normalize(track.title) &&
        (!track.albumId || !play.albumId || String(track.albumId) === String(play.albumId)),
    );
    const playDetails = matches.map((play) => {
      const ratio = Math.min(1, play.observedSeconds / track.durationSeconds);
      const transitionSeconds = play.nextStartedAt
        ? (new Date(play.nextStartedAt.replace(" ", "T")).getTime() -
            new Date(play.startedAt.replace(" ", "T")).getTime()) /
          1000
        : null;
      const earlySkip =
        play.observedSeconds < 30 && transitionSeconds != null && transitionSeconds <= 45;
      const completed = ratio >= 0.8;
      const score = earlySkip ? -2 : completed ? 2 : ratio >= 0.4 ? 1 : 0;
      return {
        startedAt: play.startedAt,
        observedSeconds: play.observedSeconds,
        completionRatio: Math.round(ratio * 1000) / 1000,
        earlySkip,
        completed,
        score,
      };
    });
    const replayBonus = Math.max(0, playDetails.length - 1) * 3;
    return {
      title: track.title,
      artist: track.artist,
      album: track.album,
      albumId: track.albumId,
      durationSeconds: track.durationSeconds,
      traits: track.traits || [],
      seeds: track.seeds || [],
      starts: playDetails.length,
      replays: Math.max(0, playDetails.length - 1),
      completedPlays: playDetails.filter((play) => play.completed).length,
      earlySkips: playDetails.filter((play) => play.earlySkip).length,
      totalObservedSeconds: Math.round(
        playDetails.reduce((sum, play) => sum + play.observedSeconds, 0),
      ),
      bestCompletionRatio: playDetails.length
        ? Math.max(...playDetails.map((play) => play.completionRatio))
        : 0,
      score: playDetails.reduce((sum, play) => sum + play.score, 0) + replayBonus,
      plays: playDetails,
    };
  });
  const evaluationId = `${input.manifestId}:${input.startDate}:${endDate}`;
  const record = {
    version: 1,
    id: evaluationId,
    manifestId: input.manifestId,
    playlist: manifest.playlist,
    evaluatedAt: new Date().toISOString(),
    startDate: input.startDate,
    endDate,
    tracks: feedbackTracks,
  };

  if (input.write !== false) {
    const path = "data/listening-feedback.jsonl";
    const current = await workspace.read(path, { format: "raw" }).catch(() => null);
    const records =
      current?.content
        .split("\n")
        .filter(Boolean)
        .map((line) => JSON.parse(line)) || [];
    const index = records.findIndex((item) => item.id === evaluationId);
    if (index >= 0) records[index] = record;
    else records.push(record);
    await workspace.edit(path, {
      revision: current?.revision || null,
      changes: [
        {
          kind: "replaceFile",
          content: records.map((item) => JSON.stringify(item)).join("\n") + "\n",
        },
      ],
    });
  }

  return {
    id: evaluationId,
    playlist: manifest.playlist,
    heard: feedbackTracks.filter((track: any) => track.starts > 0).length,
    unheard: feedbackTracks.filter((track: any) => track.starts === 0).length,
    completedPlays: feedbackTracks.reduce(
      (sum: number, track: any) => sum + track.completedPlays,
      0,
    ),
    earlySkips: feedbackTracks.reduce((sum: number, track: any) => sum + track.earlySkips, 0),
    replays: feedbackTracks.reduce((sum: number, track: any) => sum + track.replays, 0),
    totalScore: feedbackTracks.reduce((sum: number, track: any) => sum + track.score, 0),
    tracks: feedbackTracks,
    written: input.write !== false,
  };
}

/**
 * Publish or replace a richly annotated daily recommendation entry and rebuild a visual static HTML listening journal.
 *
 * @pit project
 */
async function publishMusicRecommendationJournalEntry(
  { workspace, http },
  input: {
    manifestId: string;
    headline: string;
    intro: string;
    narrative?: string;
    publishedAt?: string;
    tags?: string[];
    artistNotes?: Array<{
      artist: string;
      why: string;
      connections?: string;
      selectionNote?: string;
    }>;
    ifExists?: "replace" | "error";
    country?: string;
  },
) {
  if (!input.manifestId || !input.headline?.trim() || !input.intro?.trim())
    throw new Error("manifestId, headline, and intro are required.");
  const country = (input.country || "BR").toUpperCase();
  const recommendations = await workspace.read("data/recommendations.jsonl", { format: "raw" });
  const manifests = recommendations.content
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  const manifest = manifests.find((item) => item.id === input.manifestId);
  if (!manifest) throw new Error(`Manifest not found: ${input.manifestId}`);
  const manifestArtists = new Set(manifest.tracks.map((track: any) => track.artist));
  for (const note of input.artistNotes || [])
    if (!manifestArtists.has(note.artist))
      throw new Error(`Artist note does not match manifest: ${note.artist}`);

  const journalPath = "data/journal.jsonl";
  const journalFile = await workspace.read(journalPath, { format: "raw" }).catch(() => null);
  const entries =
    journalFile?.content
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line)) || [];
  const existingIndex = entries.findIndex((entry) => entry.manifestId === input.manifestId);
  if (existingIndex >= 0 && (input.ifExists || "error") === "error")
    throw new Error(`Journal entry already exists for ${input.manifestId}`);
  const entry = {
    version: 1,
    manifestId: input.manifestId,
    headline: input.headline,
    intro: input.intro,
    narrative: input.narrative || null,
    publishedAt: input.publishedAt || new Date().toISOString(),
    tags: Array.from(new Set(input.tags || [])),
    artistNotes: input.artistNotes || [],
    updatedAt: new Date().toISOString(),
  };
  if (existingIndex >= 0) entries[existingIndex] = entry;
  else entries.push(entry);
  entries.sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)));
  await workspace.edit(journalPath, {
    revision: journalFile?.revision || null,
    changes: [
      {
        kind: "replaceFile",
        content: entries.map((item) => JSON.stringify(item)).join("\n") + "\n",
      },
    ],
  });

  const albumIds = Array.from(
    new Set(
      entries.flatMap((journal) => {
        const related = manifests.find((item) => item.id === journal.manifestId);
        return (related?.tracks || []).map((track: any) => track.albumId).filter(Boolean);
      }),
    ),
  ) as string[];
  const artwork = new Map<string, string>();
  const chunks: string[][] = [];
  for (let index = 0; index < albumIds.length; index += 20)
    chunks.push(albumIds.slice(index, index + 20));
  const lookups = await Promise.allSettled(
    chunks.map((ids) =>
      http.request(`https://itunes.apple.com/lookup?id=${ids.join(",")}&country=${country}`, {
        maxBytes: 51200,
      }),
    ),
  );
  for (const lookup of lookups) {
    if (lookup.status !== "fulfilled" || !lookup.value.ok) continue;
    const body = JSON.parse(lookup.value.body) as {
      results?: Array<{ collectionId?: number; artworkUrl100?: string }>;
    };
    for (const item of body.results || [])
      if (item.collectionId && item.artworkUrl100)
        artwork.set(
          String(item.collectionId),
          item.artworkUrl100.replace("100x100bb", "600x600bb"),
        );
  }

  const esc = (value: unknown) =>
    String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  const duration = (seconds: number) =>
    `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, "0")}`;
  const longDuration = (seconds: number) =>
    `${Math.floor(seconds / 3600)}h ${String(Math.floor((seconds % 3600) / 60)).padStart(2, "0")}m`;
  const prettyDate = (value: string) =>
    new Intl.DateTimeFormat("en", {
      month: "long",
      day: "numeric",
      year: "numeric",
      timeZone: "UTC",
    }).format(new Date(value));
  const hashHue = (value: string) =>
    [...value].reduce((sum, char) => (sum * 31 + char.charCodeAt(0)) % 360, 0);

  const renderedEntries = entries
    .map((journal, entryIndex) => {
      const related = manifests.find((item) => item.id === journal.manifestId);
      if (!related) return "";
      const grouped = new Map<string, any[]>();
      for (const track of related.tracks)
        grouped.set(track.artist, [...(grouped.get(track.artist) || []), track]);
      const notes = new Map((journal.artistNotes || []).map((note: any) => [note.artist, note]));
      const totalSeconds = related.tracks.reduce(
        (sum: number, track: any) => sum + track.durationSeconds,
        0,
      );
      const artistCards = [...grouped.entries()]
        .map(([artist, tracks]) => {
          const note: any = notes.get(artist) || {};
          const first = tracks[0];
          const art = first.albumId ? artwork.get(String(first.albumId)) : null;
          const trackRows = tracks
            .map(
              (track: any) =>
                `<li><a href="${esc(track.albumUrl || "#")}" target="_blank" rel="noreferrer"><span>${esc(track.title)}</span><time>${duration(track.durationSeconds)}</time></a></li>`,
            )
            .join("");
          return `<section class="artist-card" style="--h:${hashHue(artist)}">
        <div class="cover-wrap">${art ? `<img src="${esc(art)}" alt="Cover of ${esc(first.album)}" loading="lazy">` : `<div class="cover-fallback">${esc(artist.slice(0, 1))}</div>`}<span class="card-number">${String([...grouped.keys()].indexOf(artist) + 1).padStart(2, "0")}</span></div>
        <div class="artist-copy"><p class="album-label">${esc(first.album)}</p><h3>${esc(artist)}</h3>
        <p class="why">${esc(note.why || first.reason || "Selected as a representative next step from your recent listening.")}</p>
        ${note.connections ? `<p class="connection"><strong>Connection</strong> ${esc(note.connections)}</p>` : ""}
        ${note.selectionNote ? `<p class="selection"><strong>Why these tracks</strong> ${esc(note.selectionNote)}</p>` : ""}
        <ol class="track-list">${trackRows}</ol></div></section>`;
        })
        .join("");
      return `<article class="entry" id="${esc(journal.manifestId)}">
      <header class="entry-head"><div class="date-stamp"><span>${prettyDate(journal.publishedAt)}</span><i></i></div>
      <p class="kicker">Entry ${String(entries.length - entryIndex).padStart(2, "0")} · ${esc(related.playlist)}</p>
      <h2>${esc(journal.headline)}</h2><p class="intro">${esc(journal.intro)}</p>
      <div class="entry-meta"><span>${related.tracks.length} tracks</span><span>${grouped.size} artists</span><span>${longDuration(totalSeconds)}</span></div>
      ${(journal.tags || []).length ? `<div class="tags">${journal.tags.map((tag: string) => `<span>${esc(tag)}</span>`).join("")}</div>` : ""}
      ${journal.narrative ? `<div class="narrative"><span>Field notes</span><p>${esc(journal.narrative)}</p></div>` : ""}</header>
      <div class="artist-grid">${artistCards}</div></article>`;
    })
    .join("\n");

  const allManifests = entries
    .map((item) => manifests.find((manifestItem) => manifestItem.id === item.manifestId))
    .filter(Boolean);
  const totalTracks = allManifests.reduce((sum, item) => sum + item.tracks.length, 0);
  const totalSeconds = allManifests.reduce(
    (sum, item) =>
      sum +
      item.tracks.reduce((trackSum: number, track: any) => trackSum + track.durationSeconds, 0),
    0,
  );
  const uniqueArtists = new Set(
    allManifests.flatMap((item) => item.tracks.map((track: any) => track.artist)),
  ).size;
  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Listening Notes · Music Recommendations</title>
<style>
:root{--ink:#f4f0e8;--muted:#a9a49a;--paper:#11110f;--panel:#191916;--line:#34332c;--acid:#d8ff63;--orange:#ff7a45}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 82% 4%,#322315 0,transparent 26rem),radial-gradient(circle at 8% 28%,#18352d 0,transparent 28rem),var(--paper);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;line-height:1.55}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.18;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.2'/%3E%3C/svg%3E")}.shell{width:min(1240px,calc(100% - 40px));margin:auto}.hero{min-height:72vh;display:grid;align-content:center;padding:80px 0 64px;border-bottom:1px solid var(--line)}.eyebrow,.kicker,.album-label,.narrative>span{text-transform:uppercase;letter-spacing:.18em;font-size:.72rem;font-weight:800;color:var(--acid)}h1,h2,h3{font-family:Georgia,"Times New Roman",serif;font-weight:500;line-height:.95;margin:0}h1{font-size:clamp(4rem,12vw,10rem);letter-spacing:-.07em;max-width:1000px}.hero-copy{max-width:660px;font-size:1.15rem;color:var(--muted);margin:32px 0}.stats{display:flex;gap:12px;flex-wrap:wrap}.stats div,.entry-meta span{border:1px solid var(--line);border-radius:999px;padding:9px 15px;background:#ffffff08}.stats strong{color:var(--acid)}.entry{padding:100px 0;border-bottom:1px solid var(--line)}.entry-head{display:grid;grid-template-columns:minmax(0,1fr) minmax(260px,420px);column-gap:64px;align-items:end;margin-bottom:56px}.date-stamp,.kicker,h2,.intro,.entry-meta,.tags{grid-column:1}.date-stamp{display:flex;align-items:center;gap:18px;color:var(--muted);font-size:.85rem;margin-bottom:30px}.date-stamp i{height:1px;background:var(--line);flex:1}.entry h2{font-size:clamp(3rem,7vw,6.5rem);letter-spacing:-.055em;max-width:850px}.intro{font-size:1.25rem;max-width:720px;color:#d7d1c5;margin:28px 0}.entry-meta{display:flex;gap:8px;flex-wrap:wrap}.tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.tags span{font-size:.72rem;text-transform:uppercase;letter-spacing:.12em;color:#111;background:var(--acid);padding:6px 10px;border-radius:2px}.narrative{grid-column:2;grid-row:2/8;border-left:1px solid var(--line);padding-left:32px;color:var(--muted)}.narrative p{font-family:Georgia,serif;font-size:1.15rem;color:#d7d1c5}.artist-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.artist-card{display:grid;grid-template-columns:200px 1fr;background:linear-gradient(145deg,hsl(var(--h) 24% 18%),var(--panel) 42%);border:1px solid #ffffff14;min-height:390px;overflow:hidden;box-shadow:0 20px 60px #0004;transition:transform .25s,border-color .25s}.artist-card:hover{transform:translateY(-4px);border-color:hsl(var(--h) 70% 60% / .5)}.cover-wrap{position:relative;min-height:100%;background:hsl(var(--h) 35% 22%);overflow:hidden}.cover-wrap img{width:100%;height:100%;object-fit:cover;filter:saturate(.82) contrast(1.05);transition:transform .5s}.artist-card:hover img{transform:scale(1.03)}.cover-fallback{height:100%;display:grid;place-items:center;font:8rem Georgia;color:#ffffff33}.card-number{position:absolute;top:12px;left:12px;background:#111d;padding:5px 8px;font-size:.7rem;letter-spacing:.12em}.artist-copy{padding:26px}.artist-copy h3{font-size:2.15rem;letter-spacing:-.035em}.album-label{color:hsl(var(--h) 75% 70%);margin:0 0 10px}.why{color:#d8d2c7}.connection,.selection{font-size:.86rem;color:var(--muted);border-top:1px solid #ffffff12;padding-top:10px}.connection strong,.selection strong{display:block;color:var(--ink);text-transform:uppercase;font-size:.65rem;letter-spacing:.12em}.track-list{list-style:none;padding:0;margin:18px 0 0;border-top:1px solid #ffffff14}.track-list li{border-bottom:1px solid #ffffff14}.track-list a{display:flex;justify-content:space-between;gap:14px;padding:9px 0;color:var(--ink);text-decoration:none;font-size:.86rem}.track-list a:hover span{color:var(--acid)}.track-list time{color:var(--muted);font-variant-numeric:tabular-nums}footer{padding:60px 0;color:var(--muted);display:flex;justify-content:space-between}.empty{padding:100px 0}@media(max-width:900px){.entry-head{grid-template-columns:1fr}.narrative{grid-column:1;grid-row:auto;margin-top:32px}.artist-grid{grid-template-columns:1fr}}@media(max-width:580px){.shell{width:min(100% - 24px,1240px)}.hero{min-height:60vh}.artist-card{grid-template-columns:1fr}.cover-wrap{height:280px}.entry{padding:72px 0}h1{font-size:4.3rem}footer{display:block}}
</style></head><body><main class="shell"><header class="hero"><p class="eyebrow">A private recommendation journal</p><h1>Listening<br>Notes</h1><p class="hero-copy">A growing field guide to the records, scenes, collaborators and musical detours worth hearing next.</p><div class="stats"><div><strong>${entries.length}</strong> entries</div><div><strong>${totalTracks}</strong> tracks</div><div><strong>${uniqueArtists}</strong> artists</div><div><strong>${longDuration(totalSeconds)}</strong> queued</div></div></header>${renderedEntries || `<p class="empty">No entries yet.</p>`}<footer><span>Generated from versioned recommendation manifests.</span><span>Last updated ${prettyDate(new Date().toISOString())}</span></footer></main></body></html>`;
  const sitePath = "site/index.html";
  const siteFile = await workspace.read(sitePath, { format: "raw" }).catch(() => null);
  await workspace.edit(sitePath, {
    revision: siteFile?.revision || null,
    changes: [{ kind: "replaceFile", content: html }],
  });
  return {
    journalPath,
    sitePath,
    manifestId: input.manifestId,
    entries: entries.length,
    artists: manifestArtists.size,
    tracks: manifest.tracks.length,
    replaced: existingIndex >= 0,
    bytes: html.length,
  };
}

/**
 * Build a recency-weighted artist and trait profile from deduplicated playback behavior and explicit feedback.
 *
 * @pit project
 */
async function updateMusicTasteProfile(
  { workspace },
  input: { halfLifeDays?: number; write?: boolean } = {},
) {
  const halfLifeDays = Math.max(7, Math.min(730, input.halfLifeDays || 180));
  const [feedbackFile, explicitFile] = await Promise.all([
    workspace.read("data/listening-feedback.jsonl", { format: "raw" }).catch(() => null),
    workspace.read("data/explicit-feedback.jsonl", { format: "raw" }).catch(() => null),
  ]);
  const evaluations =
    feedbackFile?.content
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line)) || [];
  const explicitFeedback =
    explicitFile?.content
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line)) || [];
  type Aggregate = {
    name: string;
    weightedScore: number;
    evidenceWeight: number;
    events: number;
    inferredEvents: number;
    explicitEvents: number;
  };
  const artists = new Map<string, Aggregate>();
  const traits = new Map<string, Aggregate>();
  const seenPlays = new Set<string>();
  const seenExplicit = new Set<string>();
  const now = Date.now();

  const add = (
    map: Map<string, Aggregate>,
    name: string,
    score: number,
    weight: number,
    source: "inferred" | "explicit",
  ) => {
    if (!name) return;
    const current = map.get(name) || {
      name,
      weightedScore: 0,
      evidenceWeight: 0,
      events: 0,
      inferredEvents: 0,
      explicitEvents: 0,
    };
    current.weightedScore += score * weight;
    current.evidenceWeight += weight;
    current.events += 1;
    if (source === "explicit") current.explicitEvents += 1;
    else current.inferredEvents += 1;
    map.set(name, current);
  };
  const recencyWeight = (value: string, scale = 1) => {
    const timestamp = new Date(value.replace(" ", "T")).getTime();
    const ageDays = Number.isFinite(timestamp) ? Math.max(0, (now - timestamp) / 86400000) : 0;
    return Math.pow(0.5, ageDays / halfLifeDays) * scale;
  };

  for (const evaluation of evaluations) {
    for (const track of evaluation.tracks || []) {
      for (const play of track.plays || []) {
        const key = `${evaluation.manifestId}\u0000${track.title}\u0000${play.startedAt}`;
        if (seenPlays.has(key)) continue;
        seenPlays.add(key);
        const weight = recencyWeight(play.startedAt);
        add(artists, track.artist, play.score, weight, "inferred");
        for (const trait of track.traits || []) add(traits, trait, play.score, weight, "inferred");
      }
    }
  }

  for (const feedback of explicitFeedback) {
    if (seenExplicit.has(feedback.id)) continue;
    seenExplicit.add(feedback.id);
    const weight = recencyWeight(feedback.recordedAt, 2);
    if (feedback.artist) add(artists, feedback.artist, feedback.score, weight, "explicit");
    if (feedback.targetType === "trait")
      add(traits, feedback.target, feedback.score, weight, "explicit");
    else
      for (const trait of feedback.traits || [])
        add(
          traits,
          trait,
          feedback.targetType === "artist" ? feedback.score * 0.5 : feedback.score,
          weight,
          "explicit",
        );
  }

  const rank = (map: Map<string, Aggregate>) =>
    [...map.values()]
      .map((item) => {
        const averageScore = item.evidenceWeight ? item.weightedScore / item.evidenceWeight : 0;
        const confidence = 1 - Math.exp(-item.evidenceWeight / 3);
        return {
          name: item.name,
          preference: Math.round(averageScore * confidence * 1000) / 1000,
          averageScore: Math.round(averageScore * 1000) / 1000,
          confidence: Math.round(confidence * 1000) / 1000,
          evidence: item.events,
          inferredEvents: item.inferredEvents,
          explicitEvents: item.explicitEvents,
          evidenceWeight: Math.round(item.evidenceWeight * 1000) / 1000,
        };
      })
      .sort((a, b) => b.preference - a.preference || b.evidence - a.evidence);

  const profile = {
    version: 2,
    generatedAt: new Date().toISOString(),
    halfLifeDays,
    sourceEvaluations: evaluations.length,
    sourceExplicitFeedback: explicitFeedback.length,
    uniquePlayEvents: seenPlays.size,
    uniqueExplicitEvents: seenExplicit.size,
    artists: rank(artists),
    traits: rank(traits),
  };
  if (input.write !== false) {
    const path = "data/taste-profile.json";
    const current = await workspace.read(path, { format: "raw" }).catch(() => null);
    await workspace.edit(path, {
      revision: current?.revision || null,
      changes: [{ kind: "replaceFile", content: JSON.stringify(profile, null, 2) + "\n" }],
    });
  }
  return {
    written: input.write !== false,
    sourceEvaluations: profile.sourceEvaluations,
    sourceExplicitFeedback: profile.sourceExplicitFeedback,
    uniquePlayEvents: profile.uniquePlayEvents,
    uniqueExplicitEvents: profile.uniqueExplicitEvents,
    topArtists: profile.artists.slice(0, 10),
    bottomArtists: [...profile.artists].reverse().slice(0, 10),
    topTraits: profile.traits.slice(0, 15),
    bottomTraits: [...profile.traits].reverse().slice(0, 15),
    profile,
  };
}

