async function updateMusicTasteProfile(
  { workspace },
  input: { halfLifeDays?: number; write?: boolean } = {},
) {
  const halfLifeDays = Math.max(7, Math.min(730, input.halfLifeDays || 180));
  const readAll = async (path: string) => {
    const records: any[] = [];
    let offset = 1;
    while (true) {
      const page = await workspace
        .read(path, { format: "raw", offset, limit: 1 })
        .catch(() => null);
      if (!page) break;
      const line = page.content.trim();
      if (line) records.push(JSON.parse(line));
      if (!page.hasMore) break;
      offset += 1;
    }
    return records;
  };
  const [evaluations, explicitFeedback] = await Promise.all([
    readAll("data/listening-feedback.jsonl"),
    readAll("data/explicit-feedback.jsonl"),
  ]);
  type Aggregate = {
    name: string;
    weightedScore: number;
    evidenceWeight: number;
    events: number;
    inferredEvents: number;
    explicitEvents: number;
  };
  const artists = new Map<string, Aggregate>();
  const traits = new Map<string, Aggregate>();
  const seenPlays = new Set<string>();
  const seenExplicit = new Set<string>();
  const now = Date.now();
  const add = (
    map: Map<string, Aggregate>,
    name: string,
    score: number,
    weight: number,
    source: "inferred" | "explicit",
  ) => {
    if (!name) return;
    const current = map.get(name) || {
      name,
      weightedScore: 0,
      evidenceWeight: 0,
      events: 0,
      inferredEvents: 0,
      explicitEvents: 0,
    };
    current.weightedScore += score * weight;
    current.evidenceWeight += weight;
    current.events += 1;
    if (source === "explicit") current.explicitEvents += 1;
    else current.inferredEvents += 1;
    map.set(name, current);
  };
  const recencyWeight = (value: string, scale = 1) => {
    const timestamp = new Date(value.replace(" ", "T")).getTime();
    const ageDays = Number.isFinite(timestamp) ? Math.max(0, (now - timestamp) / 86400000) : 0;
    return Math.pow(0.5, ageDays / halfLifeDays) * scale;
  };
  for (const evaluation of evaluations)
    for (const track of evaluation.tracks || [])
      for (const play of track.plays || []) {
        const key = `${evaluation.manifestId}\u0000${track.title}\u0000${play.startedAt}`;
        if (seenPlays.has(key)) continue;
        seenPlays.add(key);
        const weight = recencyWeight(play.startedAt);
        add(artists, track.artist, play.score, weight, "inferred");
        for (const trait of track.traits || []) add(traits, trait, play.score, weight, "inferred");
      }
  for (const feedback of explicitFeedback) {
    if (seenExplicit.has(feedback.id)) continue;
    seenExplicit.add(feedback.id);
    const weight = recencyWeight(feedback.recordedAt, 2);
    if (feedback.artist) add(artists, feedback.artist, feedback.score, weight, "explicit");
    if (feedback.targetType === "trait")
      add(traits, feedback.target, feedback.score, weight, "explicit");
    else
      for (const trait of feedback.traits || [])
        add(
          traits,
          trait,
          feedback.targetType === "artist" ? feedback.score * 0.5 : feedback.score,
          weight,
          "explicit",
        );
  }
  const rank = (map: Map<string, Aggregate>) =>
    [...map.values()]
      .map((item) => {
        const averageScore = item.evidenceWeight ? item.weightedScore / item.evidenceWeight : 0;
        const confidence = 1 - Math.exp(-item.evidenceWeight / 3);
        return {
          name: item.name,
          preference: Math.round(averageScore * confidence * 1000) / 1000,
          averageScore: Math.round(averageScore * 1000) / 1000,
          confidence: Math.round(confidence * 1000) / 1000,
          evidence: item.events,
          inferredEvents: item.inferredEvents,
          explicitEvents: item.explicitEvents,
          evidenceWeight: Math.round(item.evidenceWeight * 1000) / 1000,
        };
      })
      .sort((a, b) => b.preference - a.preference || b.evidence - a.evidence);
  const profile = {
    version: 2,
    generatedAt: new Date().toISOString(),
    halfLifeDays,
    sourceEvaluations: evaluations.length,
    sourceExplicitFeedback: explicitFeedback.length,
    uniquePlayEvents: seenPlays.size,
    uniqueExplicitEvents: seenExplicit.size,
    artists: rank(artists),
    traits: rank(traits),
  };
  if (input.write !== false) {
    const path = "data/taste-profile.json";
    const current = await workspace
      .read(path, { format: "raw", offset: 1, limit: 1 })
      .catch(() => null);
    await workspace.edit(path, {
      revision: current?.revision || null,
      changes: [{ kind: "replaceFile", content: JSON.stringify(profile, null, 2) + "\n" }],
    });
  }
  return {
    written: input.write !== false,
    sourceEvaluations: profile.sourceEvaluations,
    sourceExplicitFeedback: profile.sourceExplicitFeedback,
    uniquePlayEvents: profile.uniquePlayEvents,
    uniqueExplicitEvents: profile.uniqueExplicitEvents,
    topArtists: profile.artists.slice(0, 10),
    bottomArtists: [...profile.artists].reverse().slice(0, 10),
    topTraits: profile.traits.slice(0, 15),
    bottomTraits: [...profile.traits].reverse().slice(0, 15),
    profile,
  };
}

