async function evaluateRecommendedPlaylistListening(
  { workspace, shell },
  input: { manifestId: string; startDate: string; endDate?: string; write?: boolean },
) {
  if (!input.manifestId) throw new Error("manifestId is required");
  const endDate = input.endDate || input.startDate;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(input.startDate) || !/^\d{4}-\d{2}-\d{2}$/.test(endDate))
    throw new Error("Dates must use YYYY-MM-DD format.");
  const dayCount =
    Math.floor(
      (new Date(`${endDate}T12:00:00`).getTime() -
        new Date(`${input.startDate}T12:00:00`).getTime()) /
        86400000,
    ) + 1;
  if (dayCount < 1 || dayCount > 31)
    throw new Error("Evaluation range must be between 1 and 31 days.");
  const manifest = await getMusicRecommendationManifest({ manifestId: input.manifestId });
  const nextDate = (
    await shell.execFile("/bin/date", ["-j", "-v+1d", "-f", "%Y-%m-%d", endDate, "+%F"], {
      maxBytes: 1000,
      maxLines: 5,
      raise: true,
    })
  ).stdout.trim();
  const normalize = (value: string) =>
    value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
  const wantedJson = JSON.stringify(
    Array.from(new Set(manifest.tracks.map((track: any) => normalize(track.title)))),
  );
  const python = `import sys,re,json,unicodedata\nfrom datetime import datetime\nwanted=set(json.loads(${JSON.stringify(wantedJson)}))\ndef norm(value):\n value=''.join(c for c in unicodedata.normalize('NFD',value) if unicodedata.category(c)!='Mn').lower()\n return ' '.join(re.sub(r'[^a-z0-9]+',' ',value).split())\nalbums={};plays=[];current=None\ndef finish(next_started=None):\n global current\n if current is not None and norm(current['title']) in wanted:\n  current['nextStartedAt']=next_started;plays.append(current)\nfor line in sys.stdin:\n a=re.search(r"Current song: contentIdentifier=([^ ,]+).*?album\\.identifiers=.*?storeAdamID=(\\d+)",line)\n if a: albums[a.group(1)]=a.group(2)\n m=re.search(r"^(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}\\.\\d+).*?time:([0-9.]+)s .*?item=<ITMPAVItem:.*?> \\(([^)]+)\\) (.*?) - reason:",line)\n if not m: continue\n timestamp,position,cid,title=m.groups();position=float(position)\n restarted=current is not None and cid==current['contentId'] and position<2 and current['_lastPosition']>30\n if current is None or cid!=current['contentId'] or restarted:\n  finish(timestamp);current={'startedAt':timestamp,'lastEventAt':timestamp,'contentId':cid,'title':title.strip(),'observedSeconds':0.0,'_lastPosition':position}\n else:\n  wall=(datetime.fromisoformat(timestamp)-datetime.fromisoformat(current['lastEventAt'])).total_seconds();advanced=position-current['_lastPosition']\n  if 0<=wall<=15 and 0<=advanced<=15: current['observedSeconds']+=min(wall,advanced)\n  current['lastEventAt']=timestamp;current['_lastPosition']=position\nfinish(None)\nfor play in plays:\n play['albumId']=albums.get(play['contentId']);play['observedSeconds']=round(play['observedSeconds'],1);play.pop('_lastPosition',None)\nprint(json.dumps(plays,ensure_ascii=False,separators=(',',':')))`;
  const predicate = `process == "Music" AND subsystem == "com.apple.amp.mediaplaybackcore" AND (eventMessage CONTAINS "playbackTimeDidChangeTo - Regular item" OR eventMessage CONTAINS "Current song: contentIdentifier=")`;
  const quote = (value: string) => `'${value.replace(/'/g, `'"'"'`)}'`;
  const command = `set -o pipefail; /usr/bin/log show --start ${quote(`${input.startDate} 00:00:00`)} --end ${quote(`${nextDate} 00:00:00`)} --style compact --predicate ${quote(predicate)} | /usr/bin/python3 -c ${quote(python)}`;
  const logResult = await shell.exec(command, {
    timeoutMs: 180000,
    maxBytes: 51200,
    maxLines: 20,
    raise: true,
  });
  if (logResult.truncated)
    throw new Error(
      "Matched playback history exceeded the safe output limit; use a shorter range.",
    );
  const plays = JSON.parse(logResult.stdout || "[]") as Array<{
    startedAt: string;
    lastEventAt: string;
    nextStartedAt: string | null;
    title: string;
    albumId: string | null;
    observedSeconds: number;
  }>;
  const feedbackTracks = manifest.tracks.map((track: any) => {
    const matches = plays.filter(
      (play) =>
        normalize(play.title) === normalize(track.title) &&
        (!track.albumId || !play.albumId || String(track.albumId) === String(play.albumId)),
    );
    const details = matches.map((play) => {
      const ratio = Math.min(1, play.observedSeconds / track.durationSeconds);
      const transitionSeconds = play.nextStartedAt
        ? (new Date(play.nextStartedAt.replace(" ", "T")).getTime() -
            new Date(play.startedAt.replace(" ", "T")).getTime()) /
          1000
