      return {
        startedAt: play.startedAt,
        observedSeconds: play.observedSeconds,
        completionRatio: Math.round(ratio * 1000) / 1000,
        earlySkip,
        completed,
        score,
      };
    });
    return {
      title: track.title,
      artist: track.artist,
      album: track.album,
      albumId: track.albumId,
      durationSeconds: track.durationSeconds,
      traits: track.traits || [],
      seeds: track.seeds || [],
      starts: details.length,
      replays: Math.max(0, details.length - 1),
      completedPlays: details.filter((p) => p.completed).length,
      earlySkips: details.filter((p) => p.earlySkip).length,
      totalObservedSeconds: Math.round(details.reduce((s, p) => s + p.observedSeconds, 0)),
      bestCompletionRatio: details.length ? Math.max(...details.map((p) => p.completionRatio)) : 0,
      score: details.reduce((s, p) => s + p.score, 0) + Math.max(0, details.length - 1) * 3,
      plays: details,
    };
  });
  const evaluationId = `${input.manifestId}:${input.startDate}:${endDate}`;
  const record = {
    version: 1,
    id: evaluationId,
    manifestId: input.manifestId,
    playlist: manifest.playlist,
    evaluatedAt: new Date().toISOString(),
    startDate: input.startDate,
    endDate,
    tracks: feedbackTracks,
  };
  if (input.write !== false) {
    const path = "data/listening-feedback.jsonl";
    const records: any[] = [];
    let revision: string | null = null;
    let offset = 1;
    while (true) {
      const page = await workspace
        .read(path, { format: "raw", offset, limit: 1 })
        .catch(() => null);
      if (!page) break;
      if (!revision) revision = page.revision;
      const line = page.content.trim();
      if (line) records.push(JSON.parse(line));
      if (!page.hasMore) break;
      offset += 1;
    }
    const index = records.findIndex((item) => item.id === evaluationId);
    if (index >= 0) records[index] = record;
    else records.push(record);
    await workspace.edit(path, {
      revision,
      changes: [
        {
          kind: "replaceFile",
          content: records.map((item) => JSON.stringify(item)).join("\n") + "\n",
        },
      ],
    });
  }
  return {
    id: evaluationId,
    playlist: manifest.playlist,
    heard: feedbackTracks.filter((t: any) => t.starts > 0).length,
    unheard: feedbackTracks.filter((t: any) => t.starts === 0).length,
    completedPlays: feedbackTracks.reduce((s: number, t: any) => s + t.completedPlays, 0),
    earlySkips: feedbackTracks.reduce((s: number, t: any) => s + t.earlySkips, 0),
    replays: feedbackTracks.reduce((s: number, t: any) => s + t.replays, 0),
    totalScore: feedbackTracks.reduce((s: number, t: any) => s + t.score, 0),
    tracks: feedbackTracks,
    written: input.write !== false,
  };
}

