async () => {
 const p=await summarizeAppleMusicPlaylist({name:"Peel Sessions 5"});
 const profiles:Record<string,{albumId:string;albumUrl:string;seeds:string[];traits:string[];reason:string}>={
 "The Comet Is Coming":{albumId:"1449207816",albumUrl:"https://music.apple.com/br/album/trust-in-the-lifeforce-of-the-deep-mystery/1449207816",seeds:["Jaga Jazzist","James Holden & The Animal Spirits"],traits:["electronic jazz","synthesizer","saxophone","groove","high energy"],reason:"A forceful opening where synth bass and saxophone turn the Jaga/James Holden bridge into something immediate and physical."},
 "Nomade Orquestra":{albumId:"1225966757",albumUrl:"https://music.apple.com/br/album/entremundos/1225966757",seeds:["Bixiga 70","Metá Metá"],traits:["Brazilian instrumental","Afrobeat","jazz-funk","cinematic","horns"],reason:"Brazilian ensemble music connecting Bixiga's rhythmic familiarity to Metá Metá's texture, with less abrasion and more cinematic groove."},
 "Portico Quartet":{albumId:"1578464848",albumUrl:"https://music.apple.com/br/album/art-in-the-age-of-automation/1578464848",seeds:["Nala Sinephro","Jaga Jazzist"],traits:["ambient jazz","electronic jazz","post-rock","studio composition","instrumental"],reason:"A spacious bridge between Nala's warmth and Jaga's electronic ensemble architecture, used for decompression without losing motion."},
 "Orquesta Akokán":{albumId:"1485038793",albumUrl:"https://music.apple.com/br/album/orquesta-akok%C3%A1n/1485038793",seeds:["Chucho Valdés","Afro-Cuban jazz"],traits:["Cuban mambo","Afro-Cuban rhythm","brass","dance","vocals"],reason:"The Cuban rhythmic release: compact, melodic and built for movement after the cooler Portico sequence."},
 "Maserati":{albumId:"319417530",albumUrl:"https://music.apple.com/br/album/inventions-for-the-new-season/319417530",seeds:["Grails","Do Make Say Think","Goat"],traits:["post-rock","motorik","dance-rock","long-form","instrumental"],reason:"Post-rock architecture driven by a motorik pulse, linking Grails-scale composition to Goat's physical bass-and-drum momentum."},
 "Meridian Brothers":{albumId:"1514732821",albumUrl:"https://music.apple.com/br/album/cumbia-siglo-xxi/1514732821",seeds:["Francis Bebey","Orquesta Akokán"],traits:["experimental cumbia","electronic","quirky melody","dance","vocals"],reason:"Quirky, whistleable electronic cumbia—strange in the Francis Bebey sense, but anchored by concise songs and an unmistakable dance rhythm."},
 "Hurtmold":{albumId:"182353663",albumUrl:"https://music.apple.com/br/album/mestro/182353663",seeds:["Tortoise","Bixiga 70"],traits:["Brazilian post-rock","jazz","rhythmic ensemble","instrumental","studio composition"],reason:"A Brazilian answer to Tortoise: interlocking percussion, guitars and horns behaving like a composed ensemble rather than a jam."},
 "Makaya McCraven":{albumId:"1627338395",albumUrl:"https://music.apple.com/br/album/in-these-times/1627338395",seeds:["Jaga Jazzist","Tortoise"],traits:["composed jazz","polyrhythm","studio composition","strings","instrumental"],reason:"Live improvisation edited into concise compositions, emphasizing shared pulse and architecture over open-ended soloing."},
 "Red Snapper":{albumId:"278540269",albumUrl:"https://music.apple.com/br/album/making-bones/278540269",seeds:["Goat","A Certain Ratio"],traits:["bass","jazz-funk","dub","breakbeat","live electronica"],reason:"Bass-first live electronica with jazz-funk and dub weight—the direct test of whether Lucinda and Goat point toward a broader low-end preference."},
 "WITCH":{albumId:"1861544051",albumUrl:"https://music.apple.com/br/album/introduction/1861544051",seeds:["Goat","Ebo Taylor"],traits:["Zamrock","funk","psychedelic rock","bass","vocals"],reason:"Zambian psych-rock with warm basslines and compact funk songs, extending Goat's success without repeating its exact aesthetic."},
 "Kelly Lee Owens":{albumId:"1497732972",albumUrl:"https://music.apple.com/br/album/inner-song/1497732972",seeds:["Nala Sinephro","M83","New Order"],traits:["melodic electronic","analog synthesizer","ambient","techno","vocals"],reason:"The synthward direction treated as a color and transition: melodic, nocturnal electronics that never need to become an M83 or New Order destination."},
