 const profiles:Record<string,{albumId:string;albumUrl:string;seeds:string[];traits:string[];reason:string}>={
 "Zombi":{albumId:"146779486",albumUrl:"https://music.apple.com/br/album/surface-to-air/146779486",seeds:["Maserati","Jaga Jazzist"],traits:["motorik","analog synthesizer","progressive rock","instrumental","long-form"],reason:"Maserati's motorik propulsion moved into a lean synth-and-drums duo: cinematic, composed and rhythmically direct."},
 "Ibibio Sound Machine":{albumId:"1839096564",albumUrl:"https://music.apple.com/br/album/doko-mien/1839096564",seeds:["Francis Bebey","Fela Kuti","Kelly Lee Owens"],traits:["African electronic music","funk","dance","synthesizer","vocals"],reason:"Francis Bebey's melodic African electronics scaled into a bright live band with funk bass and daytime-friendly dance energy."},
 "Elephant9":{albumId:"352516151",albumUrl:"https://music.apple.com/br/album/walk-the-nile/352516151",seeds:["Jaga Jazzist","The Comet Is Coming"],traits:["progressive jazz","organ","rhythmic ensemble","groove","instrumental"],reason:"Norwegian organ-trio music connecting Jaga's architecture to the Comet's intensity while keeping one shared rhythmic center."},
 "Daymé Arocena":{albumId:"1561174445",albumUrl:"https://music.apple.com/br/album/cubafon%C3%ADa/1561174445",seeds:["Orquesta Akokán","Chucho Valdés"],traits:["Afro-Cuban jazz","rumba","melodic","dance","vocals"],reason:"The vocal Cuban branch: rich melody and personality over rumba and jazz arrangements that stay concise and danceable."},
 "GoGo Penguin":{albumId:"1579118524",albumUrl:"https://music.apple.com/br/album/v2-0-deluxe-edition/1579118524",seeds:["Tortoise","Makaya McCraven"],traits:["piano trio","breakbeat","post-rock","studio composition","instrumental"],reason:"Piano-trio writing with electronic rhythmic logic: compact songs, strong pulse and none of the open-ended jam-session problem."},
 "Los Hacheros":{albumId:"565128655",albumUrl:"https://music.apple.com/br/album/pilon/565128655",seeds:["Orquesta Akokán","Afro-Cuban jazz"],traits:["son cubano","guajira","Afro-Cuban rhythm","dance","vocals"],reason:"A rawer New York Afro-Cuban ensemble after Akokán's polish, driven by hand percussion, tres and immediate social rhythm."},
 "Mammal Hands":{albumId:"1577505862",albumUrl:"https://music.apple.com/br/album/shadow-work/1577505862",seeds:["Nala Sinephro","Portico Quartet"],traits:["ambient jazz","saxophone","piano","pulse","instrumental"],reason:"A warmer decompression phase with saxophone and piano, but enough repeating pulse to avoid floating away."},
 "Yin Yin":{albumId:"1487604128",albumUrl:"https://music.apple.com/br/album/the-rabbit-that-hunts-tigers/1487604128",seeds:["Goat","Meridian Brothers"],traits:["psychedelic funk","bass","global groove","quirky melody","instrumental"],reason:"Goat's bass-led psychedelic success redirected into playful Southeast Asian-inspired instrumental funk."},
 "Trans Am":{albumId:"5507269",albumUrl:"https://music.apple.com/br/album/futureworld/5507269",seeds:["Maserati","Stereolab"],traits:["motorik","post-rock","analog synthesizer","electronic rock","vocals"],reason:"A late-90s bridge between motorik post-rock and retro electronics, pointing generally toward the New Order/Depeche coordinate without settling there."},
 "Stereolab":{albumId:"1230517312",albumUrl:"https://music.apple.com/br/album/dots-and-loops/1230517312",seeds:["Broadcast","M83","motorik"],traits:["analog synthesizer","motorik","art pop","groove","vocals"],reason:"Warm analog pop with motorik discipline and intricate studio arrangement, selected on the more rhythmic and melodic side."},
 "Newen Afrobeat":commonNewen,
 "Newen Afrobeat & Seun Kuti":commonNewen,
 "L'Eclair":{albumId:"1720227358",albumUrl:"https://music.apple.com/br/album/sauropoda/1720227358",seeds:["Goat","Red Snapper","jazz-funk"],traits:["psychedelic funk","bass","groove","studio composition","instrumental"],reason:"Swiss instrumental psych-funk where repetition is carried by bass movement and arrangement changes rather than static loops."}
 };
 return recordMusicRecommendationManifest({playlist:p.name,manifestId:"2026-08-14-peel-sessions-6",createdAt:new Date().toISOString(),targetMinutes:180,description:"Motorik synth-rock, African electronics, organ jazz, Cuban rhythm, piano-trio pulse, psychedelic funk and a full Fela-sized ride.",ifExists:"replace",tracks:p.tracks.map(t=>{const x=profiles[t.artist];if(!x)throw new Error(`Missing ${t.artist}`);return{title:t.title,artist:t.artist,album:t.album,albumId:x.albumId,durationSeconds:t.seconds,seeds:x.seeds,traits:x.traits,reason:x.reason,albumUrl:x.albumUrl};})});
}

