/**
 * Rebuild the visual recommendation journal from its latest stored editorial entry without re-entering the content.
 *
 * @pit project
 */
async function rebuildMusicRecommendationJournal(
  { workspace },
  input: { manifestId?: string; country?: string; dryRun?: boolean } = {},
) {
  const journal = await workspace.read("data/journal.jsonl", { format: "raw" });
  const entries = journal.content
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  if (!entries.length) throw new Error("No journal entries are available to rebuild.");
  entries.sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)));
  const entry = input.manifestId
    ? entries.find((item) => item.manifestId === input.manifestId)
    : entries[0];
  if (!entry) throw new Error(`Journal entry not found: ${input.manifestId}`);
  const publishInput = {
    manifestId: entry.manifestId,
    headline: entry.headline,
    intro: entry.intro,
    narrative: entry.narrative || undefined,
    publishedAt: entry.publishedAt,
    tags: entry.tags || [],
    artistNotes: entry.artistNotes || [],
    ifExists: "replace" as const,
    country: input.country || "BR",
  };
  if (input.dryRun)
    return {
      dryRun: true,
      entryCount: entries.length,
      rebuildFrom: entry.manifestId,
      publishInput,
    };
  const result = await publishMusicRecommendationJournalEntry(publishInput);
  return { dryRun: false, entryCount: entries.length, rebuildFrom: entry.manifestId, ...result };
}

/**
 * Validate the generated listening journal, copy it to the sibling public-site repository, commit only music/index.html, and optionally push master.
 *
 * @pit project
 */
async function publishMusicJournalSite(
  { shell, git },
  input: { commitMessage?: string; push?: boolean; dryRun?: boolean } = {},
) {
  const repositoryPath = "../cv.github.io";
  const sourcePath = "site/index.html";
  const destinationPath = "music/index.html";
  const expectedRemote = "git@github.com:cv/cv.github.io.git";
  const validationScript = `import json\nfrom html.parser import HTMLParser\nfrom pathlib import Path\ns=Path('site/index.html').read_text(encoding='utf-8')\nHTMLParser().feed(s)\nentries=s.count('class=\"entry\"')\ncards=s.count('class=\"artist-card\"')\ntracks=s.count('<li><a href=')\nlinks=s.count('wikipedia.org/wiki/Special:Search')\nif not s.rstrip().endswith('</html>'): raise SystemExit('journal HTML is incomplete')\nif entries<1 or cards<1 or tracks<1: raise SystemExit('journal HTML has no rendered content')\nrows=[json.loads(line) for line in Path('data/journal.jsonl').read_text(encoding='utf-8').splitlines() if line]\nlatest=max(rows,key=lambda row:str(row.get('publishedAt','')))\nprint(json.dumps({'bytes':len(s.encode()),'entries':entries,'artistCards':cards,'trackLinks':tracks,'wikipediaLinks':links,'latestHeadline':latest.get('headline','Listening Notes')}))`;
  const [validationResult, statusBefore, branch, remote, comparison] = await Promise.all([
    shell.execFile("/usr/bin/python3", ["-c", validationScript], {
      timeoutMs: 30000,
      maxBytes: 3000,
      maxLines: 20,
      raise: true,
    }),
    git.status(["--short"], { cwd: repositoryPath }),
    shell.execFile("git", ["branch", "--show-current"], {
      cwd: repositoryPath,
      maxBytes: 1000,
      maxLines: 10,
      raise: true,
    }),
    shell.execFile("git", ["remote", "get-url", "origin"], {
      cwd: repositoryPath,
      maxBytes: 2000,
      maxLines: 10,
      raise: true,
    }),
    shell.execFile("cmp", ["-s", sourcePath, `${repositoryPath}/${destinationPath}`], {
      maxBytes: 1000,
      maxLines: 10,
    }),
  ]);
  const validation = JSON.parse(validationResult.stdout) as {
    bytes: number;
    entries: number;
    artistCards: number;
    trackLinks: number;
    wikipediaLinks: number;
    latestHeadline: string;
  };
  if (statusBefore.stdout.trim())
    throw new Error(
      `Publication repository must be clean before publishing:\n${statusBefore.stdout}`,
    );
  if (branch.stdout.trim() !== "master")
    throw new Error(`Expected publication branch master; found ${branch.stdout.trim()}`);
  if (remote.stdout.trim() !== expectedRemote)
    throw new Error(`Unexpected publication remote: ${remote.stdout.trim()}`);
  const changed = comparison.code !== 0;
  const commitMessage =
    input.commitMessage?.trim() || `music: publish ${validation.latestHeadline}`;
  if (input.dryRun)
    return {
      dryRun: true,
      changed,
      push: input.push !== false,
      repositoryPath,
      destinationPath,
      commitMessage,
      validation,
    };
  if (!changed)
    return {
      dryRun: false,
      changed: false,
      pushed: false,
      repositoryPath,
      destinationPath,
      validation,
    };
  await shell.execFile("cp", [sourcePath, `${repositoryPath}/${destinationPath}`], {
    timeoutMs: 30000,
    maxBytes: 1000,
    maxLines: 10,
    raise: true,
  });
  const copiedStatus = await git.status(["--short"], { cwd: repositoryPath });
  const changedPaths = copiedStatus.stdout
    .split("\n")
    .filter(Boolean)
    .map((line) => line.slice(3));
  if (changedPaths.length !== 1 || changedPaths[0] !== destinationPath)
    throw new Error(`Copy changed unexpected publication files:\n${copiedStatus.stdout}`);
  await git.add([destinationPath], { cwd: repositoryPath });
  const commit = await git.commit(["-m", commitMessage], { cwd: repositoryPath });
  let pushResult: null | { stdout: string; stderr: string; code: number; truncated: boolean } =
    null;
  if (input.push !== false)
    pushResult = await git.push(["origin", "master"], { cwd: repositoryPath });
  const [statusAfter, log] = await Promise.all([
    git.status(["--short", "--branch"], { cwd: repositoryPath }),
    git.log(["-1", "--oneline"], { cwd: repositoryPath }),
  ]);
  return {
    dryRun: false,
    changed: true,
    pushed: input.push !== false,
    repositoryPath,
    destinationPath,
    commitMessage,
    validation,
    commit,
    push: pushResult,
    status: statusAfter,
    log,
  };
}

/**
 * Record explicit track, artist, or trait feedback, including foundational artists outside recommendation manifests.
 *
 * @pit project
 */
async function recordExplicitMusicFeedback(
  { workspace },
  input: {
    manifestId?: string;
    track?: string;
    artist?: string;
    trait?: string;
    traits?: string[];
    sentiment: "love" | "like" | "neutral" | "dislike" | "never";
    note?: string;
    recordedAt?: string;
    feedbackId?: string;
    ifExists?: "replace" | "error";
    dryRun?: boolean;
  },
) {
  const targets = [input.track, input.artist, input.trait].filter((value) => value?.trim());
  if (targets.length !== 1) throw new Error("Provide exactly one of track, artist, or trait.");
  if (input.track && !input.manifestId)
    throw new Error("Track feedback requires manifestId for exact matching.");
  const scoreBySentiment = { love: 4, like: 2, neutral: 0, dislike: -3, never: -6 } as const;
  const normalize = (value: string) =>
    value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
  const manifest = input.manifestId
    ? await getMusicRecommendationManifest({ manifestId: input.manifestId })
    : null;
  let targetType: "track" | "artist" | "trait";
  let target: string;
  let artist: string | null = null;
  let title: string | null = null;
  let traits: Array<string> = Array.from(new Set(input.traits || []));
  if (input.track) {
    targetType = "track";
    target = input.track;
    const matched = manifest.tracks.find(
      (item: any) => normalize(item.title) === normalize(input.track!),
    );
    if (!matched) throw new Error(`Track not found in manifest: ${input.track}`);
    title = matched.title;
    artist = matched.artist;
    traits = matched.traits || [];
    target = matched.title;
  } else if (input.artist) {
    targetType = "artist";
    target = input.artist;
    artist = input.artist;
    if (manifest) {
      const matched = manifest.tracks.filter(
        (item: any) => normalize(item.artist) === normalize(input.artist!),
      );
      if (!matched.length) throw new Error(`Artist not found in manifest: ${input.artist}`);
      artist = matched[0].artist;
      target = artist!;
      traits = Array.from(new Set(matched.flatMap((item: any) => item.traits || []))) as string[];
    }
  } else {
    targetType = "trait";
    target = input.trait!;
    if (manifest) {
      const available = new Map<string, string>();
      for (const item of manifest.tracks)
        for (const value of item.traits || []) available.set(normalize(value), value);
      const canonical = available.get(normalize(input.trait!));
      if (!canonical) throw new Error(`Trait not found in manifest: ${input.trait}`);
      target = canonical;
    }
    traits = [target];
  }
  const recordedAt = input.recordedAt || new Date().toISOString();
  const scope = input.manifestId || "global";
  const id =
    input.feedbackId ||
    `${scope}:${targetType}:${normalize(target).replace(/ /g, "-")}:${recordedAt}`;
  const record = {
    version: 2,
    id,
    manifestId: input.manifestId || null,
    playlist: manifest?.playlist || null,
    recordedAt,
    targetType,
    target,
    title,
    artist,
    traits,
    sentiment: input.sentiment,
    score: scoreBySentiment[input.sentiment],
    note: input.note || null,
  };
  if (input.dryRun) return { dryRun: true, record };
  const path = "data/explicit-feedback.jsonl";
  const records: any[] = [];
  let revision: string | null = null;
  let offset = 1;
  while (true) {
    const page = await workspace.read(path, { format: "raw", offset, limit: 1 }).catch(() => null);
    if (!page) break;
    if (!revision) revision = page.revision;
    const line = page.content.trim();
    if (line) records.push(JSON.parse(line));
    if (!page.hasMore) break;
    offset += 1;
  }
  const index = records.findIndex((item) => item.id === id);
  if (index >= 0 && (input.ifExists || "error") === "error")
    throw new Error(`Feedback already exists: ${id}`);
  if (index >= 0) records[index] = record;
  else records.push(record);
  await workspace.edit(path, {
    revision,
    changes: [
      {
        kind: "replaceFile",
        content: records.map((item) => JSON.stringify(item)).join("\n") + "\n",
      },
    ],
  });
  return {
    dryRun: false,
    path,
    id,
    targetType,
    target,
    sentiment: input.sentiment,
    score: record.score,
    replaced: index >= 0,
  };
}

