  for(const lookup of lookups){if(lookup.status!=="fulfilled"||!lookup.value.ok)continue;const body=JSON.parse(lookup.value.body) as {results?:Array<{collectionId?:number;artworkUrl100?:string}>};for(const item of body.results||[])if(item.collectionId&&item.artworkUrl100)artwork.set(String(item.collectionId),item.artworkUrl100.replace("100x100bb","600x600bb"));}
  const esc=(value:unknown)=>String(value??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
  const duration=(seconds:number)=>`${Math.floor(seconds/60)}:${String(Math.round(seconds%60)).padStart(2,"0")}`;
  const longDuration=(seconds:number)=>`${Math.floor(seconds/3600)}h ${String(Math.floor((seconds%3600)/60)).padStart(2,"0")}m`;
