ase;font-size:.65rem;letter-spacing:.12em}.track-list{list-style:none;padding:0;margin:18px 0 0;border-top:1px solid #ffffff14}.track-list li{border-bottom:1px solid #ffffff14}.track-list a{display:flex;justify-content:space-between;gap:14px;padding:9px 0;color:var(--ink);text-decoration:none;font-size:.86rem}.track-list a:hover span{color:var(--acid)}.track-list time{color:var(--muted);font-variant-numeric:tabular-nums}footer{padding:60px 0;color:var(--muted);display:flex;justify-content:space-between}@media(max-width:900px){.entry-head{grid-template-columns:1fr}.narrative{grid-column:1;grid-row:auto;margin-top:32px}.artist-grid{grid-template-columns:1fr}}@media(max-width:580px){.shell{width:min(100% - 24px,1240px)}.hero{padding:24px 0 22px}.artist-card{grid-template-columns:1fr}.cover-wrap{height:280px}.entry{padding:72px 0}h1{font-size:4.3rem}footer{display:block}}`;
  const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Listening Notes · Music Recommendations</title><style>${css}</style></head><body><main class="shell"><header class="hero"><p class="eyebrow">A private recommendation journal</p><h1>Listening Notes</h1><p class="hero-copy">A growing field guide to the records, scenes, collaborators and musical detours worth hearing next.</p><div class="stats"><div><strong>${entries.length}</strong> entries</div><div><strong>${totalTracks}</strong> tracks</div><div><strong>${uniqueArtists}</strong> artists</div><div><strong>${longDuration(totalSeconds)}</strong> queued</div></div></header>${renderedEntries}<footer><span>Generated from versioned recommendation manifests.</span><span>Last updated ${prettyDate(new Date().toISOString())}</span></footer></main></body></html>`;
  const site=await workspace.read("site/index.html",{format:"raw",offset:1,limit:1}).catch(()=>null);
  await workspace.edit("site/index.html",{revision:site?.revision||null,changes:[{kind:"replaceFile",content:html}]});
  return{sitePath:"site/index.html",entries:entries.length,artistCards:manifests.reduce((sum,m)=>sum+new Set(m.tracks.map((t:any)=>t.artist)).size,0),trackLinks:totalTracks,wikipediaLinks:uniqueArtists,bytes:new TextEncoder().encode(html).length,complete:html.endsWith("</html>")};
}

