async function publishMusicRecommendationJournalEntry(
  { workspace },
  input: {
    manifestId: string;
    headline: string;
    intro: string;
    narrative?: string;
    publishedAt?: string;
    tags?: string[];
    artistNotes?: Array<{
      artist: string;
      why: string;
      connections?: string;
      selectionNote?: string;
    }>;
    ifExists?: "replace" | "error";
    country?: string;
  },
) {
  if (!input.manifestId || !input.headline?.trim() || !input.intro?.trim())
    throw new Error("manifestId, headline, and intro are required.");
  const manifest = await getMusicRecommendationManifest({ manifestId: input.manifestId });
  const artists = new Set(manifest.tracks.map((track: any) => track.artist));
  for (const note of input.artistNotes || [])
    if (!artists.has(note.artist))
      throw new Error(`Artist note does not match manifest: ${note.artist}`);
  const path = "data/journal.jsonl";
  const entries: any[] = [];
  let revision: string | null = null;
  let offset = 1;
  while (true) {
    const page = await workspace.read(path, { format: "raw", offset, limit: 1 }).catch(() => null);
    if (!page) break;
    if (!revision) revision = page.revision;
    const line = page.content.trim();
    if (line) entries.push(JSON.parse(line));
    if (!page.hasMore) break;
    offset += 1;
  }
  const index = entries.findIndex((entry) => entry.manifestId === input.manifestId);
  if (index >= 0 && (input.ifExists || "error") === "error")
    throw new Error(`Journal entry already exists for ${input.manifestId}`);
  const entry = {
    version: 1,
    manifestId: input.manifestId,
    headline: input.headline,
    intro: input.intro,
    narrative: input.narrative || null,
    publishedAt:
      input.publishedAt || (index >= 0 ? entries[index].publishedAt : new Date().toISOString()),
    tags: Array.from(new Set(input.tags || [])),
    artistNotes: input.artistNotes || [],
    updatedAt: new Date().toISOString(),
  };
  if (index >= 0) entries[index] = entry;
  else entries.push(entry);
  entries.sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)));
  await workspace.edit(path, {
    revision,
    changes: [
      {
        kind: "replaceFile",
        content: entries.map((item) => JSON.stringify(item)).join("\n") + "\n",
      },
    ],
  });
  const rendered = await renderMusicRecommendationJournal({ country: input.country || "BR" });
  return {
    journalPath: path,
    manifestId: input.manifestId,
    replaced: index >= 0,
    artists: artists.size,
    tracks: manifest.tracks.length,
    ...rendered,
  };
}

