async function rebuildMusicRecommendationJournal(
  { workspace },
  input: { manifestId?: string; country?: string; dryRun?: boolean } = {},
) {
  const entries: any[] = [];
  let offset = 1;
  while (true) {
    const page = await workspace.read("data/journal.jsonl", { format: "raw", offset, limit: 1 });
    const line = page.content.trim();
    if (line) entries.push(JSON.parse(line));
    if (!page.hasMore) break;
    offset += 1;
  }
  if (!entries.length) throw new Error("No journal entries are available to rebuild.");
  entries.sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)));
  const selected = input.manifestId
    ? entries.find((entry) => entry.manifestId === input.manifestId)
    : entries[0];
  if (!selected) throw new Error(`Journal entry not found: ${input.manifestId}`);
  if (input.dryRun)
    return {
      dryRun: true,
      entryCount: entries.length,
      rebuildFrom: selected.manifestId,
      country: input.country || "BR",
    };
  const rendered = await renderMusicRecommendationJournal({ country: input.country || "BR" });
  return {
    dryRun: false,
    entryCount: entries.length,
    rebuildFrom: selected.manifestId,
    ...rendered,
  };
}

