 const combos:any[]=[];
 const rec=(start:number,chosen:any[])=>{if(chosen.length>=3&&chosen.length<=5){const seconds=chosen.reduce((s:any,t:any)=>s+t[1],0);combos.push({seconds,delta:seconds-810,titles:chosen.map((t:any)=>t[0])});}if(chosen.length===5)return;for(let i=start;i<tracks.length;i++)rec(i+1,[...chosen,tracks[i]]);};rec(0,[]);return combos.sort((a,b)=>Math.abs(a.delta)-Math.abs(b.delta)).slice(0,10);
}

