    "source": "/**
 * Choose a balanced, priority-aware set of representative tracks near a target playlist duration.
 *
 * @pit project
 */
async function planBalancedAppleMusicPlaylist(
  {},
  input: {
    targetMinutes: number;
    artists: Array<{
      artist: string;
      albumUrl: string;
      tracks: Array<{
        title: string;
        seconds: number;
        priority?: number;
        required?: boolean;
        reason?: string;
      }>;
    }>;
    minTracksPerArtist?: number;
    maxTracksPerArtist?: number;
  },
) {
  if (!input.artists?.length) throw new Error("Provide at least one artist with candidate tracks.");
  if (!(input.targetMinutes > 0)) throw new Error("targetMinutes must be positive.");
  const minimum = Math.max(1, input.minTracksPerArtist || 2);
  const maximum = Math.max(minimum, Math.min(8, input.maxTracksPerArtist || 4));
  const targetSeconds = Math.round(input.targetMinutes * 60);
  const artistTarget = targetSeconds / input.artists.length;

  type Candidate = {
    title: string;
    seconds: number;
    priority: number;
    required: boolean;
    reason?: string;
  };
  type Option = { seconds: number; utility: number; fairnessPenalty: number; tracks: Candidate[] };
  const optionsByArtist: Array<{ artist: string; albumUrl: string; options: Option[] }> = [];

  for (const group of input.artists) {
    const candidates: Candidate[] = group.tracks
      .filter((track) => track.title && track.seconds > 0)
      .map((track) => ({
        ...track,
        priority: Math.max(0, Math.min(10, track.priority ?? 5)),
        required: Boolean(track.required),
      }))
      .sort((a, b) => Number(b.required) - Number(a.required) || b.priority - a.priority)
      .slice(0, 18);
    if (!candidates.length) throw new Error(`No valid tracks for ${group.artist}.`);
    const requiredCount = candidates.filter((track) => track.required).length;
    if (requiredCount > maximum)
      throw new Error(`${group.artist} has more required tracks than maxTracksPerArtist.`);
    const minSize = Math.min(candidates.length, Math.max(minimum, requiredCount));
    const maxSize = Math.min(candidates.length, maximum);
    const options: Option[] = [];

    const build = (start: number, chosen: Candidate[]) => {
      if (chosen.length >= minSize && chosen.length <= maxSize) {
        const requiredMissing = candidates.some(
          (track) => track.required && !chosen.includes(track),
        );
        if (!requiredMissing) {
          const seconds = chosen.reduce((sum, track) => sum + track.seconds, 0);
          const utility = chosen.reduce((sum, track) => sum + track.priority, 0);
          options.push({
            seconds,
            utility,
            fairnessPenalty: Math.abs(seconds - artistTarget),
            tracks: [...chosen],
          });
        }
      }
      if (chosen.length === maxSize) return;
      for (let index = start; index < candidates.length; index++) {
        chosen.push(candidates[index]);
        build(index + 1, chosen);
        chosen.pop();
      }
    };
    build(0, []);
    if (!options.length) throw new Error(`Could not build a valid selection for ${group.artist}.`);
    options.sort((a, b) => a.fairnessPenalty - a.utility * 8 - (b.fairnessPenalty - b.utility * 8));
    optionsByArtist.push({
      artist: group.artist,
      albumUrl: group.albumUrl,
      options: options.slice(0, 30),
    });
  }

  type State = { seconds: number; utility: number; fairnessPenalty: number; choices: Option[] };
  let states: State[] = [{ seconds: 0, utility: 0, fairnessPenalty: 0, choices: [] }];
  for (const group of optionsByArtist) {
    const buckets = new Map<number, State>();
    for (const state of states) {
      for (const option of group.options) {
        const next: State = {
          seconds: state.seconds + option.seconds,
          utility: state.utility + option.utility,
          fairnessPenalty: state.fairnessPenalty + option.fairnessPenalty,
          choices: [...state.choices, option],
        };
        const bucket = Math.round(next.seconds / 10);
        const previous = buckets.get(bucket);
        const quality = next.utility * 12 - next.fairnessPenalty * 0.15;
        const previousQuality = previous
          ? previous.utility * 12 - previous.fairnessPenalty * 0.15
          : -Infinity;
        if (!previous || quality > previousQuality) buckets.set(bucket, next);
      }
    }
    states = [...buckets.values()]
      .sort(
        (a, b) =>
          Math.abs(a.seconds - targetSeconds) +
          a.fairnessPenalty * 0.08 -
          a.utility * 5 -
          (Math.abs(b.seconds - targetSeconds) + b.fairnessPenalty * 0.08 - b.utility * 5),
      )
      .slice(0, 4000);
  }

  states.sort(
    (a, b) =>
      Math.abs(a.seconds - targetSeconds) +
      a.fairnessPenalty * 0.08 -
      a.utility * 5 -
      (Math.abs(b.seconds - targetSeconds) + b.fairnessPenalty * 0.08 - b.utility * 5),
  );
  const best = states[0];
  const selections = optionsByArtist.map((group, index) => ({
    artist: group.artist,
    albumUrl: group.albumUrl,
    seconds: best.choices[index].seconds,
    tracks: best.choices[index].tracks.map((track) => ({
      title: track.title,
      seconds: track.seconds,
      priority: track.priority,
      reason: track.reason || null,
    })),
  }));
  return {
    targetSeconds,
    targetDuration: `${Math.floor(targetSeconds / 3600)}:${String(Math.floor((targetSeconds % 3600) / 60)).padStart(2, "0")}:${String(targetSeconds % 60).padStart(2, "0")}`,
    totalSeconds: best.seconds,
    duration: `${Math.floor(best.seconds / 3600)}:${String(Math.floor((best.seconds % 3600) / 60)).padStart(2, "0")}:${String(best.seconds % 60).padStart(2, "0")}`,
    deltaSeconds: best.seconds - targetSeconds,
    trackCount: selections.reduce((sum, group) => sum + group.tracks.length, 0),
    selections,
    populateInput: selections.map((group) => ({
      url: group.albumUrl,
      tracks: group.tracks.map((track) => track.title),
    })),
  };
}"
