async ({ http }) => {
 const queries=["Wilson Simonal País Tropical","Toquinho Carolina Carol Bela","Astrud Gilberto Take It Easy My Brother Charles"];
 const rs=await Promise.all(queries.map(q=>http.request(`https://itunes.apple.com/search?term=${encodeURIComponent(q)}&entity=song&limit=20&country=BR`,{maxBytes:30000})));
 return queries.map((q,i)=>({query:q,results:(JSON.parse(rs[i].body) as {results:any[]}).results.map(x=>({track:x.trackName,artist:x.artistName,album:x.collectionName,collectionId:x.collectionId,seconds:Math.round(x.trackTimeMillis/1000),url:x.trackViewUrl})).slice(0,10)}));
}

