 return queries.map((q,i)=>({query:q,results:(JSON.parse(rs[i].body) as {results:any[]}).results.map(x=>({track:x.trackName,artist:x.artistName,album:x.collectionName,collectionId:x.collectionId,seconds:Math.round(x.trackTimeMillis/1000),url:x.trackViewUrl}))}));
}

async () => {
 const r=await findAppleMusicCatalogAlbums({country:"BR",maxAlbumMatches:8,albums:[{artist:"Jorge Ben",album:"Jorge Ben"},{artist:"Jorge Ben",album:"Samba Esquema Novo"},{artist:"Jorge Ben",album:"Solta o Pavão"}]});return r.albums.map(x=>({query:x.query,album:x.album,tracks:x.tracks.map(t=>({title:t.title,seconds:t.seconds}))}));
}

