    "signature": "planBalancedAppleMusicPlaylist(input: { targetMinutes: number; artists: Array<{ artist: string; albumUrl: string; tracks: Array<{ title: string; seconds: number; priority?: number; required?: boolean; reason?: string; }>; }>; minTracksPerArtist?: number; maxTracksPerArtist?: number; })",
