/**
 * Create or reuse an Apple Music playlist, optionally add catalog albums to the library, copy exact selected tracks without duplicates, and verify the result.
 *
 * @pit project
 */
async function populateAppleMusicCatalogPlaylist(
  { shell, http },
  input: {
    name: string;
    description?: string;
    albums: Array<{ url: string; tracks: string[] }>;
    ifExists?: "reuse" | "error" | "createUnique";
    dryRun?: boolean;
    loadTimeoutSeconds?: number;
    country?: string;
    addAlbumsToLibrary?: boolean;
  },
) {
  if (!input.name?.trim()) throw new Error("playlist name is required");
  if (!input.albums?.length) throw new Error("Provide at least one album selection.");
  if ((input.description || "").length > 255)
    throw new Error("Apple Music playlist descriptions are limited to 255 characters.");
  const requestedName = input.name.trim();
  const mode = input.ifExists || "reuse";
  const country = (input.country || "BR").toUpperCase();
  const addAlbumsToLibrary = input.addAlbumsToLibrary !== false;
  const timeoutSeconds = Math.max(5, Math.min(60, input.loadTimeoutSeconds || 20));
  const normalize = (value: string) =>
    value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
  const albumIdFromUrl = (url: string) => {
    const match = url.match(/\/(\d+)(?:\?|$)/);
    if (!match) throw new Error(`Could not extract an Apple Music album ID from ${url}`);
    return match[1];
  };
  type CatalogTrack = {
    title: string;
    artist: string;
    album: string;
    seconds: number;
    url: string;
    albumId: string;
  };
  const lookups = await Promise.all(
    input.albums.map((album) =>
      http.request(
        `https://itunes.apple.com/lookup?id=${albumIdFromUrl(album.url)}&entity=song&country=${country}`,
        { maxBytes: 51200 },
      ),
    ),
  );
  const resolvedAlbums = input.albums.map((album, index) => {
    const albumId = albumIdFromUrl(album.url);
    const body = JSON.parse(lookups[index].body) as {
      results?: Array<{
        wrapperType: string;
        trackName?: string;
        artistName?: string;
        collectionName?: string;
        trackTimeMillis?: number;
        trackViewUrl?: string;
      }>;
    };
    const catalog = (body.results || []).filter((item) => item.wrapperType === "track");
    const tracks: CatalogTrack[] = album.tracks.map((title) => {
      const match = catalog.find((item) => normalize(item.trackName || "") === normalize(title));
      if (!match?.trackViewUrl)
        throw new Error(`Catalog track not found in album ${albumId}: ${title}`);
      return {
        title: match.trackName || title,
        artist: match.artistName || "",
        album: match.collectionName || "",
        seconds: Math.round((match.trackTimeMillis || 0) / 1000),
        url: match.trackViewUrl,
        albumId,
      };
    });
    return { sourceUrl: album.url, albumId, tracks };
  });
  const plan = resolvedAlbums.flatMap((album) => album.tracks);
  if (input.dryRun)
    return {
      dryRun: true,
      requestedName,
      country,
      addAlbumsToLibrary,
      plannedTracks: plan.length,
      albums: resolvedAlbums.map((album) => ({
        albumId: album.albumId,
        tracks: album.tracks.map((track) => ({
          title: track.title,
          artist: track.artist,
          album: track.album,
          seconds: track.seconds,
        })),
      })),
    };

  const asAppleString = (value: string) => `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
  const createScript = `tell application "Music"
set requestedName to ${asAppleString(requestedName)}
set actualName to requestedName
if exists user playlist actualName then
if ${asAppleString(mode)} is "error" then error "Playlist already exists: " & actualName number 409
if ${asAppleString(mode)} is "createUnique" then
set suffix to 2
repeat while exists user playlist actualName
set actualName to requestedName & " " & suffix
set suffix to suffix + 1
end repeat
set p to make new user playlist with properties {name:actualName, description:${asAppleString(input.description || "")}}
else
set p to user playlist actualName
if ${asAppleString(input.description || "")} is not "" then set description of p to ${asAppleString(input.description || "")}
end if
else
set p to make new user playlist with properties {name:actualName, description:${asAppleString(input.description || "")}}
end if
return actualName
end tell`;
  const created = await shell.execFile("osascript", ["-e", createScript], {
    timeoutMs: 30000,
    maxBytes: 2000,
    maxLines: 20,
    raise: true,
  });
  const playlistName = created.stdout.trim() || requestedName;
  const albumsAddedToLibrary: string[] = [];
  const albumsAlreadyInLibrary: string[] = [];
  const albumsFailed: Array<{ albumId: string; reason: string }> = [];

  const libraryProbe = async (track: CatalogTrack) => {
    const script = `tell application "Music"
set matches to search playlist "Music" for ${asAppleString(track.title)} only songs
repeat with t in matches
try
if name of t is ${asAppleString(track.title)} and artist of t is ${asAppleString(track.artist)} and album of t is ${asAppleString(track.album)} then return "yes"
end try
end repeat
return "no"
end tell`;
    const result = await shell.execFile("osascript", ["-e", script], {
      timeoutMs: 30000,
      maxBytes: 1000,
      maxLines: 10,
    });
    return result.stdout.trim() === "yes";
  };

  if (addAlbumsToLibrary) {
    const accessibility = await shell.execFile(
      "osascript",
      [
        "-e",
        `tell application "Music" to activate\ndelay 0.5\ntell application "System Events" to tell process "Music" to return count of windows`,
      ],
      { timeoutMs: 15000, maxBytes: 1000, maxLines: 10 },
    );
    if (accessibility.code !== 0)
      throw new Error(
        `Music UI automation is unavailable: ${accessibility.stderr || accessibility.stdout}`,
      );
    for (const album of resolvedAlbums) {
      if (await libraryProbe(album.tracks[0])) {
        albumsAlreadyInLibrary.push(album.albumId);
        continue;
      }
      await shell.execFile("open", ["-a", "Music", album.tracks[0].url], {
        timeoutMs: 10000,
        maxBytes: 1000,
        maxLines: 10,
        raise: true,
      });
      await new Promise((resolve) => setTimeout(resolve, 5000));
      const addScript = `tell application "Music" to activate
delay 0.2
tell application "System Events"
tell process "Music"
try
set tb to first UI element of front window whose role is "AXToolbar"
set b to first button of tb whose description is "Add to Library"
if enabled of b then
perform action "AXPress" of b
return "clicked"
end if
on error
return "not-available"
end try
return "not-available"
end tell
end tell`;
      await shell.execFile("osascript", ["-e", addScript], {
        timeoutMs: 15000,
        maxBytes: 1000,
        maxLines: 10,
      });
      let available = false;
      for (let attempt = 0; attempt < timeoutSeconds; attempt++) {
        await new Promise((resolve) => setTimeout(resolve, 1000));
        if (await libraryProbe(album.tracks[0])) {
          available = true;
          break;
        }
      }
      if (available) albumsAddedToLibrary.push(album.albumId);
      else
        albumsFailed.push({
          albumId: album.albumId,
          reason: "Album did not become available in the Music library.",
        });
    }
  }

  const records = plan
    .map(
      (track) =>
        `{${asAppleString(track.title)},${asAppleString(track.artist)},${asAppleString(track.album)}}`,
    )
    .join(",");
  const copyScript = `tell application "Music"
set p to user playlist ${asAppleString(playlistName)}
set wanted to {${records}}
set output to ""
repeat with itemRecord in wanted
set wantedTitle to item 1 of itemRecord
set wantedArtist to item 2 of itemRecord
set wantedAlbum to item 3 of itemRecord
set alreadyThere to false
repeat with existingTrack in tracks of p
try
if name of existingTrack is wantedTitle and artist of existingTrack is wantedArtist then set alreadyThere to true
end try
end repeat
if alreadyThere then
set output to output & "SKIPPED" & tab & wantedTitle & tab & wantedArtist & linefeed
else
set matches to search playlist "Music" for wantedTitle only songs
set chosenTrack to missing value
repeat with candidate in matches
try
if name of candidate is wantedTitle and artist of candidate is wantedArtist and album of candidate is wantedAlbum then
set chosenTrack to candidate
exit repeat
end if
end try
end repeat
if chosenTrack is missing value then
set output to output & "MISSING" & tab & wantedTitle & tab & wantedArtist & linefeed
else
duplicate chosenTrack to p
set output to output & "ADDED" & tab & wantedTitle & tab & wantedArtist & linefeed
end if
end if
end repeat
return output
end tell`;
  const copied = await shell.execFile("osascript", ["-e", copyScript], {
    timeoutMs: 120000,
    maxBytes: 30000,
    maxLines: 1000,
    raise: true,
  });
  const added: string[] = [];
  const skipped: string[] = [];
  const missing: string[] = [];
  for (const line of copied.stdout.split("\n")) {
    const [status, title] = line.split("\t");
    if (!title) continue;
    if (status === "ADDED") added.push(title);
    if (status === "SKIPPED") skipped.push(title);
    if (status === "MISSING") missing.push(title);
  }
  const summary = await summarizeAppleMusicPlaylist({ name: playlistName });
  return {
    dryRun: false,
    name: playlistName,
    strategy: "library",
    albumsAddedToLibrary,
    albumsAlreadyInLibrary,
    albumsFailed,
    added,
    skipped,
    missing,
    trackCount: summary.trackCount,
    uniqueTrackCount: summary.uniqueTrackCount,
    duplicateCount: summary.duplicateCount,
    duplicates: summary.duplicates,
    totalSeconds: summary.totalSeconds,
    duration: summary.duration,
  };
}

/**
 * Find representative Apple Music albums and tracks in a selected storefront.
 *
 * @pit project
 */
async function findAppleMusicCatalogAlbums(
  { http },
  input: {
    albums: Array<{ artist: string; album: string }>;
    country?: string;
    maxAlbumMatches?: number;
  },
) {
  const country = (input.country || "BR").toUpperCase();
  const maxAlbumMatches = Math.max(1, Math.min(10, input.maxAlbumMatches || 5));
  if (!input.albums?.length) throw new Error("Provide at least one artist/album query.");
  if (!/^[A-Z]{2}$/.test(country)) throw new Error("country must be a two-letter storefront code.");

  type AlbumResult = {
    collectionId: number;
    artistName: string;
    collectionName: string;
    collectionViewUrl: string;
    trackCount?: number;
    releaseDate?: string;
    primaryGenreName?: string;
  };
  type TrackResult = {
    wrapperType: string;
    collectionId?: number;
    trackId?: number;
    trackName?: string;
    artistName?: string;
    collectionName?: string;
    trackNumber?: number;
    trackTimeMillis?: number;
    trackViewUrl?: string;
  };
  const normalize = (value: string) =>
    value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();

  const searches = await Promise.all(
    input.albums.map((query) =>
      http.request(
        `https://itunes.apple.com/search?term=${encodeURIComponent(`${query.artist} ${query.album}`)}&entity=album&limit=${maxAlbumMatches}&country=${country}`,
        { maxBytes: 30000 },
      ),
    ),
  );

  const selected = input.albums.map((query, index) => {
    const body = JSON.parse(searches[index].body) as { results?: AlbumResult[] };
    const wantedArtist = normalize(query.artist);
    const wantedAlbum = normalize(query.album);
    const candidates = (body.results || [])
      .map((album) => {
        const artist = normalize(album.artistName);
        const title = normalize(album.collectionName);
        let score = 0;
        if (title === wantedAlbum) score += 8;
        else if (title.includes(wantedAlbum) || wantedAlbum.includes(title)) score += 4;
        if (artist === wantedArtist) score += 8;
        else if (artist.includes(wantedArtist) || wantedArtist.includes(artist)) score += 4;
        return { album, score };
      })
      .sort((a, b) => b.score - a.score);
    return {
      query,
      album: candidates[0]?.album || null,
      candidates: candidates.map((item) => ({ ...item.album, score: item.score })),
    };
  });

  const lookups = await Promise.allSettled(
    selected.map((item) =>
      item.album
        ? http.request(
            `https://itunes.apple.com/lookup?id=${item.album.collectionId}&entity=song&country=${country}`,
            { maxBytes: 51200 },
          )
        : Promise.reject(new Error("No album match")),
    ),
  );

  const output = [];
  for (let index = 0; index < selected.length; index++) {
    const item = selected[index];
    let tracks: TrackResult[] = [];
    const lookup = lookups[index];
    if (lookup.status === "fulfilled" && lookup.value.ok && item.album) {
      const body = JSON.parse(lookup.value.body) as { results?: TrackResult[] };
      tracks = (body.results || []).filter(
        (result) =>
          result.wrapperType === "track" && result.collectionId === item.album!.collectionId,
      );
    }
    if (!tracks.length && item.album) {
      const fallback = await http.request(
        `https://itunes.apple.com/search?term=${encodeURIComponent(`${item.album.artistName} ${item.album.collectionName}`)}&entity=song&limit=50&country=${country}`,
        { maxBytes: 51200 },
      );
      if (fallback.ok) {
        const body = JSON.parse(fallback.body) as { results?: TrackResult[] };
        tracks = (body.results || []).filter(
          (result) => result.collectionId === item.album!.collectionId,
        );
      }
    }
    output.push({
      query: item.query,
      album: item.album
        ? {
            id: item.album.collectionId,
            artist: item.album.artistName,
            title: item.album.collectionName,
            url: item.album.collectionViewUrl,
            trackCount: item.album.trackCount || tracks.length,
            releaseDate: item.album.releaseDate || null,
            genre: item.album.primaryGenreName || null,
          }
        : null,
      tracks: tracks
        .sort((a, b) => (a.trackNumber || 0) - (b.trackNumber || 0))
        .map((track) => ({
          id: track.trackId || null,
          number: track.trackNumber || null,
          title: track.trackName || "Unknown title",
          artist: track.artistName || item.album?.artistName || "Unknown artist",
          album: track.collectionName || item.album?.collectionName || "Unknown album",
          seconds: Math.round((track.trackTimeMillis || 0) / 1000),
          url: track.trackViewUrl || null,
        })),
      alternatives: item.candidates.slice(0, maxAlbumMatches),
    });
  }
  return { country, albums: output };
}

/**
 * Choose a balanced, priority-aware set of representative tracks near a target playlist duration.
 *
 * @pit project
 */
async function planBalancedAppleMusicPlaylist(
  {},
  input: {
    targetMinutes: number;
    artists: Array<{
      artist: string;
      albumUrl: string;
      tracks: Array<{
        title: string;
        seconds: number;
        priority?: number;
        required?: boolean;
        reason?: string;
      }>;
    }>;
    minTracksPerArtist?: number;
    maxTracksPerArtist?: number;
  },
) {
  if (!input.artists?.length) throw new Error("Provide at least one artist with candidate tracks.");
  if (!(input.targetMinutes > 0)) throw new Error("targetMinutes must be positive.");
  const minimum = Math.max(1, input.minTracksPerArtist || 2);
  const maximum = Math.max(minimum, Math.min(8, input.maxTracksPerArtist || 4));
  const targetSeconds = Math.round(input.targetMinutes * 60);
  const artistTarget = targetSeconds / input.artists.length;

  type Candidate = {
    title: string;
    seconds: number;
    priority: number;
    required: boolean;
    reason?: string;
  };
  type Option = { seconds: number; utility: number; fairnessPenalty: number; tracks: Candidate[] };
  const optionsByArtist: Array<{ artist: string; albumUrl: string; options: Option[] }> = [];

  for (const group of input.artists) {
    const candidates: Candidate[] = group.tracks
      .filter((track) => track.title && track.seconds > 0)
      .map((track) => ({
        ...track,
        priority: Math.max(0, Math.min(10, track.priority ?? 5)),
        required: Boolean(track.required),
      }))
      .sort((a, b) => Number(b.required) - Number(a.required) || b.priority - a.priority)
      .slice(0, 18);
    if (!candidates.length) throw new Error(`No valid tracks for ${group.artist}.`);
    const requiredCount = candidates.filter((track) => track.required).length;
    if (requiredCount > maximum)
      throw new Error(`${group.artist} has more required tracks than maxTracksPerArtist.`);
    const minSize = Math.min(candidates.length, Math.max(minimum, requiredCount));
    const maxSize = Math.min(candidates.length, maximum);
    const options: Option[] = [];

    const build = (start: number, chosen: Candidate[]) => {
      if (chosen.length >= minSize && chosen.length <= maxSize) {
        const requiredMissing = candidates.some(
          (track) => track.required && !chosen.includes(track),
        );
        if (!requiredMissing) {
          const seconds = chosen.reduce((sum, track) => sum + track.seconds, 0);
          const utility = chosen.reduce((sum, track) => sum + track.priority, 0);
          options.push({
            seconds,
            utility,
            fairnessPenalty: Math.abs(seconds - artistTarget),
            tracks: [...chosen],
          });
        }
      }
      if (chosen.length === maxSize) return;
      for (let index = start; index < candidates.length; index++) {
        chosen.push(candidates[index]);
        build(index + 1, chosen);
        chosen.pop();
      }
    };
    build(0, []);
    if (!options.length) throw new Error(`Could not build a valid selection for ${group.artist}.`);
    options.sort((a, b) => a.fairnessPenalty - a.utility * 8 - (b.fairnessPenalty - b.utility * 8));
    optionsByArtist.push({
      artist: group.artist,
      albumUrl: group.albumUrl,
      options: options.slice(0, 30),
    });
  }

  type State = { seconds: number; utility: number; fairnessPenalty: number; choices: Option[] };
  let states: State[] = [{ seconds: 0, utility: 0, fairnessPenalty: 0, choices: [] }];
  for (const group of optionsByArtist) {
    const buckets = new Map<number, State>();
    for (const state of states) {
      for (const option of group.options) {
        const next: State = {
          seconds: state.seconds + option.seconds,
          utility: state.utility + option.utility,
          fairnessPenalty: state.fairnessPenalty + option.fairnessPenalty,
          choices: [...state.choices, option],
        };
        const bucket = Math.round(next.seconds / 10);
        const previous = buckets.get(bucket);
        const quality = next.utility * 12 - next.fairnessPenalty * 0.15;
        const previousQuality = previous
          ? previous.utility * 12 - previous.fairnessPenalty * 0.15
          : -Infinity;
        if (!previous || quality > previousQuality) buckets.set(bucket, next);
      }
    }
    states = [...buckets.values()]
      .sort(
        (a, b) =>
          Math.abs(a.seconds - targetSeconds) +
          a.fairnessPenalty * 0.08 -
          a.utility * 5 -
          (Math.abs(b.seconds - targetSeconds) + b.fairnessPenalty * 0.08 - b.utility * 5),
      )
      .slice(0, 4000);
  }

  states.sort(
    (a, b) =>
      Math.abs(a.seconds - targetSeconds) +
      a.fairnessPenalty * 0.08 -
      a.utility * 5 -
      (Math.abs(b.seconds - targetSeconds) + b.fairnessPenalty * 0.08 - b.utility * 5),
  );
  const best = states[0];
  const selections = optionsByArtist.map((group, index) => ({
    artist: group.artist,
    albumUrl: group.albumUrl,
    seconds: best.choices[index].seconds,
    tracks: best.choices[index].tracks.map((track) => ({
      title: track.title,
      seconds: track.seconds,
      priority: track.priority,
      reason: track.reason || null,
    })),
  }));
  return {
    targetSeconds,
    targetDuration: `${Math.floor(targetSeconds / 3600)}:${String(Math.floor((targetSeconds % 3600) / 60)).padStart(2, "0")}:${String(targetSeconds % 60).padStart(2, "0")}`,
    totalSeconds: best.seconds,
    duration: `${Math.floor(best.seconds / 3600)}:${String(Math.floor((best.seconds % 3600) / 60)).padStart(2, "0")}:${String(best.seconds % 60).padStart(2, "0")}`,
    deltaSeconds: best.seconds - targetSeconds,
    trackCount: selections.reduce((sum, group) => sum + group.tracks.length, 0),
    selections,
    populateInput: selections.map((group) => ({
      url: group.albumUrl,
      tracks: group.tracks.map((track) => track.title),
    })),
  };
}

/**
 * Render the complete visual journal from paginated editorial entries and bounded manifest lookups, preserving current styling.
 *
 * @pit project
 */
async function renderMusicRecommendationJournal(
  { workspace, http },
  input: { country?: string } = {},
) {
  const country = (input.country || "BR").toUpperCase();
  const entries: any[] = [];
  let offset = 1;
  while (true) {
    const page = await workspace.read("data/journal.jsonl", { format: "raw", offset, limit: 1 });
    const line = page.content.trim();
    if (line) entries.push(JSON.parse(line));
    if (!page.hasMore) break;
    offset += 1;
  }
  entries.sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)));
  const manifests = await Promise.all(
    entries.map((entry) => getMusicRecommendationManifest({ manifestId: entry.manifestId })),
  );
  const byId = new Map(manifests.map((manifest) => [manifest.id, manifest]));
  const albumIds = Array.from(
    new Set(
      manifests.flatMap((manifest) =>
        manifest.tracks.map((track: any) => track.albumId).filter(Boolean),
      ),
    ),
  ) as string[];
  const artwork = new Map<string, string>();
  const chunks: string[][] = [];
  for (let i = 0; i < albumIds.length; i += 20) chunks.push(albumIds.slice(i, i + 20));
  const lookups = await Promise.allSettled(
    chunks.map((ids) =>
      http.request(`https://itunes.apple.com/lookup?id=${ids.join(",")}&country=${country}`, {
        maxBytes: 51200,
      }),
    ),
  );
  for (const lookup of lookups) {
    if (lookup.status !== "fulfilled" || !lookup.value.ok) continue;
    const body = JSON.parse(lookup.value.body) as {
      results?: Array<{ collectionId?: number; artworkUrl100?: string }>;
    };
    for (const item of body.results || [])
      if (item.collectionId && item.artworkUrl100)
        artwork.set(
          String(item.collectionId),
          item.artworkUrl100.replace("100x100bb", "600x600bb"),
        );
  }
  const esc = (value: unknown) =>
    String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  const duration = (seconds: number) =>
    `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, "0")}`;
  const longDuration = (seconds: number) =>
    `${Math.floor(seconds / 3600)}h ${String(Math.floor((seconds % 3600) / 60)).padStart(2, "0")}m`;
  const prettyDate = (value: string) =>
    new Intl.DateTimeFormat("en", {
      month: "long",
      day: "numeric",
      year: "numeric",
      timeZone: "UTC",
    }).format(new Date(value));
  const hashHue = (value: string) =>
    [...value].reduce((sum, char) => (sum * 31 + char.charCodeAt(0)) % 360, 0);
  const wiki = (artist: string) =>
    `https://en.wikipedia.org/wiki/Special:Search?search=${encodeURIComponent(artist)}`;
  let artistCardCount = 0;
  const articles = entries
    .map((entry, entryIndex) => {
      const manifest = byId.get(entry.manifestId);
      if (!manifest) return "";
      const grouped = new Map<string, any[]>();
      for (const track of manifest.tracks)
        grouped.set(track.artist, [...(grouped.get(track.artist) || []), track]);
      const notes = new Map((entry.artistNotes || []).map((note: any) => [note.artist, note]));
      const artists = [...grouped.entries()];
      artistCardCount += artists.length;
      const cards = artists
        .map(([artist, tracks], index) => {
          const note: any = notes.get(artist) || {};
          const first = tracks[0];
          const art = first.albumId ? artwork.get(String(first.albumId)) : null;
          const rows = tracks
            .map(
              (track: any) =>
                `<li><a href="${esc(track.albumUrl || "#")}" target="_blank" rel="noreferrer"><span>${esc(track.title)}</span><time>${duration(track.durationSeconds)}</time></a></li>`,
            )
            .join("");
          return `<section class="artist-card" style="--h:${hashHue(artist)}"><div class="cover-wrap">${art ? `<img src="${esc(art)}" alt="Cover of ${esc(first.album)}" loading="lazy">` : `<div class="cover-fallback">${esc(artist.slice(0, 1))}</div>`}<span class="card-number">${String(index + 1).padStart(2, "0")}</span></div><div class="artist-copy"><p class="album-label">${esc(first.album)}</p><h3><a href="${esc(wiki(artist))}" target="_blank" rel="noreferrer" title="Read about ${esc(artist)} on Wikipedia">${esc(artist)} <span aria-hidden="true">↗</span></a></h3><p class="why">${esc(note.why || first.reason || "Selected as a representative next step from your recent listening.")}</p>${note.connections ? `<p class="connection"><strong>Connection</strong> ${esc(note.connections)}</p>` : ""}${note.selectionNote ? `<p class="selection"><strong>Why these tracks</strong> ${esc(note.selectionNote)}</p>` : ""}<ol class="track-list">${rows}</ol></div></section>`;
        })
        .join("");
      const seconds = manifest.tracks.reduce(
        (sum: number, track: any) => sum + track.durationSeconds,
        0,
      );
      return `<article class="entry" id="${esc(entry.manifestId)}"><header class="entry-head"><div class="date-stamp"><span>${prettyDate(entry.publishedAt)}</span><i></i></div><p class="kicker">Entry ${String(entries.length - entryIndex).padStart(2, "0")} · ${esc(manifest.playlist)}</p><h2>${esc(entry.headline)}</h2><p class="intro">${esc(entry.intro)}</p><div class="entry-meta"><span>${manifest.tracks.length} tracks</span><span>${grouped.size} artists</span><span>${longDuration(seconds)}</span></div>${(entry.tags || []).length ? `<div class="tags">${entry.tags.map((tag: string) => `<span>${esc(tag)}</span>`).join("")}</div>` : ""}${entry.narrative ? `<div class="narrative"><span>Field notes</span><p>${esc(entry.narrative)}</p></div>` : ""}</header><div class="artist-grid">${cards}</div></article>`;
    })
    .join("\n");
  const existing = await workspace
    .read("site/index.html", { format: "raw", offset: 1, limit: 5 })
    .catch(() => null);
  const style =
    existing?.content.match(/<style>([\s\S]*?)<\/style>/)?.[1] ||
    `:root{color-scheme:dark}body{margin:2rem;background:#111;color:#eee;font-family:system-ui}.artist-grid{display:grid;gap:1rem}.artist-card{border:1px solid #444;padding:1rem}a{color:inherit}`;
  const totalTracks = manifests.reduce((sum, manifest) => sum + manifest.tracks.length, 0);
  const totalSeconds = manifests.reduce(
    (sum, manifest) =>
      sum + manifest.tracks.reduce((s: number, t: any) => s + t.durationSeconds, 0),
    0,
  );
  const uniqueArtists = new Set(
    manifests.flatMap((manifest) => manifest.tracks.map((track: any) => track.artist)),
  ).size;
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Listening Notes · Music Recommendations</title><style>${style}</style></head><body><main class="shell"><header class="hero"><p class="eyebrow">A private recommendation journal</p><h1>Listening Notes</h1><p class="hero-copy">A growing field guide to the records, scenes, collaborators and musical detours worth hearing next.</p><div class="stats"><div><strong>${entries.length}</strong> entries</div><div><strong>${totalTracks}</strong> tracks</div><div><strong>${uniqueArtists}</strong> artists</div><div><strong>${longDuration(totalSeconds)}</strong> queued</div></div></header>${articles}<footer><span>Generated from versioned recommendation manifests.</span><span>Last updated ${prettyDate(new Date().toISOString())}</span></footer></main></body></html>`;
  const site = await workspace
    .read("site/index.html", { format: "raw", offset: 1, limit: 1 })
    .catch(() => null);
  await workspace.edit("site/index.html", {
    revision: site?.revision || null,
    changes: [{ kind: "replaceFile", content: html }],
  });
  return {
    sitePath: "site/index.html",
    entries: entries.length,
    artistCards: artistCardCount,
    trackLinks: totalTracks,
    wikipediaLinks: artistCardCount,
    bytes: html.length,
    complete: html.endsWith("</html>"),
  };
}

/**
 * Validate the generated listening journal, copy it to the sibling public-site repository, commit only music/index.html, and optionally push master.
 *
 * @pit project
 */
async function publishMusicJournalSite(
  { shell, git },
  input: { commitMessage?: string; push?: boolean; dryRun?: boolean } = {},
) {
  const repositoryPath = "../cv.github.io";
  const sourcePath = "site/index.html";
  const destinationPath = "music/index.html";
  const expectedRemote = "git@github.com:cv/cv.github.io.git";
  const validationScript = `import json\nfrom html.parser import HTMLParser\nfrom pathlib import Path\ns=Path('site/index.html').read_text(encoding='utf-8')\nHTMLParser().feed(s)\nentries=s.count('class=\"entry\"')\ncards=s.count('class=\"artist-card\"')\ntracks=s.count('<li><a href=')\nlinks=s.count('wikipedia.org/wiki/Special:Search')\nif not s.rstrip().endswith('</html>'): raise SystemExit('journal HTML is incomplete')\nif entries<1 or cards<1 or tracks<1: raise SystemExit('journal HTML has no rendered content')\nrows=[json.loads(line) for line in Path('data/journal.jsonl').read_text(encoding='utf-8').splitlines() if line]\nlatest=max(rows,key=lambda row:str(row.get('publishedAt','')))\nprint(json.dumps({'bytes':len(s.encode()),'entries':entries,'artistCards':cards,'trackLinks':tracks,'wikipediaLinks':links,'latestHeadline':latest.get('headline','Listening Notes')}))`;
  const [validationResult, statusBefore, branch, remote, comparison] = await Promise.all([
    shell.execFile("/usr/bin/python3", ["-c", validationScript], {
      timeoutMs: 30000,
      maxBytes: 3000,
      maxLines: 20,
      raise: true,
    }),
    git.status(["--short"], { cwd: repositoryPath }),
    shell.execFile("git", ["branch", "--show-current"], {
      cwd: repositoryPath,
      maxBytes: 1000,
      maxLines: 10,
      raise: true,
    }),
    shell.execFile("git", ["remote", "get-url", "origin"], {
      cwd: repositoryPath,
      maxBytes: 2000,
      maxLines: 10,
      raise: true,
    }),
    shell.execFile("cmp", ["-s", sourcePath, `${repositoryPath}/${destinationPath}`], {
      maxBytes: 1000,
      maxLines: 10,
    }),
  ]);
  const validation = JSON.parse(validationResult.stdout) as {
    bytes: number;
    entries: number;
    artistCards: number;
    trackLinks: number;
    wikipediaLinks: number;
    latestHeadline: string;
  };
  if (statusBefore.stdout.trim())
    throw new Error(
      `Publication repository must be clean before publishing:\n${statusBefore.stdout}`,
    );
  if (branch.stdout.trim() !== "master")
    throw new Error(`Expected publication branch master; found ${branch.stdout.trim()}`);
  if (remote.stdout.trim() !== expectedRemote)
    throw new Error(`Unexpected publication remote: ${remote.stdout.trim()}`);
  const changed = comparison.code !== 0;
  const commitMessage =
    input.commitMessage?.trim() || `music: publish ${validation.latestHeadline}`;
  if (input.dryRun)
    return {
      dryRun: true,
      changed,
      push: input.push !== false,
      repositoryPath,
      destinationPath,
      commitMessage,
      validation,
    };
  if (!changed)
    return {
      dryRun: false,
      changed: false,
      pushed: false,
      repositoryPath,
      destinationPath,
      validation,
    };
  await shell.execFile("cp", [sourcePath, `${repositoryPath}/${destinationPath}`], {
    timeoutMs: 30000,
    maxBytes: 1000,
    maxLines: 10,
    raise: true,
  });
  const copiedStatus = await git.status(["--short"], { cwd: repositoryPath });
  const changedPaths = copiedStatus.stdout
    .split("\n")
    .filter(Boolean)
    .map((line) => line.slice(3));
  if (changedPaths.length !== 1 || changedPaths[0] !== destinationPath)
    throw new Error(`Copy changed unexpected publication files:\n${copiedStatus.stdout}`);
  await git.add([destinationPath], { cwd: repositoryPath });
  const commit = await git.commit(["-m", commitMessage], { cwd: repositoryPath });
  let pushResult: null | { stdout: string; stderr: string; code: number; truncated: boolean } =
    null;
  if (input.push !== false)
    pushResult = await git.push(["origin", "master"], { cwd: repositoryPath });
  const [statusAfter, log] = await Promise.all([
    git.status(["--short", "--branch"], { cwd: repositoryPath }),
    git.log(["-1", "--oneline"], { cwd: repositoryPath }),
  ]);
  return {
    dryRun: false,
    changed: true,
    pushed: input.push !== false,
    repositoryPath,
    destinationPath,
    commitMessage,
    validation,
    commit,
    push: pushResult,
    status: statusAfter,
    log,
  };
}

