async function findAppleMusicTrackAlternatives(
  { http },
  input: {
    tracks: Array<{ artist: string; title: string; seconds?: number }>;
    country?: string;
    maxResultsPerTrack?: number;
  },
) {
  if (!input.tracks?.length) throw new Error("Provide at least one artist/title pair.");
  const country = (input.country || "BR").toUpperCase();
  const limit = Math.max(1, Math.min(10, input.maxResultsPerTrack || 5));
  const normalize = (value: string) =>
    value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
  const responses = await Promise.all(
    input.tracks.map((track) =>
      http.request(
        `https://itunes.apple.com/search?term=${encodeURIComponent(`${track.artist} ${track.title}`)}&entity=song&limit=25&country=${country}`,
        { maxBytes: 50000 },
      ),
    ),
  );
  const results = input.tracks.map((wanted, index) => {
    const body = JSON.parse(responses[index].body) as {
      results?: Array<{
        trackId?: number;
        trackName?: string;
        artistName?: string;
        collectionId?: number;
        collectionName?: string;
        trackTimeMillis?: number;
        trackViewUrl?: string;
        collectionViewUrl?: string;
      }>;
    };
    const wantedTitle = normalize(wanted.title);
    const wantedArtist = normalize(wanted.artist);
    const seen = new Set<string>();
    const candidates = (body.results || [])
      .map((item) => {
        const title = normalize(item.trackName || "");
        const artist = normalize(item.artistName || "");
        const seconds = Math.round((item.trackTimeMillis || 0) / 1000);
        let score = 0;
        if (title === wantedTitle) score += 20;
        else if (title.includes(wantedTitle) || wantedTitle.includes(title)) score += 8;
        if (artist === wantedArtist) score += 12;
        else if (artist.includes(wantedArtist) || wantedArtist.includes(artist)) score += 5;
        if (wanted.seconds != null) score -= Math.min(10, Math.abs(seconds - wanted.seconds) / 5);
        return {
          score,
          trackId: item.trackId || null,
          title: item.trackName || "",
          artist: item.artistName || "",
          albumId: item.collectionId || null,
          album: item.collectionName || "",
          seconds,
          trackUrl: item.trackViewUrl || null,
          albumUrl: item.collectionViewUrl || null,
          durationDelta: wanted.seconds != null ? seconds - wanted.seconds : null,
        };
      })
      .filter((item) => item.score >= 20 && item.albumId && item.trackUrl)
      .sort(
        (a, b) =>
          b.score - a.score || Math.abs(a.durationDelta || 0) - Math.abs(b.durationDelta || 0),
      )
      .filter((item) => {
        const key = `${item.albumId}\u0000${item.trackId}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      })
      .slice(0, limit)
      .map(({ score: _score, ...item }) => item);
    return { requested: wanted, alternatives: candidates };
  });
  return { country, results };
}

